window.__HSK_CHAPTER_DATA__['chapter_01'] = [{"meanings_summary": {"en": "details; particulars; minor points", "es": "detalles; pormenores; minucias"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Examine every fine silk thread (细) tied at each bamboo joint (节) to grasp the true details.", "composite_memory_hook_es": "Examina cada fino hilo de seda (细) atado en cada nudo de bambú (节) para comprender los verdaderos detalles.", "cultural_and_cognitive_roots": "Traditional Chinese philosophy posits that wholeness emerges from the disciplined harmony of micro-units; 'xì' (fine thread) and 'jié' (bamboo joint) signify that elegance resides in flawless joints.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 51-35 pitch contour (4th tone falling sharply, followed by 2nd tone rising cleanly). Do not truncate the rising contour of jié."}, "semantic_boundary_contrasts": {"core_nuance": "细节 refers specifically to concrete micro-components, particulars, or subtle nuances embedded within a whole entity or situation.", "contrasts": [{"id": "1", "compared_word": "细节 vs. 详细", "pinyin": "xiángxì", "analysis": "细节 is a noun referring to the discrete facts or structural particulars, whereas 详细 is an adjective meaning thorough, detailed, or exhaustive in explanation."}, {"id": "2", "compared_word": "细节 vs. 环节", "pinyin": "huánjié", "analysis": "细节 denotes static individual elements or subtle touches, while 环节 represents a vital link, stage, or operational phase within a sequential process."}, {"id": "3", "compared_word": "细节 vs. 情节", "pinyin": "qíngjié", "analysis": "细节 applies broadly to any physical, technical, or behavioural detail, whereas 情节 is restricted to narrative plots, storylines, or dramatic sequences."}]}, "traps_and_cognates": {"look_alikes": [{"character": "粗", "pinyin": "cū", "meaning_en": "coarse; rough", "distinction_note": "Has radical 米 (rice) instead of 纟 (silk); semantically its direct antonym", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/lookalike_粗_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/lookalike_粗_office_man.mp3"}}, {"character": "组", "pinyin": "zǔ", "meaning_en": "group; organize", "distinction_note": "Shares radical 纟 but has 且 on the right instead of 田", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/lookalike_组_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/lookalike_组_office_man.mp3"}}, {"character": "符", "pinyin": "fú", "meaning_en": "tally; symbol", "distinction_note": "Has bamboo radical 竹 over 付; unrelated to 节", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/lookalike_符_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/lookalike_符_office_man.mp3"}}, {"character": "爷", "pinyin": "yé", "meaning_en": "grandfather; lord", "distinction_note": "Has top radical 父; distinct lower structure from 节", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/lookalike_爷_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/lookalike_爷_office_man.mp3"}}], "etymological_cognates": [{"character": "丝", "pinyin": "sī", "gloss_en": "silk; minute thread", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/cognate_丝_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/cognate_丝_office_man.mp3"}}, {"character": "幼", "pinyin": "yòu", "gloss_en": "infant; tender micro-growth", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/cognate_幼_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/cognate_幼_office_man.mp3"}}, {"character": "竹", "pinyin": "zhú", "gloss_en": "bamboo; parent radical of traditional 節", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/cognate_竹_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/cognate_竹_office_man.mp3"}}, {"character": "阶", "pinyin": "jiē", "gloss_en": "steps; discrete levels", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/cognate_阶_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/cognate_阶_office_man.mp3"}}]}, "id": "1", "hanzi": "细节", "pinyin": "xì jié", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "details; minute aspects; particulars of an event or object", "definition_es": "detalles; aspectos minuciosos; pormenores de un hecho u objeto", "example_phrase": "注意细节 (pay attention to details)"}], "example_sentences": [{"id": "#1", "hanzi": "老艺术家的画作细腻生动，连花瓣上的露珠这种细节都被表现得惟妙惟肖。", "pinyin": "Lǎo yìshùjiā de huàzuò xìnì shēngdòng, lián huābàn shàng de lùzhū zhè zhǒng xìjié dōu bèi biǎoxiàn de wéimiàowéixiào.", "en": "The veteran artist's paintings are exquisite and vivid; even such details as dew on petals are depicted to perfection.", "es": "Las pinturas del veterano artista son exquisitas y vivaces; incluso detalles como el rocío en los pétalos están plasmados a la perfección.", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/sentence_1_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/sentence_1_office_man.mp3"}}, {"id": "#2", "hanzi": "在复杂的外交谈判中，代表团对协议文本的每一处细节都进行了反复推敲和严谨确认。", "pinyin": "Zài fùzá de wàijiāo tánpàn zhōng, dàibiǎotuán duì xiéyì wénběn de měi yí chù xìjié dōu jìnxíng le fǎnfù tuīqiāo hé yánjǐn quèrèn.", "en": "In complex diplomatic negotiations, the delegation repeatedly scrutinized and rigorously confirmed every detail of the agreement text.", "es": "En las complejas negociaciones diplomáticas, la delegación examinó minuciosamente y confirmó con rigor cada detalle del texto del acuerdo.", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/sentence_2_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/sentence_2_office_man.mp3"}}], "collocations": [{"hanzi": "注意细节", "en": "pay attention to details", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/collocation_1_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/collocation_1_office_man.mp3"}}, {"hanzi": "忽略细节", "en": "overlook details", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/collocation_2_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/collocation_2_office_man.mp3"}}, {"hanzi": "具体细节", "en": "specific details", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/collocation_3_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/collocation_3_office_man.mp3"}}, {"hanzi": "技术细节", "en": "technical details", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/collocation_4_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/collocation_4_office_man.mp3"}}, {"hanzi": "细节决定成败", "en": "details determine success or failure", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/collocation_5_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/collocation_5_office_man.mp3"}}, {"hanzi": "丰富细节", "en": "enrich the details", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/collocation_6_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/collocation_6_office_man.mp3"}}], "idioms": [{"hanzi": "不拘小节", "pinyin": "bù jū xiǎo jié", "meaning_en": "not bother about trifles; not adhere strictly to trivial rules", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/idiom_1_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/idiom_1_office_man.mp3"}}, {"hanzi": "细水长流", "pinyin": "xì shuǐ cháng liú", "meaning_en": "a fine stream flows long; economize to ensure long-term sustainability", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/idiom_2_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/idiom_2_office_man.mp3"}}, {"hanzi": "节衣缩食", "pinyin": "jié yī suō shí", "meaning_en": "live frugally; practice strict economy in clothing and food", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/idiom_3_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/idiom_3_office_man.mp3"}}, {"hanzi": "明察秋毫", "pinyin": "míng chá qiū háo", "meaning_en": "perceive the finest detail; see clearly down to an autumn hair", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/idiom_4_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/idiom_4_office_man.mp3"}}], "character_decomposition": [{"character": "细", "pinyin": "xì", "meaning_en": "fine; thin; meticulous", "meaning_es": "fino; delgado; meticuloso", "radical": "纟", "radical_meaning_en": "silk", "meaning_component": "纟 (silk, suggesting fine threads)", "sound_component": "田 (tián, phonetic harmony)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where silk radical indicates delicate spun fiber.", "visual_mnemonic_story_en": "A silken thread (纟) stretched across an open rice field (田) is so fine it captures the tiniest dew drops.", "visual_mnemonic_story_es": "Un hilo de seda (纟) tendido sobre un campo de arroz (田) es tan fino que atrapa las gotas más diminutas.", "tone_mnemonic_anchor": "51", "cangjie": "VMW", "traditional": "細", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/char_细_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/char_细_office_man.mp3"}}, {"character": "节", "pinyin": "jié", "meaning_en": "joint; node; segment; moderation", "meaning_es": "nudo; articulación; segmento; moderación", "radical": "艸", "radical_meaning_en": "grass", "meaning_component": "艸 (grass, derived from bamboo nodes)", "sound_component": "卩 (jié, simplified form marker)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Originally written with bamboo radical 節 indicating the distinct nodes dividing bamboo into measured sections.", "visual_mnemonic_story_en": "Sprouts of vegetation (艹) growing up to a seal (卩) mark the measured seasonal breaks of a stem.", "visual_mnemonic_story_es": "Brotes de hierba (艹) que crecen junto a un sello (卩) marcan las secciones medidas del tallo.", "tone_mnemonic_anchor": "35", "cangjie": "TSL", "traditional": "節", "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/char_节_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/char_节_office_man.mp3"}}], "extended_reading_passages": [{"id": "#1", "hanzi": "生活的美好往往隐藏在那些不被注意的细节之中。清晨桌案上一杯温热的红茶，窗台前一盆悄然绽放的花，都在静默中诉说着温度。懂得捕捉细节的人，才能在平凡岁月中体会生命的温润。", "pinyin": "Shēnghuó de měihǎo wǎngwǎng yǐncáng zài nàxiē bú bèi zhùyì de xìjié zhīzhōng. Qīngchén zhuō'àn shàng yì bēi wēnrè de hóngchá, chuāngtái qián yì pén qiǎorán zhànfàng de huā, dōu zài jìngmò zhōng sùshuō zhe wēndù. Dǒngdé bǔzhuō xìjié de rén, cáinǐng zài píngfán suìyuè zhōng tǐhuì shēngmìng de wēnrùn.", "en": "The beauty of life often hides within unnoticed details. A warm cup of black tea on the morning desk and a flower quietly blooming by the window silently convey warmth. Only those who know how to capture details can savor life's gentle grace in ordinary days.", "es": "La belleza de la vida a menudo se oculta en aquellos detalles que pasan desapercibidos. Una taza de té tibio sobre la mesa matutina y una flor que florece en silencio junto a la ventana expresan calidez. Solo quien sabe apreciar los detalles logra percibir la ternura de la existencia."}, {"id": "#2", "hanzi": "制造业的竞争力正转向精密制造。在高端装备与半导体产业中，公差控制的微米级细节往往决定了整体性能与良品率。国际标准对生产细节的严苛要求，倒逼企业建立全生命周期的精细化管理体系。", "pinyin": "Zhìzàoyè de jìngzhēnglì zhèng zhuǎnxiàng jīngmì zhìzào. Zài gāoduān zhuāngbèi yǔ bàndǎotǐ chǎnyè zhōng, gōngchā kòngzhì de wēimǐ jí xìjié wǎngwǎng juédìng le zhěngtǐ xìngnéng yǔ liángpǐnlǜ. Guójì biāozhǔn duì shēngchǎn xìjié de yánkē yāoqiú, dàobī qǐyè jiànlì quán shēngmìng zhōuqī de jīngxìhuà guǎnlǐ tǐxì.", "en": "Manufacturing competitiveness is shifting toward precision engineering. In high-end equipment and semiconductor sectors, micron-level tolerance details often determine overall performance and yield. Stringent international standards on production details compel enterprises to establish lifecycle refined management systems.", "es": "La competitividad manufacturera evoluciona hacia la ingeniería de precisión. En equipos avanzados y semiconductores, los detalles de tolerancia micrométrica determinan el rendimiento y la calidad. Las exigentes normas internacionales sobre detalles productivos obligan a implantar una gestión refinada integral."}], "audio": {"mature_woman": "chapters/chapter_01/audio/01_细节/headword_mature_woman.mp3", "office_man": "chapters/chapter_01/audio/01_细节/headword_office_man.mp3"}}, {"meanings_summary": {"en": "radio station; broadcasting station; transceiver station", "es": "emisora de radio; estación de radio; radiotransmisor"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Harnessing electric lightning waves (电) on an elevated broadcast platform (台) creates a radio station.", "composite_memory_hook_es": "Aprovechar las ondas eléctricas (电) sobre una plataforma elevada (台) da vida a una emisora de radio.", "cultural_and_cognitive_roots": "Early 20th-century Chinese modernization combined 'diàn' (lightning/electricity) with 'tái' (high terrace or altar), conceptualizing mass radio broadcasting as an elevated electric stage beaming voices into every household.", "tone_sandhi_and_pitch_modulation": "51-35 pitch contour (4th tone falling sharp, 2nd tone rising smooth). Avoid neutralizing the second syllable into a light tone."}, "semantic_boundary_contrasts": {"core_nuance": "电台 specifically denotes a radio transmission station or apparatus that broadcasts voice and acoustic signals over electromagnetic airwaves.", "contrasts": [{"id": "1", "compared_word": "电台 vs. 电视台", "pinyin": "diànshìtái", "analysis": "电台 broadcasts purely auditory content over radio frequencies, whereas 电视台 produces and broadcasts audio-visual television programming."}, {"id": "2", "compared_word": "电台 vs. 广播", "pinyin": "guǎngbō", "analysis": "电台 is the institutional facility, organization, or physical station, while 广播 refers to the medium or action of broadcasting audio signals."}, {"id": "3", "compared_word": "电台 vs. 报社", "pinyin": "bàoshè", "analysis": "电台 is an electronic audio broadcasting institution, whereas 报社 is a print or digital newspaper publishing house."}]}, "traps_and_cognates": {"look_alikes": [{"character": "申", "pinyin": "shēn", "meaning_en": "express; state", "distinction_note": "Vertical stroke extends through both top and bottom, unlike 电"}, {"character": "甲", "pinyin": "jiǎ", "meaning_en": "first; armor", "distinction_note": "Vertical stroke extends only downward from 田, unlike 电 which curls"}, {"character": "合", "pinyin": "hé", "meaning_en": "combine; join", "distinction_note": "Has roof 人/一 on top instead of 厶; distinct from 台"}, {"character": "苔", "pinyin": "tái", "meaning_en": "moss", "distinction_note": "Has grass radical 艹 above 台; refers to botanical moss"}], "etymological_cognates": [{"character": "雷", "pinyin": "léi", "gloss_en": "thunder; shares rain/storm root with traditional 電"}, {"character": "震", "pinyin": "zhèn", "gloss_en": "shock; quake; meteorological family"}, {"character": "坛", "pinyin": "tán", "gloss_en": "altar; elevated platform"}, {"character": "基", "pinyin": "jī", "gloss_en": "base; foundation stage"}]}, "id": "2", "hanzi": "电台", "pinyin": "diàn tái", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "radio broadcasting station; transceiver apparatus", "definition_es": "estación de radiodifusión; aparato transmisor y receptor de radio", "example_phrase": "收听电台 (listen to the radio station)"}], "example_sentences": [{"id": "#1", "hanzi": "每当深夜开车行驶在空旷的高速公路上，我总习惯打开车载广播，收听音乐电台的经典老歌。", "pinyin": "Měidāng shēnyè kāichē xíngshǐ zài kōngkuàng de gāosù gōnglù shàng, wǒ zǒng xíguàn dǎkāi chēzài guǎngbō, shōutīng yīnyuè diàntái de jīngdiǎn lǎogē.", "en": "Whenever I drive on the empty highway late at night, I am accustomed to turning on the car radio to listen to classics on the music station.", "es": "Cada vez que conduzco de noche por la autopista despejada, suelo encender la radio del coche para escuchar canciones clásicas en la emisora musical."}, {"id": "#2", "hanzi": "在发生重大自然灾害导致移动通信网络中断时，民用无线电台成了灾区与外界取得联系的关键通道。", "pinyin": "Zài fāshēng zhòngdà zìrán zāihài dǎozhì yídòng tōngxìn wǎngluò zhōngduàn shí, mínyòng wúxiàndiàn diàntái chéng le zāiqū yǔ wàijiè qǔdé liánxì de guānjiàn tōngdào.", "en": "When a major natural disaster cuts off cellular networks, civilian radio transceiver stations become the crucial channel connecting the disaster area with the outside world.", "es": "Cuando un gran desastre natural interrumpe las redes móviles, las estaciones de radiotransmisión civil se convierten en el canal decisivo para comunicar la zona afectada con el exterior."}], "collocations": [{"hanzi": "广播电台", "en": "radio broadcasting station"}, {"hanzi": "收听电台", "en": "listen to a radio station"}, {"hanzi": "地方电台", "en": "local radio station"}, {"hanzi": "无线电台", "en": "wireless transceiver station"}, {"hanzi": "电台主持人", "en": "radio show host"}, {"hanzi": "电台频率", "en": "radio station frequency"}], "idioms": [{"hanzi": "风驰电掣", "pinyin": "fēng chí diàn chè", "meaning_en": "swift as the wind and quick as lightning"}, {"hanzi": "雷电交加", "pinyin": "léi diàn jiāo jiā", "meaning_en": "lightning accompanied by thunder; severe storms"}, {"hanzi": "电光石火", "pinyin": "diàn guāng shí huǒ", "meaning_en": "lightning flash and spark of flint; in a flash"}, {"hanzi": "登台亮相", "pinyin": "dēng tái liàng xiàng", "meaning_en": "mount the stage and make an appearance"}], "character_decomposition": [{"character": "电", "pinyin": "diàn", "meaning_en": "electricity; lightning", "meaning_es": "electricidad; rayo", "radical": "田", "radical_meaning_en": "field", "meaning_component": "田 (field / cloud matrix)", "sound_component": "乚 (lightning bolt curving downwards)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "Originally depicted a flash of lightning bursting through rain clouds.", "visual_mnemonic_story_en": "Sun and clouds overhead (日) discharge a bright curved bolt of lightning (乚) onto the land.", "visual_mnemonic_story_es": "El sol y las nubes (日) descargan un rayo curvo y luminoso (乚) sobre la tierra.", "tone_mnemonic_anchor": "51", "cangjie": "LWU", "traditional": "電"}, {"character": "台", "pinyin": "tái", "meaning_en": "platform; stage; station", "meaning_es": "plataforma; escenario; estación", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (mouth, speaking or commanding)", "sound_component": "厶 (sī, phonetic marker)", "stroke_count": "5", "composition_type": "上下结构", "etymology_and_mnemonic": "Simplification conflating 台 (elevated structure/terrace) and 臺 (watchtower).", "visual_mnemonic_story_en": "A speaker stands on a private platform (厶) projecting announcements through a megaphone mouth (口).", "visual_mnemonic_story_es": "Un locutor se para sobre una plataforma elevada (厶) y transmite su mensaje a través de la boca (口).", "tone_mnemonic_anchor": "35", "cangjie": "IR", "traditional": "臺"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在收音机普及的岁月里，电台播音曾陪伴了一代人的青春。每当夜幕降临，主持人温和的声音穿透黑暗，抚慰着无数孤独的心灵。电台用电波架起了一座温暖之桥。", "pinyin": "Zài shōuyīnjī pǔjí de suìyuè lǐ, diàntái bōyīn céng péibàn le yí dài rén de qīngchūn. Měidāng yèmù jiànglín, zhǔchírén wēnhé de shēngyīn chuāntòu hēi'àn, fǔwèi zhe wúshù gūdú de xīnlíng. Diàntái yòng diànbō jiàqǐ le yí zuò wēnnuǎn zhī qiáo.", "en": "In the days when radios were widespread, radio broadcasts accompanied a generation's youth. As night fell, the host's gentle voice pierced the darkness, comforting lonely hearts. The station built a bridge of warmth with radio waves.", "es": "En la época en que la radio era común, sus emisiones acompañaron a toda una generación. Al caer la noche, la voz serena del locutor atravesaba la penumbra, reconfortando corazones solitarios y tendiendo un puente de calidez."}, {"id": "#2", "hanzi": "随着融媒体时代的发展，传统广播电台正加快数字化转型步伐。许多电台进军音频客户端与网络播客，重构交互式内容生态，不仅拓宽了受众边界，更提升了现代公共传媒的传播实效。", "pinyin": "Suízhe róng méitǐ shídài de fāzhǎn, chuántǒng guǎngbō diàntái zhèng jiākuài shùzìhuà zhuǎnxíng bùfá. Xǔduō diàntái jìnjūn yīnpín kèhùduān yǔ wǎngluò bōkè, zhònggòu jiāohùshì nèiróng shēngtài, bùjǐn tuòkuān le shòuzhòng biānjiè, gèng tíshēng le xiàndài gōnggòng chuánméi de chuánbō shíxiào.", "en": "With the development of media convergence, traditional radio stations are accelerating digital transformation. Many stations enter audio apps and podcasts to reshape interactive ecosystems, broadening audiences and improving public communication.", "es": "Con el avance de la convergencia de medios, las emisoras tradicionales aceleran su digitalización. Al incursionar en aplicaciones y podcasts, reconstruyen un ecosistema interactivo que amplía audiencias y optimiza la comunicación pública."}]}, {"meanings_summary": {"en": "(of husband and wife) affectionate; loving; deeply devoted", "es": "(entre cónyuges) cariñoso; amoroso; profundamente afectuoso"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Mutual kindness and lifelong grace (恩) combined with passionate tenderness (爱) define marital devotion.", "composite_memory_hook_es": "La bondad mutua y la gratitud compartida (恩) unidas a la ternura sincera (爱) definen el amor conyugal.", "cultural_and_cognitive_roots": "In Chinese marital ethics, romantic passion alone is fragile; true matrimonial harmony requires 'ēn' (benevolence, mutual obligation, and shared loyalty) alongside 'ài' (emotional affection). Hence, conjugal love is conceived as moral and emotional reciprocity.", "tone_sandhi_and_pitch_modulation": "55-51 pitch contour (1st tone high level at 55, smoothly sliding into 4th tone falling from 5 to 1). Note the glottal onset or smooth liaison between ēn and ài."}, "semantic_boundary_contrasts": {"core_nuance": "恩爱 specifically characterizes reciprocal tenderness, devotion, and moral-emotional bonding between spouses.", "contrasts": [{"id": "1", "compared_word": "恩爱 vs. 相爱", "pinyin": "xiāng'ài", "analysis": "恩爱 is strictly used to describe married couples possessing enduring mutual care, whereas 相爱 can refer broadly to lovers, partners, or people falling in love at any relationship stage."}, {"id": "2", "compared_word": "恩爱 vs. 亲热", "pinyin": "qīnrè", "analysis": "恩爱 denotes deep emotional and spiritual harmony in marriage, while 亲热 emphasizes overtly affectionate, warm, or physically intimate behaviour between friends or partners."}, {"id": "3", "compared_word": "恩爱 vs. 关爱", "pinyin": "guān'ài", "analysis": "恩爱 describes mutual spousal devotion, while 关爱 is a transitive verb/noun referring to caring for and looking after elders, children, subordinates, or the vulnerable."}]}, "traps_and_cognates": {"look_alikes": [{"character": "思", "pinyin": "sī", "meaning_en": "think; consider", "distinction_note": "Features 田 (field) over 心 (heart) instead of 因 (cause)"}, {"character": "受", "pinyin": "shòu", "meaning_en": "receive; endure", "distinction_note": "Lacks the top stroke and has 又 at the bottom; distinct from 爱"}, {"character": "妥", "pinyin": "tuǒ", "meaning_en": "appropriate; settled", "distinction_note": "Features 女 (woman) below 爫 instead of 友"}, {"character": "息", "pinyin": "xī", "meaning_en": "breath; rest", "distinction_note": "Has 自 (nose/self) above 心 instead of 因"}], "etymological_cognates": [{"character": "因", "pinyin": "yīn", "gloss_en": "cause; reason; phonetic matrix for 恩"}, {"character": "德", "pinyin": "dé", "gloss_en": "virtue; moral grace sharing heart radical"}, {"character": "友", "pinyin": "yǒu", "gloss_en": "friend; companion component of simplified 爱"}, {"character": "慈", "pinyin": "cí", "gloss_en": "compassionate; merciful love"}]}, "id": "3", "hanzi": "恩爱", "pinyin": "ēn ài", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "mutually loving and deeply affectionate (specifically used for married couples)", "definition_es": "afectuoso y enamorado recíprocamente (empleado en particular para parejas de cónyuges)", "example_phrase": "夫妻恩爱 (affectionate married couple)"}], "example_sentences": [{"id": "#1", "hanzi": "爷爷奶奶结婚五十年了，日常生活中互敬互助，街坊邻里都羡慕他们十分恩爱。", "pinyin": "Yéye nǎinai jiéhūn wǔshí nián le, rìcháng shēnghuó zhōng hù jìng hù zhù, jiēfang línlǐ dōu xiànmù tāmen shífēn ēn'ài.", "en": "Grandpa and grandma have been married for fifty years; they respect and help each other daily, and all the neighbors admire how deeply affectionate they are.", "es": "El abuelo y la abuela llevan cincuenta años casados; se respetan y ayudan mutuamente cada día, y todos los vecinos admiran lo cariñosos y unidos que son."}, {"id": "#2", "hanzi": "家庭社会学调研显示，夫妻恩爱且沟通顺畅的家庭环境，对于未成年子女健全人格的塑造具有决定性影响。", "pinyin": "Jiātíng shèhuìxué diàoyán xiǎnshì, fūqī ēn'ài qiě gōutōng shùnchàng de jiātíng huánjìng, duìyú wèichéngnián zǐnǚ jiànquán réngé de shùzào jùyǒu juédìngxìng yǐngxiǎng.", "en": "Family sociology surveys demonstrate that an affectionate marital environment with smooth communication exerts a decisive influence on shaping wholesome personalities in underage children.", "es": "Los estudios de sociología familiar demuestran que un entorno doméstico donde los cónyuges son amorosos y mantienen una comunicación fluida tiene un impacto decisivo en la formación de una personalidad sana en los hijos menores."}], "collocations": [{"hanzi": "夫妻恩爱", "en": "loving married couple"}, {"hanzi": "十分恩爱", "en": "extremely affectionate"}, {"hanzi": "恩爱夫妻", "en": "devoted husband and wife"}, {"hanzi": "恩爱如初", "en": "as loving as in the beginning"}, {"hanzi": "恩爱有加", "en": "exceptionally loving and caring"}, {"hanzi": "秀恩爱", "en": "publicly display affection"}], "idioms": [{"hanzi": "恩重如山", "pinyin": "ēn zhòng rú shān", "meaning_en": "benevolence as heavy as a mountain; immense gratitude"}, {"hanzi": "爱不释手", "pinyin": "ài bù shì shǒu", "meaning_en": "love something so much that one cannot bear to part with it"}, {"hanzi": "相濡以沫", "pinyin": "xiāng rú yǐ mò", "meaning_en": "moisten each other with saliva; share meager resources in adversity"}, {"hanzi": "恩威并施", "pinyin": "ēn wēi bìng shī", "meaning_en": "combine mercy with severity; balance kindness and authority"}], "character_decomposition": [{"character": "恩", "pinyin": "ēn", "meaning_en": "grace; favor; gratitude; kindness", "meaning_es": "gracia; favor; gratitud; bondad", "radical": "心", "radical_meaning_en": "heart", "meaning_component": "心 (heart, feelings of gratitude)", "sound_component": "因 (yīn, phonetic root)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic compound composed of 因 (cause/source) over 心 (heart), evoking deep gratitude felt in the heart for kindness received.", "visual_mnemonic_story_en": "When someone gives you a reason (因) to survive hardship, your heart (心) fills with lifelong grace.", "visual_mnemonic_story_es": "Cuando alguien te brinda un motivo (因) para superar la adversidad, tu corazón (心) se llena de gratitud eterna.", "tone_mnemonic_anchor": "55", "cangjie": "WKP", "traditional": ""}, {"character": "爱", "pinyin": "ài", "meaning_en": "love; affection; cherish", "meaning_es": "amor; afecto; apreciar", "radical": "爫", "radical_meaning_en": "claw / hand", "meaning_component": "爫 (hand holding gently) + 友 (friendship/embrace)", "sound_component": "冖 (cover/canopy protecting)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Originally featured 心 (heart) in traditional 愛; simplified to shelter (爫/冖) over friend (友), denoting tender embrace.", "visual_mnemonic_story_en": "A protective canopy (冖) extends caring hands (爫) to shelter a cherished friend (友).", "visual_mnemonic_story_es": "Un manto protector (冖) extiende manos cariñosas (爫) para cobijar a un amigo entrañable (友).", "tone_mnemonic_anchor": "51", "cangjie": "BBE", "traditional": "愛"}], "extended_reading_passages": [{"id": "#1", "hanzi": "世间最动人的爱情，往往是步入晚年后依然相濡以沫的恩爱。当岁月的风霜爬满额头，彼此依然能读懂对方眼中的温存，在柴米油盐中相守一生。这种恩爱早已化作生命的契约。", "pinyin": "Shìjiān zuì dòngrén de àiqíng, wǎngwǎng shì bùrù wǎnnián hòu yīrán xiāngrúyǐmò de ēn'ài. Dāng suìyuè de fēngshuāng pámǎn étóu, bǐcǐ yīrán néng dúdǒng duìfāng yǎn zhōng de wēncún, zài cháimǐyóuyán zhōng xiāngshǒu yìshēng. Zhè zhǒng ēn'ài zǎoyǐ huàzuò shēngmìng de qìyuē.", "en": "The most touching love is the lifelong affection of growing old together. When frost marks their foreheads, they still read tenderness in each other's eyes throughout daily life. Such marital love becomes an enduring covenant of existence.", "es": "El amor más conmovedor es el afecto conyugal que perdura en la vejez. Cuando el tiempo marca el rostro, ambos siguen leyendo ternura en sus miradas a través de la vida diaria, convirtiendo su cariño en un pacto indestructible."}, {"id": "#2", "hanzi": "在快节奏生活下，夫妻情感凝聚力成为重要的社会议题。婚姻学者强调，健康的恩爱关系需要在同甘共苦中培育责任认同。通过建立良性倾听机制与情感仪式感，才能有效抵御现代家庭的解构风险。", "pinyin": "Zài kuài jièzòu shēnghuó xià, fūqī qínggǎn níngjùlì chéngwéi zhòngyào de shèhuì yìtí. Hūnyīn xuézhě qiángdiào, jiànkāng de ēn'ài guānxì xūyào zài tónggāngòngkǔ zhōng péiyù zérèn rèntóng. Tōngguò jiànlì liángxìng qīngtīng jīzhì yǔ qínggǎn yíshìgǎn, cáinǐng yǒuxiào dǐyù xiàndài jiātíng de jiěgòu fēngxiǎn.", "en": "In fast-paced life, spousal cohesion is an essential social issue. Scholars emphasize that healthy marital love requires cultivating shared responsibility through thick and thin. Establishing listening habits and emotional rituals effectively resists the risk of family fragmentation.", "es": "En la vida contemporánea, la cohesión conyugal es una cuestión social clave. Los especialistas señalan que un amor matrimonial sano exige cultivar la responsabilidad compartida. La escucha mutua y los rituales afectivos protegen a la familia frente a la fragmentación."}]}, {"meanings_summary": {"en": "to compare; to contrast; contrast; comparison", "es": "comparar; contrastar; contraste; comparación"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Place two objects face-to-face (对) and stand them side by side (比) to highlight their contrast.", "composite_memory_hook_es": "Coloca dos objetos frente a frente (对) y ponlos hombro con hombro (比) para contrastar sus diferencias.", "cultural_and_cognitive_roots": "The cognitive framework of 'duì' (confronting/pairing) and 'bǐ' (parallel alignment) stems from ancient Chinese logic of polar dialectics: understanding truth requires balancing symmetrical opposites.", "tone_sandhi_and_pitch_modulation": "51-214 contour. The first syllable is a crisp falling 4th tone (51), followed by the dipping 3rd tone of bǐ (214). When followed by another syllable, bǐ drops to a low dipping tone (21)."}, "semantic_boundary_contrasts": {"core_nuance": "对比 emphasizes laying two contrasting entities side by side to discern discrepancies, discrepancies of scale, or oppositional characteristics.", "contrasts": [{"id": "1", "compared_word": "对比 vs. 比较", "pinyin": "bǐjiào", "analysis": "比较 is a general verb/adverb meaning to compare or 'relatively', whereas 对比 strongly highlights stark differences, polarity, or visual/analytical juxtaposition."}, {"id": "2", "compared_word": "对比 vs. 相比", "pinyin": "xiāngbǐ", "analysis": "相比 is typically used in introductory adverbial frames (如“与……相比”), whereas 对比 functions directly as a transitive verb or an independent noun (如“鲜明的对比”)."}, {"id": "3", "compared_word": "对比 vs. 对照", "pinyin": "duìzhào", "analysis": "对照 implies checking against a standard, benchmark, or reference text (e.g., verifying against a translation), whereas 对比 investigates thematic or statistical divergences."}]}, "traps_and_cognates": {"look_alikes": [{"character": "寸", "pinyin": "cùn", "meaning_en": "inch", "distinction_note": "Lacks the left component 又 of 对"}, {"character": "北", "pinyin": "běi", "meaning_en": "north; flee", "distinction_note": "Depicts two people back-to-back (opposite facing), while 比 has both facing the same direction"}, {"character": "皆", "pinyin": "jiē", "meaning_en": "all; each", "distinction_note": "Features 比 over 白 (white); denotes universality"}, {"character": "毕", "pinyin": "bì", "meaning_en": "complete; finish", "distinction_note": "Has 比 at the top over 十; means to conclude"}], "etymological_cognates": [{"character": "匹", "pinyin": "pǐ", "gloss_en": "match; equal counterpart; sharing pairing nuance"}, {"character": "从", "pinyin": "cóng", "gloss_en": "follow; two people aligned sequentially"}, {"character": "齐", "pinyin": "qí", "gloss_en": "even; uniform level"}, {"character": "双", "pinyin": "shuāng", "gloss_en": "pair; two hands together"}]}, "id": "4", "hanzi": "对比", "pinyin": "duì bǐ", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to juxtapose two or more things to examine their differences and similarities", "definition_es": "yuxtaponer dos o más cosas para examinar sus diferencias y similitudes", "example_phrase": "对比两组数据 (compare two sets of data)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a marked contrast or juxtaposition", "definition_es": "un marcado contraste o contraposición", "example_phrase": "形成鲜明对比 (form a sharp contrast)"}], "example_sentences": [{"id": "#1", "hanzi": "老师让我们仔细对比这两篇题材相同的作文，分析它们在写作手法与结构上的异同。", "pinyin": "Lǎoshī ràng wǒmen zǐxì duìbǐ zhè liǎng piān tícái xiāngtóng de zuòwén, fēnxī tāmen zài xiězuò shǒufǎ yǔ jiégòu shàng de yìtóng.", "en": "The teacher had us carefully compare these two essays on the same topic, analyzing similarities and differences in writing techniques and structure.", "es": "El profesor nos pidió comparar detenidamente estas dos redacciones sobre el mismo tema, analizando similitudes y diferencias en sus técnicas narrativas y estructura."}, {"id": "#2", "hanzi": "经济研究团队通过对比过去三十年间的进出口贸易数据，深入论证了新兴产业转型升级的战略成效。", "pinyin": "Jīngjì yánjiū tuánduì tōngguò duìbǐ guòqù sānshí nián jiān de jìnchūkǒu màoyì shùjù, shēnrù lùnzhèng le xīnxīng chǎnyè zhuǎnxíng shēngjí de zhànlüè chéngxiào.", "en": "By contrasting import and export trade data over the past thirty years, the economic research team substantiated the strategic efficacy of emerging industry upgrades.", "es": "Al contrastar los datos comerciales de importación y exportación de las últimas tres décadas, el equipo de investigación económica demostró la eficacia estratégica de la transformación industrial emergente."}], "collocations": [{"hanzi": "鲜明对比", "en": "sharp contrast"}, {"hanzi": "强烈对比", "en": "strong contrast"}, {"hanzi": "对比分析", "en": "comparative analysis"}, {"hanzi": "对比数据", "en": "compare data"}, {"hanzi": "横向对比", "en": "horizontal/peer comparison"}, {"hanzi": "纵向对比", "en": "longitudinal/historical comparison"}], "idioms": [{"hanzi": "截然不同", "pinyin": "jié rán bù tóng", "meaning_en": "completely different; worlds apart"}, {"hanzi": "对比鲜明", "pinyin": "duì bǐ xiān míng", "meaning_en": "in striking contrast; sharply demarcated"}, {"hanzi": "针锋相对", "pinyin": "zhēn fēng xiāng duì", "meaning_en": "tit for tat; sharply oppose head-on"}, {"hanzi": "比上不足", "pinyin": "bǐ shàng bù zú", "meaning_en": "fall short of the best, but better than the worst"}], "character_decomposition": [{"character": "对", "pinyin": "duì", "meaning_en": "face; pair; opposite; correct", "meaning_es": "frente a; pareja; opuesto; correcto", "radical": "寸", "radical_meaning_en": "inch / hand measurement", "meaning_component": "寸 (inch/rule for measurement)", "sound_component": "又 (hand/phonetic simplification)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Originally depicted standing face-to-face and answering appropriately under royal measure (寸).", "visual_mnemonic_story_en": "Two hands (又) measure with a small inch ruler (寸) to ensure two objects face each other evenly.", "visual_mnemonic_story_es": "Dos manos (又) miden con una regla de pulgada (寸) para asegurarse de que dos piezas se enfrenten con exactitud.", "tone_mnemonic_anchor": "51", "cangjie": "EDI", "traditional": "對"}, {"character": "比", "pinyin": "bǐ", "meaning_en": "compare; emulate; close together", "meaning_es": "comparar; competir; estar juntos", "radical": "比", "radical_meaning_en": "compare", "meaning_component": "匕 (person standing next to another)", "sound_component": "匕 (bǐ, mirrored human figures)", "stroke_count": "4", "composition_type": "左右结构", "etymology_and_mnemonic": "Pictogram of two people walking side by side shoulder-to-shoulder, compared against each other.", "visual_mnemonic_story_en": "Two people (匕 + 匕) stand side by side back-to-back to compare their heights.", "visual_mnemonic_story_es": "Dos personas (匕 + 匕) se paran hombro con hombro para comparar sus estaturas.", "tone_mnemonic_anchor": "214", "cangjie": "PP", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "古老的青砖瓦房与高耸的现代玻璃幕墙在晨光中形成了鲜明的对比。历史的厚重与现代的轻盈在街头对话，让人体会到岁月的流变。正是在这种对比中，城市记忆才更加立体丰满。", "pinyin": "Gǔlǎo de qīngzhuān wǎfáng yǔ gāosǒng de xiàndài bōlí mùqiáng zài chénguāng zhōng xíngchéng le xiānmíng de duìbǐ. Lìshǐ de hòuzhòng yǔ xiàndài de qīngyíng zài jiētóu duìhuà, ràng rén tǐhuì dào suìyuè de liúbiàn. Zhèng shì zài zhè zhǒng duìbǐ zhōng, chéngshì jìyì cái gèngjiā lìtǐ fēngmǎn.", "en": "Ancient grey tile cottages and soaring modern glass curtain walls form a vivid contrast in the morning light. Historical gravitas converses with contemporary grace, making urban memories richer through contrast.", "es": "Las antiguas casas de teja gris y los modernos muros de cristal forman un vivo contraste bajo la luz matutina. La solidez histórica dialoga con la ligereza contemporánea, enriqueciendo la memoria urbana a través de este contraste."}, {"id": "#2", "hanzi": "在现代企业战略管理中，标杆管理方法的核心正是跨行业对比。企业通过对标行业领军者的周转速度与创新周期，精准识别价值链短板。深入的对比分析不仅能打破路径依赖，更为流程再造提供了量化依据。", "pinyin": "Zài xiàndài qǐyè zhànlüè guǎnlǐ zhōng, biāogān guǎnlǐ fāngfǎ de héxīn zhèng shì kuà hángyè duìbǐ. Qǐyè tōngguò duìbiāo hángyè lǐngjūnzhě de zhōuzhuǎn sùdù yǔ chuàngxīn zhōuqī, jīngzhǔn shíbié jiàzhíliàn duǎnbǎn. Shēnrù de duìbǐ fēnxī bùjǐn néng dǎpò lùjìng yīlài, gèng wèi liúchéng zàizào tígōng le liànghuà yījù.", "en": "In corporate strategy, benchmarking centers on cross-industry comparison. By comparing turnover velocity and innovation cycles with leaders, firms identify value-chain weaknesses. Deep comparative analysis breaks path dependency and provides quantitative grounds for reengineering.", "es": "En la estrategia empresarial moderna, el benchmarking se basa en la comparación intersectorial. Al contrastar la velocidad de rotación e innovación con los líderes, las empresas identifican fallos y obtienen bases cuantitativas para rediseñar procesos."}]}, {"meanings_summary": {"en": "to be shortlisted; to qualify for the next round; to make the finalist list", "es": "ser seleccionado; quedar como finalista; pasar a la ronda final"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Penetrating (入) inside the exclusive enclosure (围) means you have officially made the shortlist.", "composite_memory_hook_es": "Penetrar (入) dentro del recinto exclusivo (围) significa que has sido seleccionado como finalista.", "cultural_and_cognitive_roots": "Derived from the ancient imperial examination and hunting cordon where only top performers were permitted to enter the inner imperial enclosure ('wéi'); modern usage adapts this to entering competitive shortlists.", "tone_sandhi_and_pitch_modulation": "51-35 pitch contour. The entering tone of rù falls swiftly (51), followed by the smooth rising contour of wéi (35)."}, "semantic_boundary_contrasts": {"core_nuance": "入围 specifically denotes crossing the threshold of preliminary selection to secure a designated spot on the final nominee list.", "contrasts": [{"id": "1", "compared_word": "入围 vs. 晋级", "pinyin": "jìnjí", "analysis": "入围 stresses entering an elite shortlist or nomination bracket (e.g., film awards), while 晋级 emphasizes tournament stage progression (e.g., advancing from round of 16 to quarterfinals)."}, {"id": "2", "compared_word": "入围 vs. 获奖", "pinyin": "huòjiǎng", "analysis": "入围 indicates qualification as a finalist or nominee, whereas 获奖 denotes actually winning an award or final prize."}, {"id": "3", "compared_word": "入围 vs. 入选", "pinyin": "rùxuǎn", "analysis": "入选 means being chosen or accepted into a team, anthology, or roster, whereas 入围 strictly implies qualifying for an ongoing competitive final round."}]}, "traps_and_cognates": {"look_alikes": [{"character": "人", "pinyin": "rén", "meaning_en": "person; human", "distinction_note": "Left falling stroke extends above the right stroke, unlike 入 where right overlaps left"}, {"character": "八", "pinyin": "bā", "meaning_en": "eight", "distinction_note": "The two strokes do not touch at the top, leaving an open apex"}, {"character": "国", "pinyin": "guó", "meaning_en": "country; nation", "distinction_note": "Contains 玉 (jade) inside the 囗 enclosure instead of 韦"}, {"character": "园", "pinyin": "yuán", "meaning_en": "garden; park", "distinction_note": "Contains 元 inside the 囗 enclosure instead of 韦"}], "etymological_cognates": [{"character": "进", "pinyin": "jìn", "gloss_en": "advance; enter forward"}, {"character": "内", "pinyin": "nèi", "gloss_en": "inside; interior, sharing inward penetration root"}, {"character": "圈", "pinyin": "quān", "gloss_en": "circle; bounded ring"}, {"character": "界", "pinyin": "jiè", "gloss_en": "boundary; border scope"}]}, "id": "5", "hanzi": "入围", "pinyin": "rù wéi", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to pass preliminary screening and enter the final selection or shortlist of a competition", "definition_es": "superar la selección preliminar y entrar en la lista de finalistas de un certamen o concurso", "example_phrase": "入围决赛 (make it to the finals)"}], "example_sentences": [{"id": "#1", "hanzi": "经过长达半年的刻苦备战，我们学校的辩论队凭借出色的发挥顺利入围全国中学生辩论锦标赛总决赛。", "pinyin": "Jīngguò chángdá bàn nián de kèkǔ bèizhàn, wǒmen xuéxiào de biànlùn duì píngjiè chūsè de fāhuī shùnlì rùwéi quánguó zhōngxuéshēng biànlùn jǐnbiāosài zǒngjuésài.", "en": "After half a year of arduous preparation, our school debate team smoothly qualified for the national high school debate championship grand finals.", "es": "Tras medio año de rigurosa preparación, el equipo de debate de nuestra escuela logró clasificarse con éxito para la gran final del campeonato nacional escolar."}, {"id": "#2", "hanzi": "该项绿色能源专利技术凭借显著的减排效益，成功入围联合国工业发展组织全球可持续技术前沿榜单。", "pinyin": "Gāi xiàng lǜsè néngyuán zhuānlì jìshù píngjiè xiǎnzhù de jiǎnpái xiàoyì, chénggōng rùwéi Liánhéguó Gōngyè Fāzhǎn Zǔzhī quánqiú kěchíxù jìshù qiányán bǎngdān.", "en": "By virtue of significant emission reduction efficacy, this green energy patent successfully made the shortlist of UNIDO's global sustainable technology frontier ranking.", "es": "Gracias a su notable eficacia en reducción de emisiones, esta patente de energía verde logró ser seleccionada en la prestigiosa lista de tecnologías sostenibles de la ONUDI."}], "collocations": [{"hanzi": "成功入围", "en": "successfully shortlisted"}, {"hanzi": "入围名单", "en": "shortlist / finalists roster"}, {"hanzi": "入围作品", "en": "shortlisted works"}, {"hanzi": "入围决赛", "en": "qualify for the finals"}, {"hanzi": "入围奖项", "en": "shortlisted for awards"}, {"hanzi": "顺利入围", "en": "smoothly made the cut"}], "idioms": [{"hanzi": "脱颖而出", "pinyin": "tuō yǐng ér chū", "meaning_en": "stand out from the crowd; talent revealing itself"}, {"hanzi": "入木三分", "pinyin": "rù mù sān fēn", "meaning_en": "penetrate deeply; keen and incisive"}, {"hanzi": "金榜题名", "pinyin": "jīn bǎng tí míng", "meaning_en": "pass the civil examination; succeed in a competitive test"}, {"hanzi": "重围之中", "pinyin": "chóng wéi zhī zhōng", "meaning_en": "amid tight encirclement; in the thick of a cordon"}], "character_decomposition": [{"character": "入", "pinyin": "rù", "meaning_en": "enter; join; admit", "meaning_es": "entrar; ingresar; admitir", "radical": "入", "radical_meaning_en": "enter", "meaning_component": "入 (pictogram of sharp downward entry)", "sound_component": "入 (inherent archaic sound)", "stroke_count": "2", "composition_type": "独体字", "etymology_and_mnemonic": "Pictogram of an arrow or wedge penetrating downward through a membrane or portal.", "visual_mnemonic_story_en": "A sharp root or wedge (入) pushes its tip deep into the soil to gain entry.", "visual_mnemonic_story_es": "Una cuña afilada (入) se abre paso hacia abajo para penetrar en la tierra.", "tone_mnemonic_anchor": "51", "cangjie": "OH", "traditional": ""}, {"character": "围", "pinyin": "wéi", "meaning_en": "surround; enclose; corral; perimeter", "meaning_es": "rodear; cercar; recinto; perímetro", "radical": "囗", "radical_meaning_en": "enclosure", "meaning_component": "囗 (surrounding boundary wall)", "sound_component": "韦 (wéi, leather/encircling belt)", "stroke_count": "7", "composition_type": "全包围结构", "etymology_and_mnemonic": "Depicts an enclosing border wall (囗) surrounding leather perimeter guards (韦).", "visual_mnemonic_story_en": "Soldiers wearing leather armor (韦) stand inside fortified city walls (囗) guarding the designated perimeter.", "visual_mnemonic_story_es": "Guardianes con corazas de cuero (韦) vigilan dentro de las murallas (囗) el perímetro del recinto.", "tone_mnemonic_anchor": "35", "cangjie": "ODS", "traditional": "圍"}], "extended_reading_passages": [{"id": "#1", "hanzi": "对青年电影人而言，作品入围国际电影节主竞赛单元，是一份极大的肯定。当掌声在影厅响起，所有的付出都在这一刻化为前行的力量。入围不仅关乎荣耀，更关乎被看见的喜悦。", "pinyin": "Duì qīngnián diànyǐngrén éryán, zuòpǐn rùwéi guójì diànyǐngjié zhǔ jìngsài dānyuán, shì yí fèn jídà de kěndìng. Dāng zhǎngshēng zài yǐngtīng xiǎngqǐ, suǒyǒu de fùchū dōu zài zhè yí kè huàwéi qiánxíng de lìliàng. Rùwéi bùjǐn guānhū róngyào, gèng guānhū bèi kànjiàn de xǐyuè.", "en": "For young filmmakers, having a work shortlisted in an international festival's main competition is immense validation. When applause rings out, all effort turns into strength to forge ahead. Being shortlisted is not just about honor, but the joy of being seen.", "es": "Para un joven cineasta, que su obra quede finalista en la sección oficial de un festival internacional es un gran reconocimiento. Los aplausos convierten todo esfuerzo en impulso. Ser finalista no es solo un honor, sino la alegría de ser apreciado."}, {"id": "#2", "hanzi": "在大型工程招标实践中，资格预审入围是防范履约风险的首要关卡。招标方从财务稳健度、技术资质及历史绩效等维度展开全面审查。只有成功入围的联合体，方有资格递交最终商务标书。", "pinyin": "Zài dàxíng gōngchéng zhāobiāo shíjiàn zhōng, zīgé yùshěn rùwéi shì fángfàn lǚyuē fēngxiǎn de shǒuyào guānkǎ. Zhāobiāofāng cóng cáiwù wěnjiàndù, jìshù zīzhì jí lìshǐ jìxiào děng wéidù zhǎnkāi quánmiàn shěnchá. Zhǐyǒu chénggōng rùwéi de liánhétǐ, fāng yǒu zīgé dìjiāo zuìzhōng shāngwù biāoshū.", "en": "In major project tendering, prequalification shortlisting is the primary defense against default risk. Tendering authorities review financial health, technical qualifications, and track record. Only shortlisted consortia may submit final commercial proposals.", "es": "En licitaciones de gran envergadura, la preselección de finalistas es el filtro principal contra riesgos de incumplimiento. Se revisan solvencia económica, capacidad técnica e historial. Solo los consorcios seleccionados pueden presentar ofertas comerciales definitivas."}]}, {"meanings_summary": {"en": "judge; member of a judging panel; evaluation committee member", "es": "miembro del jurado; juez calificador; evaluador"}, "mnemonics_and_roots": {"composite_memory_hook_en": "One who speaks with fair words (评) and is entrusted with authority (委) sits as a respected judge.", "composite_memory_hook_es": "Quien emite juicios equilibrados (评) y recibe la confianza encomendada (委) actúa como juez en el tribunal.", "cultural_and_cognitive_roots": "In Chinese governance, 'píng' denotes level-headed appraisal without bias, while 'wěi' (abbreviation of 委员会委员) conveys delegated communal trust; together, a 评委 is a guardian of meritocratic fairness.", "tone_sandhi_and_pitch_modulation": "35-214 pitch contour. The rising tone of píng leads smoothly into the dipping tone of wěi. In fluent conversation, wěi often stays in a low dipping contour (21) when followed by further syllables."}, "semantic_boundary_contrasts": {"core_nuance": "评委 denotes an officially appointed adjudicator or committee member tasked with assessing contest submissions and awarding scores.", "contrasts": [{"id": "1", "compared_word": "评委 vs. 裁判", "pinyin": "cáipàn", "analysis": "裁判 is primarily used in athletic events and legal arbitrations for enforcing rules, whereas 评委 adjudicates artistic, academic, or competitive talent performances."}, {"id": "2", "compared_word": "评委 vs. 专家", "pinyin": "zhuānjiā", "analysis": "专家 is an expert possessing domain mastery in a field, who may or may not act as a 评委 in a specific judging panel."}, {"id": "3", "compared_word": "评委 vs. 考官", "pinyin": "kǎoguān", "analysis": "考官 specifically refers to an examiner overseeing formal aptitude or academic examinations, whereas 评委 ranks contestants in competitive venues."}]}, "traps_and_cognates": {"look_alikes": [{"character": "许", "pinyin": "xǔ", "meaning_en": "allow; praise", "distinction_note": "Right side is 午 (noon) rather than 平 (level)"}, {"character": "订", "pinyin": "dìng", "meaning_en": "order; book", "distinction_note": "Right side is 丁 rather than 平"}, {"character": "季", "pinyin": "jì", "meaning_en": "season; quarter", "distinction_note": "Features 禾 over 子 (child) instead of 女 (woman)"}, {"character": "秀", "pinyin": "xiù", "meaning_en": "elegant; show", "distinction_note": "Features 禾 over 乃 instead of 女"}], "etymological_cognates": [{"character": "平", "pinyin": "píng", "gloss_en": "level; fair; phonetic root of 评"}, {"character": "论", "pinyin": "lùn", "gloss_en": "discuss; evaluate in the speech radical family"}, {"character": "托", "pinyin": "tuō", "gloss_en": "entrust; related in semantic delegation to 委"}, {"character": "员", "pinyin": "yuán", "gloss_en": "member; official roster"}]}, "id": "6", "hanzi": "评委", "pinyin": "píng wěi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a person serving on a judging committee or jury for a contest or evaluation", "definition_es": "persona que forma parte de un comité evaluador o jurado calificador", "example_phrase": "担任评委 (serve as a judge)"}], "example_sentences": [{"id": "#1", "hanzi": "在今晚的青年歌手大奖赛现场，著名音乐家担任主评委并对每位选手的表现给予了中肯点评。", "pinyin": "Zài jīnwǎn de qīngnián gēshǒu dàjiǎngsài xiànchǎng, zhùmíng yīnyuèjiā dānrèn zhǔ píngwěi bìng duì měi wèi xuǎnshǒu de biǎoxiàn jǐyǔ le zhòngkěn diǎnpíng.", "en": "At tonight's young singers competition, a renowned musician served as head judge and offered pertinent feedback on each contestant's performance.", "es": "En la gala de cantantes juveniles de esta noche, un destacado músico actuó como juez principal y brindó comentarios acertados sobre cada concursante."}, {"id": "#2", "hanzi": "科技创新基金评审委员会明确规定，与参评企业存在利益关联的专家必须主动申请回避评委职务。", "pinyin": "Kējì chuàngxīn jījīn píngshěn wěiyuánhuì míngquè guīdìng, yǔ cānpíng qǐyè cúnzài lìyì guānlián de zhuānjiā bìxū zhǔdòng shēnqǐng huíbì píngwěi zhíwù.", "en": "The Science and Technology Innovation Fund review committee expressly stipulates that experts with vested interests in participating firms must recuse themselves from serving as judges.", "es": "El comité de evaluación del fondo de innovación tecnológica estipula con claridad que los expertos con conflictos de interés con las empresas aspirantes deben abstenerse de integrar el jurado."}], "collocations": [{"hanzi": "担任评委", "en": "serve as a judge"}, {"hanzi": "评委会主席", "en": "jury president / head of judging panel"}, {"hanzi": "特邀评委", "en": "guest judge"}, {"hanzi": "专业评委", "en": "professional juror"}, {"hanzi": "大众评委", "en": "popular/audience juror"}, {"hanzi": "评委打分", "en": "judges' scoring"}], "idioms": [{"hanzi": "评头品足", "pinyin": "píng tóu pǐn zú", "meaning_en": "find fault with; make hypercritical comments"}, {"hanzi": "委曲求全", "pinyin": "wěi qū qiú quán", "meaning_en": "compromise for the sake of the general interest"}, {"hanzi": "虚与委蛇", "pinyin": "xū yǔ wēi yí", "meaning_en": "deal with someone insincerely; play along politely"}, {"hanzi": "评功摆好", "pinyin": "píng gōng bǎi hǎo", "meaning_en": "sing praises of one's own contributions"}], "character_decomposition": [{"character": "评", "pinyin": "píng", "meaning_en": "evaluate; judge; criticize; discuss", "meaning_es": "evaluar; juzgar; criticar; comentar", "radical": "讠", "radical_meaning_en": "speech", "meaning_component": "讠 (speech, uttering verdicts)", "sound_component": "平 (píng, level/fair)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining speech (讠) with fairness/balance (平), conveying speaking impartial truth.", "visual_mnemonic_story_en": "Words spoken (讠) across a level balance scale (平) represent fair judicial appraisal.", "visual_mnemonic_story_es": "Palabras expresadas (讠) sobre una balanza equilibrada (平) representan un juicio imparcial.", "tone_mnemonic_anchor": "35", "cangjie": "IVMF", "traditional": "評"}, {"character": "委", "pinyin": "wěi", "meaning_en": "entrust; appoint; committee; indirect", "meaning_es": "encomendar; encargar; comité; indirecto", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (woman / yielding compliance)", "sound_component": "禾 (grain / resource managed)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Depicts grain (禾) entrusted to a household manager (女), evolving to mean delegation of authority.", "visual_mnemonic_story_en": "Harvested sheaves of grain (禾) are entrusted to the capable hands of a matriarch (女) to manage.", "visual_mnemonic_story_es": "Las gavillas de trigo (禾) se encomiendan al cuidado prudente de una mujer (女) para su gestión.", "tone_mnemonic_anchor": "214", "cangjie": "HDV", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "艺术比赛的舞台不仅见证选手的汗水，更考验评委的眼光。面对风格各异的参赛作品，优秀的评委总能剥离华丽的表象，发现直击心灵的灵性表达。中肯的评语如同一束光，指引着青年探索者前行的方向。", "pinyin": "Yìshù bǐsài de wǔtái bùjǐn jiànzhèng xuǎnshǒu de hànshuǐ, gèng kǎoyàn píngwěi de yǎnguāng. Miànduì fēnggé gèyì de cānsài zuòpǐn, yōuxiù de píngwěi zǒng néng bōlí huálì de biǎoxiàng, fāxiàn zhíjī xīnlíng de língxìng biǎodá. Zhòngkěn de píngyǔ rútóng yí shù guāng, zhǐyǐn zhe qīngnián tànsuǒzhě qiánxíng de fāngxiàng.", "en": "The stage of an arts contest tests not only contestants' sweat but judges' discernment. Confronting diverse works, outstanding judges see through superficial gloss to spot genuine soul. Pertinent commentary serves as a beacon lighting the path of young creators.", "es": "El escenario de un certamen artístico pone a prueba la mirada del jurado tanto como el esfuerzo de los participantes. Ante obras variadas, los jurados perspicaces trascienden la superficie para valorar la autenticidad emocional, guiando a los jóvenes creadores."}, {"id": "#2", "hanzi": "在现代科技成果评估体系中，评委团队的跨学科构成已成为确保评审客观性的制度基石。来自产业界与学术界的资深评委共同参与答辩，从学术前沿价值与产业转化可行性双重视角，严格审核每一项申报成果。", "pinyin": "Zài xiàndài kējì chéngguǒ pínggū tǐxì zhōng, píngwěi tuánduì de kuà xuékē gòuchéng yǐ chéngwéi quèbǎo píngshěn kèguānxìng de zhìdù jīshí. Lázì chǎnyèjiè yǔ xuéshùjiè de zīshēn píngwěi gòngtóng cānyù dábbiàn, cóng xuéshù qiányán jiàzhí yǔ chǎnyè zhuǎnhuà kěxíngxìng shuāngzhòng shìjiǎo, yángé shěnhé měi yí xiàng shēnbào chéngguǒ.", "en": "In modern scientific evaluation systems, the interdisciplinary composition of judging panels forms an institutional bedrock for objectivity. Senior jurors from industry and academia participate jointly in defenses, evaluating innovations through academic frontiers and market feasibility.", "es": "En la evaluación científica contemporánea, la integración interdisciplinaria del jurado constituye la base de la objetividad institucional. Jueces veteranos del sector industrial y académico evalúan conjuntamente los proyectos desde la validez teórica y su viabilidad productiva."}]}, {"meanings_summary": {"en": "how; what; what way; in what condition", "es": "¿cómo?; ¿de qué manera?; ¿en qué estado?"}, "mnemonics_and_roots": {"composite_memory_hook_en": "In accordance with (如) what method (何) should we proceed? That is the heart of asking 'how'.", "composite_memory_hook_es": "¿Conforme a (如) qué camino (何) debemos actuar? Así se indaga el 'cómo' formal de las cosas.", "cultural_and_cognitive_roots": "Inherited directly from Classical Chinese (文言文), 'rú hé' blends the comparative particle 'rú' (to resemble/conform) and interrogative 'hé' (what), framing practical inquiries with philosophical elegance.", "tone_sandhi_and_pitch_modulation": "35-35 tone sequence. In standard Mandarin, two consecutive 2nd tones (rising 35) are pronounced distinctly without tone change, giving a melodious double-rising cadence."}, "semantic_boundary_contrasts": {"core_nuance": "如何 is a formal, written-register interrogative pronoun asking about the manner, method, condition, or state of affairs.", "contrasts": [{"id": "1", "compared_word": "如何 vs. 怎么", "pinyin": "zěnme", "analysis": "怎么 is predominantly colloquial and everyday spoken Chinese, whereas 如何 belongs to formal, academic, written, or elevated oratorical registers."}, {"id": "2", "compared_word": "如何 vs. 怎样", "pinyin": "zěnyàng", "analysis": "怎样 is neutral-colloquial inquiring about state or appearance, while 如何 often introduces strategic inquiries or formal problem formulations."}, {"id": "3", "compared_word": "如何 vs. 为何", "pinyin": "wèihé", "analysis": "为何 inquires specifically about reason or causation ('why'), whereas 如何 inquires about methodology, degree, or status ('how')."}]}, "traps_and_cognates": {"look_alikes": [{"character": "知", "pinyin": "zhī", "meaning_en": "know", "distinction_note": "Left component is 矢 (arrow) rather than 女 (woman)"}, {"character": "和", "pinyin": "hé", "meaning_en": "harmony; and", "distinction_note": "Left component is 禾 (grain) rather than 女 or 口"}, {"character": "河", "pinyin": "hé", "meaning_en": "river", "distinction_note": "Has water radical 氵 on the left instead of person 亻"}, {"character": "荷", "pinyin": "hé", "meaning_en": "lotus; carry", "distinction_note": "Has grass radical 艹 above 何"}], "etymological_cognates": [{"character": "若", "pinyin": "ruò", "gloss_en": "like; if; shares classical subjunctive lineage with 如"}, {"character": "孰", "pinyin": "shú", "gloss_en": "who; which; classical interrogative relative of 何"}, {"character": "胡", "pinyin": "hú", "gloss_en": "why; how; archaic question root"}, {"character": "安", "pinyin": "ān", "gloss_en": "how; where; classical modal interrogative"}]}, "id": "7", "hanzi": "如何", "pinyin": "rú hé", "level": "HSK 5", "part_of_speech": "Pronoun", "senses": [{"sense_number": "1", "part_of_speech": "Pronoun", "register": "Formal", "definition_en": "in what manner, way, or state (formal inquiry equivalent to 怎么 or 怎么样)", "definition_es": "de qué modo o en qué circunstancias (interrogativo formal equivalente a 怎么 o 怎么样)", "example_phrase": "如何解决问题 (how to resolve the issue)"}], "example_sentences": [{"id": "#1", "hanzi": "面对大学毕业后的人生十字路口，年轻人们都在认真思考如何平衡理想追求与现实生活压力。", "pinyin": "Miànduì dàxué bìyè hòu de rénshēng shízì lùkǒu, niánqīngrén men dōu zài rènzhēn sīkǎo rúhé pínghéng lǐxiǎng zhuīqiú yǔ xiànshí shēnghuó yālì.", "en": "Faced with the crossroads of life after university graduation, young people earnestly ponder how to balance idealism with the pressures of reality.", "es": "Frente a la encrucijada vital tras graduarse de la universidad, los jóvenes meditan con seriedad cómo equilibrar sus ideales con las presiones de la realidad."}, {"id": "#2", "hanzi": "如何在全球供应链动荡的外部挑战下构建高韧性产业生态，是当前各国宏观经济决策者面临的紧迫课题。", "pinyin": "Rúhé zài quánqiú gōngyìngliàn dòngdàng de wàibù tiǎozhàn xià gòujiàn gāo rènxìng chǎnyè shēngtài, shì dāngqián gè guó hóngguān jīngjì juécèzhě miànlín de jǐnpò kètí.", "en": "How to construct a resilient industrial ecosystem amidst external global supply chain disruptions is an urgent topic for macroeconomic policymakers worldwide.", "es": "Cómo construir un ecosistema productivo resiliente frente a las disrupciones en las cadenas globales de suministro constituye un reto prioritario para los gobernantes."}], "collocations": [{"hanzi": "如何处理", "en": "how to handle"}, {"hanzi": "如何看待", "en": "how to view / regard"}, {"hanzi": "如何解决", "en": "how to resolve"}, {"hanzi": "无论如何", "en": "in any case; no matter what"}, {"hanzi": "不知如何是好", "en": "not know what to do"}, {"hanzi": "如何应对", "en": "how to respond to"}], "idioms": [{"hanzi": "无可奈何", "pinyin": "wú kě nài hé", "meaning_en": "have no alternative; helpless in the face of fate"}, {"hanzi": "如火如荼", "pinyin": "rú huǒ rú tú", "meaning_en": "like raging fire and blooming rush; thriving vigorously"}, {"hanzi": "何去何从", "pinyin": "hé qù hé cóng", "meaning_en": "what course to follow; which path to choose"}, {"hanzi": "谈何容易", "pinyin": "tán hé róng yì", "meaning_en": "far from easy; easier said than done"}], "character_decomposition": [{"character": "如", "pinyin": "rú", "meaning_en": "as; like; if; accord with", "meaning_es": "como; igual que; según; si", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (woman / accommodating)", "sound_component": "口 (mouth / words complying)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Ancient ideogram of mouth (口) yielding to guidance (女), evolving to mean 'in accordance with' or 'likeness'.", "visual_mnemonic_story_en": "Speaking from the mouth (口) with the graceful compliance of a lady (女) ensures actions match intentions.", "visual_mnemonic_story_es": "Expresarse con la boca (口) de forma armónica como una dama (女) logra que las acciones se correspondan con las palabras.", "tone_mnemonic_anchor": "35", "cangjie": "VR", "traditional": ""}, {"character": "何", "pinyin": "hé", "meaning_en": "what; how; why; which", "meaning_es": "qué; cómo; por qué; cuál", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person carrying/asking)", "sound_component": "可 (kě, phonetic marker)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Originally a person (亻) carrying a burden on the shoulder asking where to go, borrowed early on as an interrogative pronoun.", "visual_mnemonic_story_en": "A traveler (亻) pauses asking if it is possible (可) to proceed in this manner.", "visual_mnemonic_story_es": "Un viajero (亻) se detiene a preguntar si es posible (可) seguir por ese camino.", "tone_mnemonic_anchor": "35", "cangjie": "OMNR", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "古人常问，人在顺境与逆境中应如何安身立命。顺境时保持清醒克制，不迷失于喧嚣；逆境中坚守信念初衷，不屈服于风雨。懂得如何与孤独相处，如何在喧嚣中守住内心宁静，是每个人终其一生的修行。", "pinyin": "Gǔrén cháng wèn, rén zài shùnjìng yǔ nìjìng zhōng yīng rúhé ānshēnlìmìng. Shùnjìng shí bǎochí qīngxǐng kèzhì, bù míshī yú xuānxiāo; nìjìng zhōng jiānshǒu xìnniàn chūzhōng, bù qūfú yú fēngyǔ. Dǒngdé rúhé yǔ gūdú xiāngchǔ, rúhé zài xuānxiāo zhōng shǒuzhù nèixīn níngjìng, shì měi gè rén zhōng qí yìshēng de xiūxíng.", "en": "The ancients frequently asked how one should find peace amid fortune and adversity. Remaining sober in success and resolute in hardship is key. Knowing how to dwell with solitude and preserve inner quiet amidst clamor is a lifelong cultivation.", "es": "Los antiguos se preguntaban cómo encontrar paz en la prosperidad y la adversidad. Conservar la serenidad en el éxito y la firmeza en la dificultad es esencial. Saber convivir con la soledad y cuidar la calma interior es un aprendizaje para toda la vida."}, {"id": "#2", "hanzi": "在人工智能技术快速重塑劳动力市场的背景下，教育体系应如何调整培养方案成为全球焦点。如何在基础课程中强化批判性思维，如何培养跨学科解决复杂现实问题的能力，直接决定了未来人才的竞争格局。", "pinyin": "Zài réngōng zhìnéng jìshù kuàisù zhòngshù láodònglì shìchǎng de bèijǐng xià, jiàoyù tǐxì yīng rúhé tiáozhěng péiyǎng fāng'àn chéngwéi quánqiú jiāodiǎn. Rúhé zài jīchǔ kèchéng zhōng qiánghuà pīpànxìng sīwéi, rúhé péiyǎng kuà xuékē jiějué fùzá xiànshí wèntí de nénglì, zhíjiē juédìng le wèilái réncái de jìngzhēng géjú.", "en": "As artificial intelligence rapidly reshapes labor markets, how education systems adapt has become a global focal point. How to strengthen critical thinking and nurture cross-disciplinary problem-solving will dictate future human capital competitiveness.", "es": "Con el avance de la inteligencia artificial sobre el mercado laboral, cómo adaptar la educación se ha vuelto prioritario. Cómo reforzar el pensamiento crítico y fomentar la capacidad multidisciplinar definirá la competitividad del talento futuro."}]}, {"meanings_summary": {"en": "to be paralyzed; paralysis; breakdown; gridlock", "es": "estar paralizado; parálisis; colapso; paralización"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Both characters share the sickness radical (疒): suffering motor difficulty (瘫) and bodily slackness (痪) paralyzes movement.", "composite_memory_hook_es": "Ambos caracteres comparten el radical de enfermedad (疒): la postración (瘫) y la atrofia (痪) provocan parálisis total.", "cultural_and_cognitive_roots": "Traditional Chinese medicine conceptualizes 瘫痪 as severe obstruction of Qi and Blood within meridians. In modern sociology, it naturally metaphoricalized to urban gridlock and digital system outages.", "tone_sandhi_and_pitch_modulation": "55-51 pitch contour. High flat level tone (55) on tān swiftly descends into the crisp falling 4th tone (51) of huàn."}, "semantic_boundary_contrasts": {"core_nuance": "瘫痪 denotes complete loss of motor function biologically, or the total cessation of functional operation in systems.", "contrasts": [{"id": "1", "compared_word": "瘫痪 vs. 残废", "pinyin": "cánfèi", "analysis": "残废 refers broadly to physical disability or bodily maiming (often permanent), while 瘫痪 specifically targets neurological or systematic loss of functional movement."}, {"id": "2", "compared_word": "瘫痪 vs. 停顿", "pinyin": "tíngdùn", "analysis": "停顿 indicates a temporary pause or interruption in motion, whereas 瘫痪 indicates a disastrous systemic breakdown incapable of spontaneous recovery."}, {"id": "3", "compared_word": "瘫痪 vs. 崩溃", "pinyin": "bēngkuì", "analysis": "崩溃 emphasizes structural collapse or psychological disintegration, while 瘫痪 highlights functional immobilization and loss of transmission."}]}, "traps_and_cognates": {"look_alikes": [{"character": "痛", "pinyin": "tòng", "meaning_en": "pain; ache", "distinction_note": "Contains 甬 inside 疒 instead of 难"}, {"character": "疯", "pinyin": "fēng", "meaning_en": "insane; mad", "distinction_note": "Contains 风 (wind) inside 疒 instead of 难"}, {"character": "涣", "pinyin": "huàn", "meaning_en": "dissipate; disperse", "distinction_note": "Has water radical 氵 on the left instead of disease 疒"}, {"character": "唤", "pinyin": "huàn", "meaning_en": "call; awaken", "distinction_note": "Has mouth radical 口 on the left instead of disease 疒"}], "etymological_cognates": [{"character": "病", "pinyin": "bìng", "gloss_en": "disease; illness in the 疒 radical system"}, {"character": "疾", "pinyin": "jí", "gloss_en": "ailment; rapid onset sickness"}, {"character": "痹", "pinyin": "bì", "gloss_en": "numbness; rheumatic paralysis"}, {"character": "滞", "pinyin": "zhì", "gloss_en": "stagnant; clogged flow"}]}, "id": "8", "hanzi": "瘫痪", "pinyin": "tān huàn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to suffer loss of motor function or physical paralysis due to neurological or spinal illness", "definition_es": "perder la función motora o sufrir parálisis física por enfermedad neurológica", "example_phrase": "双腿瘫痪 (legs are paralyzed)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Metaphorical", "definition_en": "to completely break down, grind to a halt, or collapse (of systems, traffic, computers)", "definition_es": "colapsar por completo o quedar inoperante (tráfico, redes, sistemas)", "example_phrase": "交通陷入瘫痪 (traffic collapsed into gridlock)"}], "example_sentences": [{"id": "#1", "hanzi": "虽然在一场意外车祸中不幸下肢瘫痪，但他凭借坚强的毅力自学编程，最终创办了无障碍软件公司。", "pinyin": "Suīrán zài yì chǎng yìwài chēhuò zhōng bùxìng xiàzhī tānhuàn, dàn tā píngjiè jiānqiáng de yìlì zìxué biānchéng, zuìzhōng chuàngbàn le wúzhàng'ài ruǎnjiàn gōngsī.", "en": "Although his lower limbs were paralyzed in an unfortunate car accident, he taught himself programming through sheer willpower and founded an accessibility software company.", "es": "A pesar de que sus piernas quedaron paralizadas en un accidente, aprendió programación con tenacidad y fundó una empresa de software de accesibilidad."}, {"id": "#2", "hanzi": "突如其来的罕见特大暴雪导致该枢纽机场跑道严重结冰，供电系统受损，整个地面交通保障网络陷入全面瘫痪。", "pinyin": "Tūrúqílái de hǎnjiàn tìdà bàoxuě dǎozhì gāi shūniǔ jīchǎng pǎodào yánzhòng jiébīng, gōngdiàn xìtǒng shòusǔn, zhěnggè dìmiàn jiāotōng bǎozhàng wǎngluò xiànrù quánmiàn tānhuàn.", "en": "A sudden blizzard caused severe icing on the hub airport's runways and power damage, plunging the entire ground transport network into complete paralysis.", "es": "Una inesperada ventisca heló las pistas del aeropuerto neurálgico y dañó el suministro eléctrico, sumiendo la red de transporte en una parálisis total."}], "collocations": [{"hanzi": "陷入瘫痪", "en": "fall into complete paralysis / gridlock"}, {"hanzi": "下肢瘫痪", "en": "paralysis of the lower limbs"}, {"hanzi": "交通瘫痪", "en": "traffic gridlock / breakdown"}, {"hanzi": "全身瘫痪", "en": "quadriplegia / total paralysis"}, {"hanzi": "系统瘫痪", "en": "system outage / crash"}, {"hanzi": "导致瘫痪", "en": "lead to paralysis / standstill"}], "idioms": [{"hanzi": "半身不遂", "pinyin": "bàn shēn bù suí", "meaning_en": "hemiplegia; paralysis of one side of the body"}, {"hanzi": "寸步难行", "pinyin": "cùn bù nán xíng", "meaning_en": "cannot take a single step; stuck in immense difficulty"}, {"hanzi": "风烛残年", "pinyin": "fēng zhú cán nián", "meaning_en": "like a candle in the wind; in one's frail declining years"}, {"hanzi": "麻木不仁", "pinyin": "má mù bù rén", "meaning_en": "numb and unfeeling; utterly insensitive"}], "character_decomposition": [{"character": "瘫", "pinyin": "tān", "meaning_en": "paralysis; palsy; collapse", "meaning_es": "parálisis; postración; entumecimiento", "radical": "疒", "radical_meaning_en": "sickness / disease", "meaning_component": "疒 (sickness enclosure)", "sound_component": "难 (nán, difficulty/hardship)", "stroke_count": "15", "composition_type": "半包围结构", "etymology_and_mnemonic": "Phono-semantic character with disease radical (疒) enclosing hardship (难), describing motor incapacity.", "visual_mnemonic_story_en": "A sickbed frame (疒) bounds a patient enduring great physical hardship (难), unable to stand.", "visual_mnemonic_story_es": "El marco de una cama de hospital (疒) cobija a un enfermo en gran aflicción (难), sin poder moverse.", "tone_mnemonic_anchor": "55", "cangjie": "KTOE", "traditional": "癱"}, {"character": "痪", "pinyin": "huàn", "meaning_en": "paralysis; numbness; infirmity", "meaning_es": "parálisis; atrofia motora", "radical": "疒", "radical_meaning_en": "sickness / disease", "meaning_component": "疒 (sickness radical)", "sound_component": "奂 (huàn, broad/slackening phonetic)", "stroke_count": "14", "composition_type": "半包围结构", "etymology_and_mnemonic": "Phono-semantic character pairing disease (疒) with 奂 (huàn), describing bodily muscles losing tone.", "visual_mnemonic_story_en": "Under the illness shelter (疒), limbs slacken into complete immobility (奂).", "visual_mnemonic_story_es": "Bajo el techo de la enfermedad (疒), los músculos se relajan hasta la inmovilidad (奂).", "tone_mnemonic_anchor": "51", "cangjie": "KNBK", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "突如其来的疾病夺去了他的行走能力，让健步如飞的青年不得不面对身体瘫痪的严酷现实。经过漫长的内心挣扎，他在书海与文字中重获新生。肉体虽被束缚在轮椅之上，他的思想却穿越群山，奔向了辽阔的星空。", "pinyin": "Tūrúqílái de jíbìng duóqù le tā de xíngzǒu nénglì, ràng jiànbùrúfēi de qīngnián bùdébù miànduì shēntǐ tānhuàn de yánkù xiànshí. Jīngguò màncháng de nèixīn zhēngzhá, tā zài shūhǎi yǔ wénzì zhōng zhònghuò xīnshēng. Ròutǐ suī bèi shùfù zài lúnyǐ zhī shàng, tā de sīxiǎng què chuānyuè qúnshān, bènxiàng le liáokuò de xīngkōng.", "en": "A sudden illness stripped away his ability to walk, forcing the agile youth to confront physical paralysis. Following prolonged inner anguish, he found renewal in books and writing. Though his body was tethered to a wheelchair, his mind traversed mountains toward the vast stars.", "es": "Una inesperada enfermedad lo privó de caminar, obligándolo a afrontar la parálisis física. Tras una dura lucha interior, renació entre libros y palabras. Aunque su cuerpo quedó atado a una silla de ruedas, su pensamiento cruzó cordilleras hacia la inmensidad del cielo."}, {"id": "#2", "hanzi": "在高度互联的现代智慧城市中，核心电网与云服务器已成为维系运转的中枢神经。一旦遭遇恶意网络攻击或极端气象灾害，不仅可能导致城市金融与交通系统全面瘫痪，更会引发连锁安全危机。构建多重容灾备份机制已是当务之急。", "pinyin": "Zài gāodù hùlián de xiàndài zhìhuì chéngshì zhōng, héxīn diànwǎng yǔ yún fúwùqì yǐ chéngwéi wéixì yùnzhuǎn de zhōngshū shénjīng. Yídàn zāoyù è'yì wǎngluò gōngjī huò jíduān qìxiàng zāihài, bùjǐn kěnéng dǎozhì chéngshì jīnróng yǔ jiāotōng xìtǒng quánmiàn tānhuàn, gèng huì yǐnfā liánsuǒ ānquán wēijī. Gòujiàn duōchóng róngzāi bèifèn jīzhì yǐ shì dāngwùzhījí.", "en": "In interconnected smart cities, power grids and cloud servers are the central nervous system. A malicious cyberattack or extreme storm could plunge financial and transit networks into total paralysis and trigger cascading crises, making redundant disaster recovery urgent.", "es": "En las ciudades inteligentes, las redes eléctricas y servidores en la nube forman el sistema nervioso vital. Un ciberataque o tormenta extrema no solo paralizaría las finanzas y el transporte, sino que desataría crisis en cadena, haciendo urgente la protección de respaldo."}]}, {"meanings_summary": {"en": "to divorce; to dissolve a marriage", "es": "divorciarse; disolver el matrimonio"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Separating (离) from the marital bonds forged at dusk (婚) legally dissolves the union.", "composite_memory_hook_es": "Separarse (离) del vínculo matrimonial sellado en el crepúsculo (婚) constituye el divorcio legal.", "cultural_and_cognitive_roots": "Marriage in traditional China was a sacred cosmic and lineage union celebrated at dusk (昏); 'lí' (departure) paired with 'hūn' marks the institutional and emotional severing of this social bond.", "tone_sandhi_and_pitch_modulation": "35-55 pitch contour. The rising 2nd tone of lí ascends smoothly to meet the steady high level tone of hūn (55)."}, "semantic_boundary_contrasts": {"core_nuance": "离婚 specifically and exclusively refers to the formal or legal dissolution of a registered marriage.", "contrasts": [{"id": "1", "compared_word": "离婚 vs. 分手", "pinyin": "fēnshǒu", "analysis": "分手 is broadly applied to boyfriends, girlfriends, dating couples, or business partners breaking up, whereas 离婚 strictly requires legal marriage dissolution."}, {"id": "2", "compared_word": "离婚 vs. 分居", "pinyin": "fēnjū", "analysis": "分居 means living apart in separate residences while remaining legally married, whereas 离婚 dissolves marital status entirely."}, {"id": "3", "compared_word": "离婚 vs. 绝交", "pinyin": "juéjiāo", "analysis": "绝交 refers to severing social ties or friendship between friends or associates, unrelated to matrimonial law."}]}, "traps_and_cognates": {"look_alikes": [{"character": "禽", "pinyin": "qín", "meaning_en": "bird; fowl", "distinction_note": "Features 人 at the top instead of 亠; bottom has different interior"}, {"character": "篱", "pinyin": "lí", "meaning_en": "bamboo fence", "distinction_note": "Has bamboo radical 竹 on top of 离"}, {"character": "昏", "pinyin": "hūn", "meaning_en": "dusk; faint", "distinction_note": "Lacks the woman radical 女 on the left"}, {"character": "姻", "pinyin": "yīn", "meaning_en": "marriage by affinity", "distinction_note": "Has 因 on the right rather than 昏"}], "etymological_cognates": [{"character": "别", "pinyin": "bié", "gloss_en": "part; separate; sharing departure nuance"}, {"character": "分", "pinyin": "fēn", "gloss_en": "divide; split into parts"}, {"character": "嫁", "pinyin": "jià", "gloss_en": "marry off a woman in the 女 radical cluster"}, {"character": "娶", "pinyin": "qǔ", "gloss_en": "take a wife"}]}, "id": "9", "hanzi": "离婚", "pinyin": "lí hūn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to legally dissolve a marriage relationship between husband and wife", "definition_es": "disolver legalmente el vínculo matrimonial entre los cónyuges", "example_phrase": "协议离婚 (divorce by mutual agreement)"}], "example_sentences": [{"id": "#1", "hanzi": "经过反复沟通与理性权衡，他们发现彼此的价值观差异过大，最终决定和平离婚并共同承担抚养孩子的责任。", "pinyin": "Jīngguò fǎnfù gōutōng yǔ lǐxìng quánhéng, tāmen fāxiàn bǐcǐ de jiàzhíguān chāyì guò dà, zuìzhōng juédìng hépíng líhūn bìng gòngtóng chéngdān fǔyǎng háizi de zérèn.", "en": "After repeated dialogue and rational deliberation, they realized their value disparities were insurmountable and ultimately chose an amicable divorce, sharing custody of their child.", "es": "Tras un diálogo constante y reflexivo, comprendieron que sus diferencias eran insalvables y decidieron divorciarse de forma amistosa compartiendo la crianza de sus hijos."}, {"id": "#2", "hanzi": "最新出台的民法典关于婚姻家庭编的司法解释中，对夫妻共同债务清偿及诉讼离婚财产分割作出了更明确的指引。", "pinyin": "Zuìxīn chūtái de mínfǎdiǎn guānyú hūnyīn jiātíng biān de sīfǎ jiěshì zhōng, duì fūqī gòngtóng zhàiwù qīngchǎng jí sùsòng líhūn cáichǎn fēngē zuòchū le gèng míngquè de zhǐyǐn.", "en": "In recent judicial interpretations of the Civil Code marriage chapter, clearer guidelines were established regarding spousal joint debt settlement and property division in contentious divorces.", "es": "En la reciente interpretación judicial del Código Civil sobre familia, se fijaron pautas más claras para la liquidación de deudas conyugales y la división de bienes en juicios de divorcio."}], "collocations": [{"hanzi": "协议离婚", "en": "divorce by mutual agreement"}, {"hanzi": "诉讼离婚", "en": "divorce through judicial litigation"}, {"hanzi": "申请离婚", "en": "file for divorce"}, {"hanzi": "办理离婚", "en": "handle divorce formalities"}, {"hanzi": "离婚率", "en": "divorce rate"}, {"hanzi": "离婚冷静期", "en": "divorce cooling-off period"}], "idioms": [{"hanzi": "劳燕分飞", "pinyin": "láo yàn fēn fēi", "meaning_en": "part ways like swallows flying in opposite directions"}, {"hanzi": "一别两宽", "pinyin": "yì bié liǎng kuān", "meaning_en": "part company and wish each other peace and freedom"}, {"hanzi": "各奔前程", "pinyin": "gè bèn qián chéng", "meaning_en": "each goes their own separate way towards the future"}, {"hanzi": "破镜重圆", "pinyin": "pò jìng chóng yuán", "meaning_en": "a broken mirror joined together again; reunite after estrangement"}], "character_decomposition": [{"character": "离", "pinyin": "lí", "meaning_en": "leave; depart; separate; distance", "meaning_es": "separarse; alejarse; distancia; partir", "radical": "亠", "radical_meaning_en": "lid", "meaning_component": "禸 (animal footstep departing)", "sound_component": "离 (lí, mythological bird)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Anciently depicted an oriolar bird caught in a net that frees itself and takes flight away.", "visual_mnemonic_story_en": "A bird trapped under a canopy (亠) spreads its wings, leaving footmarks behind (禸) as it parts forever.", "visual_mnemonic_story_es": "Un ave atrapada bajo un cobertizo (亠) alza el vuelo dejando huellas (禸) al partir para siempre.", "tone_mnemonic_anchor": "35", "cangjie": "YUBB", "traditional": "離"}, {"character": "婚", "pinyin": "hūn", "meaning_en": "marry; wedding; marriage", "meaning_es": "casarse; boda; matrimonio", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (woman, the bride entering home)", "sound_component": "昏 (hūn, dusk/evening wedding rites)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Ideogram of taking a bride (女) home at twilight dusk (昏), the auspicious time for ancient nuptials.", "visual_mnemonic_story_en": "The bride (女) is escorted to her new home right as the sun sets at dusk (昏).", "visual_mnemonic_story_es": "La novia (女) es recibida en su nuevo hogar justo cuando el sol se oculta en el crepúsculo (昏).", "tone_mnemonic_anchor": "55", "cangjie": "VHPA", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "婚姻走到尽头并不意味着人生的彻底失败。选择离婚，有时是双方在认清彼此无法同行后，给予对方最体面的解脱。带着理智与温和告别过去，勇敢开始独立的生活，同样是对生命的真诚交代。", "pinyin": "Hūnyīn zǒudào jìntóu bìng bù yìwèizhe rénshēng de chèdǐ shībài. Xuǎnzé líhūn, yǒushí shì shuāngfāng zài rènqīng bǐcǐ wúfǎ tóngxíng hòu, jǐyǔ duìfāng zuì tǐmiàn de jiětuō. Dàizhe lǐzhì yǔ wēnhé gàobié guòqù, yǒnggǎn kāishǐ dúlì de shēnghuó, tóngyàng shì duì shēngmìng de zhēnchéng jiāodài.", "en": "The end of a marriage does not signify absolute personal defeat. Choosing divorce is sometimes the most dignified release after realizing that paths diverge. Saying farewell with rationality and beginning life anew is a sincere tribute to living.", "es": "Que un matrimonio llegue a su fin no implica un fracaso absoluto. Divorciarse es a veces la salida más digna tras comprender que los caminos se bifurcan. Despedirse con serenidad para emprender una vida independiente es un acto de honestidad vital."}, {"id": "#2", "hanzi": "随着社会经济结构演变与女性经济独立性的提高，当代社会的离婚观念呈现出理性化趋势。法律学者指出，健全的离婚财产分割机制与未成年子女探望保障，对于缓解单亲家庭抚育压力具有深远意义。", "pinyin": "Suízhe shèhuì jīngjì jiégòu yǎnbiàn yǔ nǚxìng jīngjì dúlìxìng de tígāo, dāngdài shèhuì de líhūn guānniàn chéngxiàn chū lǐxìnghuà qūshì. Fǎxué xuézhě zhǐchū, jiànquán de líhūn cáichǎn fēngē jīzhì yǔ wèichéngnián zǐnǚ tànwàng bǎozhàng, duìyú huǎnjiě dānqīn jiātíng fǔyù yālì jùyǒu shēnyuǎn yìyì.", "en": "With evolving economic structures and women's growing autonomy, modern views on divorce have become rationalized. Legal scholars note that sound property division and child visitation safeguards are vital to alleviating pressure on single-parent homes.", "es": "Con el desarrollo socioeconómico y la autonomía femenina, la concepción del divorcio se ha vuelto más racional. Los juristas destacan que mecanismos claros de división patrimonial y visitas protegen el bienestar de los hogares monoparentales."}]}, {"meanings_summary": {"en": "to commit suicide; suicide; self-destruction", "es": "suicidarse; suicidio; autodestrucción"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Directing the lethal blade (杀) against oneself (自) embodies the tragedy of suicide.", "composite_memory_hook_es": "Dirigir el arma letal (杀) contra uno mismo (自) representa la tragedia del suicidio.", "cultural_and_cognitive_roots": "Confucian morality historically regarded the body as a sacred inheritance from parents ('身体发肤，受之父母，不敢毁伤'). In modern biomedical and psychological contexts, 自杀 is approached as a treatable mental health crisis demanding compassionate societal intervention.", "tone_sandhi_and_pitch_modulation": "51-55 pitch contour. The falling 4th tone of zì (51) steps up into the high level 1st tone of shā (55)."}, "semantic_boundary_contrasts": {"core_nuance": "自杀 specifically denotes the intentional act of ending one's own physical life.", "contrasts": [{"id": "1", "compared_word": "自杀 vs. 自残", "pinyin": "zìcán", "analysis": "自残 refers to non-fatal deliberate self-harm or bodily mutilation, whereas 自杀 aims at ending one's life entirely."}, {"id": "2", "compared_word": "自杀 vs. 殉职", "pinyin": "xùnzhí", "analysis": "殉职 refers to dying in the heroic performance of official duty or line of duty, whereas 自杀 is taking one's own life."}, {"id": "3", "compared_word": "自杀 vs. 牺牲", "pinyin": "xīshēng", "analysis": "牺牲 denotes noble self-sacrifice for a greater societal cause or loss in war, whereas 自杀 carries psychological or individual distress connotations."}]}, "traps_and_cognates": {"look_alikes": [{"character": "白", "pinyin": "bái", "meaning_en": "white", "distinction_note": "Has only five strokes and lacks the top horizontal stroke of 自"}, {"character": "目", "pinyin": "mù", "meaning_en": "eye", "distinction_note": "Lacks the top diagonal dot/drop stroke that 自 possesses"}, {"character": "杂", "pinyin": "zá", "meaning_en": "mixed; miscellaneous", "distinction_note": "Features 九 on top instead of 乂 above 木"}, {"character": "条", "pinyin": "tiáo", "meaning_en": "strip; branch", "distinction_note": "Features 夂 (walking slowly) on top of 木"}], "etymological_cognates": [{"character": "己", "pinyin": "jǐ", "gloss_en": "self; own person"}, {"character": "死", "pinyin": "sǐ", "gloss_en": "death; mortality"}, {"character": "灭", "pinyin": "miè", "gloss_en": "extinguish; perish"}, {"character": "绝", "pinyin": "jué", "gloss_en": "sever; terminate"}]}, "id": "10", "hanzi": "自杀", "pinyin": "zì shā", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to intentionally end one's own life; commit suicide", "definition_es": "quitarse voluntariamente la vida; cometer suicidio", "example_phrase": "自杀未遂 (attempted suicide)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the act or tragedy of taking one's own life", "definition_es": "el acto de quitarse la propia vida", "example_phrase": "自杀干预 (suicide intervention)"}], "example_sentences": [{"id": "#1", "hanzi": "社会工作者通过二十四小时心理热线成功劝导了一名企图自杀的重度抑郁症患者，帮助其重拾生存的希望。", "pinyin": "Shèhuì gōngzuòzhě tōngguò èrshísì xiǎoshí xīnlǐ rèxiàn chénggōng quàndǎo le yì míng qǐtú zìshā de zhòngdù yìyùzhèng huànzhě, bāngzhù qí zhòngshí shēngcún de xīwàng.", "en": "Social workers via a 24-hour psychological hotline successfully dissuaded a patient with severe depression from suicide, helping restore hope for life.", "es": "Mediante una línea telefónica de ayuda 24 horas, los trabajadores sociales disuadieron del suicidio a una persona con depresión severa, devolviéndole la esperanza."}, {"id": "#2", "hanzi": "世界卫生组织公共卫生报告指出，建立全社会的自杀危机预警与干预网络，能够大幅降低青年群体的非正常死亡率。", "pinyin": "Shìjiè Wèishēng Zǔzhī gōnggòng wèishēng bàogào zhǐchū, jiànlì quán shèhuì de zìshā wēijī yùjǐng yǔ gānyù wǎngluò, nénggòu dàfú jiàngdī qīngnián qúntǐ de fēizhèngcháng sǐwánglǜ.", "en": "The World Health Organization public health report notes that establishing society-wide suicide crisis early warning and intervention networks significantly reduces youth mortality.", "es": "El informe de la Organización Mundial de la Salud señala que crear redes sociales de alerta e intervención ante el suicidio reduce la mortalidad juvenil de forma sustancial."}], "collocations": [{"hanzi": "自杀倾向", "en": "suicidal ideation / tendencies"}, {"hanzi": "自杀未遂", "en": "attempted suicide"}, {"hanzi": "自杀率", "en": "suicide rate"}, {"hanzi": "自杀干预", "en": "suicide intervention"}, {"hanzi": "企图自杀", "en": "attempt suicide"}, {"hanzi": "自杀式攻击", "en": "suicide attack"}], "idioms": [{"hanzi": "自取灭亡", "pinyin": "zì qǔ miè wáng", "meaning_en": "court one's own destruction; invite doom upon oneself"}, {"hanzi": "自绝于人", "pinyin": "zì jué yú rén", "meaning_en": "alienate oneself completely from the people"}, {"hanzi": "杀身成仁", "pinyin": "shā shēn chéng rén", "meaning_en": "sacrifice one's life for benevolence and justice"}, {"hanzi": "杀鸡儆猴", "pinyin": "shā jī jǐng hóu", "meaning_en": "kill the chicken to warn the monkey; punish one to warn others"}], "character_decomposition": [{"character": "自", "pinyin": "zì", "meaning_en": "self; oneself; from", "meaning_es": "uno mismo; propio; desde", "radical": "自", "radical_meaning_en": "nose / self", "meaning_component": "自 (pictogram of human nose, pointing to self)", "sound_component": "自 (inherent archaic phoneme)", "stroke_count": "6", "composition_type": "独体字", "etymology_and_mnemonic": "Originally a pictogram of the human nose; in ancient China, one pointed to one's nose to indicate 'myself'.", "visual_mnemonic_story_en": "A person points directly at the bridge of their nose (自) to say 'I, myself'.", "visual_mnemonic_story_es": "Una persona señala el tabique de su propia nariz (自) para referirse a 'sí mismo'.", "tone_mnemonic_anchor": "51", "cangjie": "HDU", "traditional": ""}, {"character": "杀", "pinyin": "shā", "meaning_en": "kill; slaughter; slay", "meaning_es": "matar; asesinar; sacrificar", "radical": "木", "radical_meaning_en": "wood / spear", "meaning_component": "木 (wooden weapon/shaft)", "sound_component": "乂 (scythe slashing stroke)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Traditional 殺 combined beast/hair with a hand holding a weapon; simplified to cross weapon strokes (乂/木).", "visual_mnemonic_story_en": "Crossing blades (乂) strike down upon a wooden post (木) to end life.", "visual_mnemonic_story_es": "Hojas cruzadas en aspa (乂) caen sobre una estaca de madera (木) segando la vida.", "tone_mnemonic_anchor": "55", "cangjie": "KCD", "traditional": "殺"}], "extended_reading_passages": [{"id": "#1", "hanzi": "生命是一场不可逆的旅程，无论遭遇多么沉重的阴霾，黎明的微光总在云层之后。在痛苦的深渊里，每一次向外界伸出求助之手的勇气，都是对自杀冲动的有力阻击。学会向世界坦露脆弱，才能重新握住生命的温度。", "pinyin": "Shēngmìng shì yì chǎng bùkěnì de lǚchéng, wúlùn zāoyù duōme chénzhòng de yīnmái, límíng de wēiguāng zǒng zài yúncéng zhīhòu. Zài tòngkǔ de shēnyuān lǐ, měi yí cì xiàng wàijiè shēnchū qiúzhù zhī shǒu de yǒngqì, dōu shì duì zìshā chōngdòng de yǒulì zǔjī. Xuéhuì xiàng shìjiè tǎnlù cuìruò, cáinǐng chóngxīn wòzhù shēngmìng de wēndù.", "en": "Life is an irreversible journey; no matter how heavy the shadows, the dawn's faint glow always awaits beyond the clouds. In deep suffering, every courage to reach out for help fends off suicidal impulses. Revealing vulnerability helps reclaim life's warmth.", "es": "La vida es un viaje sin retorno; por densas que sean las sombras, la claridad del alba siempre aguarda tras las nubes. En el sufrimiento, cada intento de pedir auxilio frena el impulso suicida. Mostrar vulnerabilidad permite recuperar la calidez de la existencia."}, {"id": "#2", "hanzi": "现代公共卫生与心理健康研究证明，自杀并非单纯的个人悲剧，而是复杂的社会心理危机。通过在社区与高校设立心理咨询中心，普及心理急救知识，能够建立起灵敏的自杀预防安全网，为迷茫的心灵构筑生命防线。", "pinyin": "Xiàndài gōnggòng wèishēng yǔ xīnlǐ jiànkāng yánjiū zhèngmíng, zìshā bìng fēi dānchún de gèrén bēijù, érshì fùzá de shèhuì xīnlǐ wēijī. Tōngguò zài shèqū yǔ gāoxiào shèlì xīnlǐ zīxún zhōngxīn, pǔjí xīnlǐ jíjiù zhīshì, nénggòu jiànlì qǐ língmǐn de zìshā yùfáng ānquánwǎng, wèi mímáng de xīnlíng gòuzhù shēngmìng fángxiàn.", "en": "Modern public health demonstrates that suicide is not merely an individual tragedy, but a complex social crisis. Establishing counseling clinics in communities and universities and teaching psychological first aid build an effective safety net for troubled minds.", "es": "La salud pública demuestra que el suicidio no es una simple tragedia personal, sino una crisis psicosocial compleja. Abrir centros de orientación en comunidades y universidades y difundir primeros auxilios psicológicos teje una red protectora para vidas en crisis."}]}, {"meanings_summary": {"en": "to complain; to grumble; to blame", "es": "quejarse; rezongar; lamentarse; culpar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Harboring in your chest (抱) a wounded heart full of resentment (怨) spills outward as constant complaining.", "composite_memory_hook_es": "Abrazar en el pecho (抱) un corazón herido de resentimiento (怨) se desborda en quejas continuas.", "cultural_and_cognitive_roots": "Chinese psychological tradition distinguishes between verbal expression and internal brooding; 'bàoyuàn' literally describes carrying (抱) grievances (怨) in one's bosom, reflecting the Buddhist-Taoist observation that harboring resentment harms internal harmony.", "tone_sandhi_and_pitch_modulation": "51-51 pitch contour. Two consecutive 4th tones require crisp, assertive downward falls (51 to 51) without merging into flat tones."}, "semantic_boundary_contrasts": {"core_nuance": "抱怨 focuses on venting vocal discontent or harboring chronic dissatisfaction toward unfavorable conditions or people.", "contrasts": [{"id": "1", "compared_word": "抱怨 vs. 埋怨", "pinyin": "mányuàn", "analysis": "埋怨 emphasizes finding fault with or blaming someone for minor blunders (often mild or implicit), whereas 抱怨 focuses on openly grumbling about hardship or poor conditions."}, {"id": "2", "compared_word": "抱怨 vs. 批评", "pinyin": "pīpíng", "analysis": "批评 is constructive or formal critique aimed at evaluating faults or correcting behaviour, whereas 抱怨 is an emotional venting of dissatisfaction."}, {"id": "3", "compared_word": "抱怨 vs. 控告", "pinyin": "kònggào", "analysis": "控告 is a formal legal term meaning to file criminal or legal charges, whereas 抱怨 is casual or emotional grumbling."}]}, "traps_and_cognates": {"look_alikes": [{"character": "跑", "pinyin": "pǎo", "meaning_en": "run", "distinction_note": "Has foot radical 𧾷 on the left instead of hand 扌"}, {"character": "饱", "pinyin": "bǎo", "meaning_en": "full; satisfied", "distinction_note": "Has food radical 饣 on the left instead of hand 扌"}, {"character": "恕", "pinyin": "shù", "meaning_en": "forgive; pardon", "distinction_note": "Features 如 over 心 instead of 夗"}, {"character": "怒", "pinyin": "nù", "meaning_en": "anger; furious", "distinction_note": "Features 奴 over 心 instead of 夗"}], "etymological_cognates": [{"character": "包", "pinyin": "bāo", "gloss_en": "wrap; phonetic root of 抱"}, {"character": "恨", "pinyin": "hèn", "gloss_en": "hate; remorse in the heart family"}, {"character": "悔", "pinyin": "huǐ", "gloss_en": "regret; remorse"}, {"character": "忧", "pinyin": "yōu", "gloss_en": "grief; worry"}]}, "id": "11", "hanzi": "抱怨", "pinyin": "bào yuàn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to express dissatisfaction, resentment, or grievance about an unpleasant situation or person", "definition_es": "expresar descontento, resentimiento o reproche ante una situación adversa o persona", "example_phrase": "抱怨天气 (complain about the weather)"}], "example_sentences": [{"id": "#1", "hanzi": "遇到生活中的挫折时，一味抱怨外界环境并不能解决问题，积极调整心态才是走出困境的关键。", "pinyin": "Yùdào shēnghuó zhōng de cuòzhé shí, yíwèi bàoyuàn wàijiè huánjìng bìng bù néng jiějué wèntí, jījí tiáozhěng xīntài cái shì zǒuchū kùnjìng de guānjiàn.", "en": "When encountering setbacks in life, blindly complaining about external circumstances resolves nothing; proactively adjusting one's mindset is the key out of adversity.", "es": "Al afrontar reveses en la vida, quejarse ciegamente del entorno no resuelve nada; ajustar una actitud proactiva es la clave para superar las dificultades."}, {"id": "#2", "hanzi": "在产品发布后的用户体验追踪调研中，不少消费者公开抱怨该款智能软件的操作界面复杂繁琐。", "pinyin": "Zài chǎnpǐn fābù hòu de yònghù tǐyàn zhuīzōng diàoyán zhōng, bùshǎo xiāofèizhě gōngkāi bàoyuàn gāi kuǎn zhìnéng ruǎnjiàn de cāozuò jièmiàn fùzá fánsuǒ.", "en": "In post-launch user experience tracking surveys, many consumers openly complained that the operating interface of the smart software was convoluted and cumbersome.", "es": "En las encuestas de seguimiento de experiencia de usuario tras el lanzamiento, numerosos consumidores se quejaron de que la interfaz del software resultaba confusa."}], "collocations": [{"hanzi": "经常抱怨", "en": "constantly complain"}, {"hanzi": "停止抱怨", "en": "stop complaining"}, {"hanzi": "抱怨命运", "en": "complain about fate"}, {"hanzi": "毫无抱怨", "en": "without any complaint"}, {"hanzi": "引起抱怨", "en": "cause complaints / grumbling"}, {"hanzi": "私下抱怨", "en": "grumble in private"}], "idioms": [{"hanzi": "怨天尤人", "pinyin": "yuàn tiān yóu rén", "meaning_en": "blame heaven and other people; complain of fate"}, {"hanzi": "满腹牢骚", "pinyin": "mǎn fù láo sāo", "meaning_en": "full of grievances and complaints"}, {"hanzi": "以德报怨", "pinyin": "yǐ dé bào yuàn", "meaning_en": "repay injury with kindness"}, {"hanzi": "任劳任怨", "pinyin": "rèn láo rèn yuàn", "meaning_en": "bear hardships and work without complaints"}], "character_decomposition": [{"character": "抱", "pinyin": "bào", "meaning_en": "hold in arms; hug; cherish; harbor", "meaning_es": "abrazar; sostener en brazos; albergar", "radical": "手", "radical_meaning_en": "hand", "meaning_component": "扌 (hand, embracing or holding)", "sound_component": "包 (bāo, wrap/bundle)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character combining hand (扌) with wrapping package (包), describing folding arms around something or harboring sentiments in one's bosom.", "visual_mnemonic_story_en": "Hands (扌) wrap tightly around a heavy bundle (包), holding grudges close to the chest.", "visual_mnemonic_story_es": "Las manos (扌) envuelven con fuerza un fardo (包), reteniendo amarguras contra el pecho.", "tone_mnemonic_anchor": "51", "cangjie": "QPU", "traditional": ""}, {"character": "怨", "pinyin": "yuàn", "meaning_en": "resent; blame; grievance; malice", "meaning_es": "resentimiento; rencor; agravio; quejarse", "radical": "心", "radical_meaning_en": "heart", "meaning_component": "心 (heart, inner emotional distress)", "sound_component": "夗 (yuàn, bent/turned over in bed)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic character of turning restlessly in bed (夗) over heartache (心), conveying brooding bitterness.", "visual_mnemonic_story_en": "Tossing restlessly at dusk (夗) because the heart (心) harbors unresolved grievances.", "visual_mnemonic_story_es": "Dar vueltas inquietas al anochecer (夗) porque el corazón (心) alberga rencores no resueltos.", "tone_mnemonic_anchor": "51", "cangjie": "NUP", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "生活就像一面镜子，你对它抱怨，它便回赠你阴霾；你对它微笑，它便报之以晴朗。无休止的抱怨如同一杯苦酒，不仅会腐蚀自己的心境，也会疏远身边的挚友。唯有放下抱怨，才能看清前路的花开。", "pinyin": "Shēnghuó jiù xiàng yí miàn jìngzi, nǐ duì tā bàoyuàn, tā biàn huízèng nǐ yīnmái; nǐ duì tā wēixiào, tā biàn bào zhī yǐ qínglǎng. Wúxiūzhǐ de bàoyuàn rútóng yì bēi kǔjiǔ, bùjǐn huì fǔshí zìjǐ de xīnjìng, yě huì shūyuǎn shēnbiān de zhìyǒu. Wéiyǒu fàngxià bàoyuàn, cáinǐng kànqīng qiánlù de huākāi.", "en": "Life is like a mirror: if you complain to it, it returns gloom; if you smile, it gives warmth. Ceaseless complaining is a bitter draught, eroding your mood and distancing friends. Only dropping complaints reveals the flowers ahead.", "es": "La vida es como un espejo: si te quejas ante ella, te devuelve sombras; si le sonríes, te brinda luz. Quejarse sin cesar es como un trago amargo que marchita el ánimo y aleja a los amigos. Dejar las quejas permite ver los senderos floridos."}, {"id": "#2", "hanzi": "在现代企业组织行为学中，员工无序的抱怨往往是内部管理沟通机制不畅的警示信号。卓越的管理者善于将消极抱怨转化为建设性反馈，通过构建开放的民主申诉通道，将潜在的团队怨气转化为流程革新的动力。", "pinyin": "Zài xiàndài qǐyè zǔzhī xíngwéixué zhōng, yuángōng wúxù de bàoyuàn wǎngwǎng shì nèibù guǎnlǐ gōutōng jīzhì bú chàng de jǐngshì xìnhào. Zhuóyuè de guǎnlǐzhě shànyú jiāng xiāojí bàoyuàn zhuǎnhuà wéi jiànshèxìng fǎnkuì, tōngguò gòujiàn kāifàng de mínzhǔ shēnsù tōngdào, jiāng qiánzài de tuánduì yuànqì zhuǎnhuà wéi liúchéng géxīn de dònglì.", "en": "In organizational behavior, disordered employee complaining serves as a red flag signaling obstructed internal communication. Astute managers convert complaints into constructive feedback, channeling latent team frustration into motivation for process innovation.", "es": "En el comportamiento organizativo moderno, las quejas continuas de los empleados advierten fallas de comunicación interna. Los líderes competentes transforman los descontentos en aportes constructivos, convirtiendo el malestar latente en motor de innovación."}]}, {"meanings_summary": {"en": "to care for; to cherish; to treasure; to take good care of", "es": "cuidar; proteger; mimar; valorar con esmero"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Pouring genuine love (爱) while extending hands to shield and protect (护) encapsulates caring deeply for someone or something.", "composite_memory_hook_es": "Brindar amor sincero (爱) extendiendo las manos para proteger (护) significa cuidar con devoción.", "cultural_and_cognitive_roots": "Derived from classical ethics of paternal benevolence and ecological stewardship ('仁民而爱物'); caring combines tender warmth with vigilant protective action.", "tone_sandhi_and_pitch_modulation": "51-51 pitch contour. Both syllables are sharp falling 4th tones; articulate each tone distinctly without swallowing the syllable finals."}, "semantic_boundary_contrasts": {"core_nuance": "爱护 conveys protective affection and conscientious care, used towards subordinates, youth, animals, or public objects.", "contrasts": [{"id": "1", "compared_word": "爱护 vs. 爱惜", "pinyin": "àixī", "analysis": "爱惜 focuses on not wasting or squandering scarce resources (e.g., 爱惜时间, 爱惜粮食), while 爱护 stresses protecting something fragile from damage or harm (e.g., 爱护公物, 爱护身体)."}, {"id": "2", "compared_word": "爱护 vs. 保护", "pinyin": "bǎohù", "analysis": "保护 focuses on shielding against external threats, attacks, or environmental legal frameworks, whereas 爱护 adds a layer of emotional warmth, gentleness, and moral duty."}, {"id": "3", "compared_word": "爱护 vs. 关心", "pinyin": "guānxīn", "analysis": "关心 denotes psychological solicitude and attentiveness to someone's welfare, whereas 爱护 emphasizes physical protection, stewardship, and preservation."}]}, "traps_and_cognates": {"look_alikes": [{"character": "受", "pinyin": "shòu", "meaning_en": "receive; bear", "distinction_note": "Lacks the upper horizontal roof stroke; different top component from 爱"}, {"character": "妥", "pinyin": "tuǒ", "meaning_en": "proper", "distinction_note": "Features 女 below 爫 instead of 友"}, {"character": "炉", "pinyin": "lú", "meaning_en": "stove; furnace", "distinction_note": "Has fire radical 火 on the left instead of hand 扌"}, {"character": "庐", "pinyin": "lú", "meaning_en": "thatched hut", "distinction_note": "Features 广 on the outside enclosing 户"}], "etymological_cognates": [{"character": "保", "pinyin": "bǎo", "gloss_en": "protect; preserve"}, {"character": "卫", "pinyin": "wèi", "gloss_en": "defend; guard"}, {"character": "惜", "pinyin": "xī", "gloss_en": "cherish; feel tender regret"}, {"character": "疼", "pinyin": "téng", "gloss_en": "love dearly; dote upon"}]}, "id": "12", "hanzi": "爱护", "pinyin": "ài hù", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to cherish, protect, and care tenderly for people (subordinates/children) or public property", "definition_es": "cuidar con cariño y proteger a personas o cuidar esmeradamente bienes públicos", "example_phrase": "爱护公物 (take good care of public property)"}], "example_sentences": [{"id": "#1", "hanzi": "班主任老师不仅悉心指导我们的学业，更像父母一样在日常生活中爱护每一个学生的身体与心理健康。", "pinyin": "Bānzhǔrèn lǎoshī bùjǐn xīxīn zhǐdǎo wǒmen de xuéyè, gèng xiàng fùmǔ yíyàng zài rìcháng shēnghuó zhōng àihù měi yí gè xuéshēng de shēntǐ yǔ xīnlǐ jiànkāng.", "en": "Our homeroom teacher not only guides our academics with diligence, but also cares for every student's physical and mental health like a parent.", "es": "El tutor no solo orienta nuestros estudios con esmero, sino que cuida la salud física y emocional de cada alumno con afecto maternal."}, {"id": "#2", "hanzi": "企业社会责任报告特别强调，所有员工在日常生产经营活动中都应自觉爱护厂区环境，严守生态保护红线。", "pinyin": "Qǐyè shèhuì zérèn bàogào tèbié qiángdiào, suǒyǒu yuángōng zài rìcháng shēngchǎn jīngyíng huó dòng zhōng dōu yīng zìjué àihù chǎngqū huánjìng, yánshǒu shēngtài bǎohù hóngxiàn.", "en": "The corporate social responsibility report specifically emphasized that all employees must take good care of the factory environment and respect ecological baselines.", "es": "El informe de responsabilidad social empresarial destacó que todos los empleados deben cuidar conscientemente las instalaciones y respetar las normas ecológicas."}], "collocations": [{"hanzi": "爱护公物", "en": "take care of public property"}, {"hanzi": "爱护环境", "en": "care for the environment"}, {"hanzi": "爱护花草", "en": "protect flora and greenery"}, {"hanzi": "倍加爱护", "en": "cherish with double care"}, {"hanzi": "爱护儿童", "en": "care for and protect children"}, {"hanzi": "爱护名誉", "en": "cherish one's reputation"}], "idioms": [{"hanzi": "爱不释手", "pinyin": "ài bù shì shǒu", "meaning_en": "love something so much one cannot part with it"}, {"hanzi": "爱憎分明", "pinyin": "ài zēng fēn míng", "meaning_en": "have a clear distinction between what to love and what to hate"}, {"hanzi": "官官相护", "pinyin": "guān guān xiāng hù", "meaning_en": "bureaucrats shielding one another; mutual complicity"}, {"hanzi": "自相庇护", "pinyin": "zì xiāng bì hù", "meaning_en": "shield each other mutually"}], "character_decomposition": [{"character": "爱", "pinyin": "ài", "meaning_en": "love; affection; cherish", "meaning_es": "amor; afecto; apreciar", "radical": "爫", "radical_meaning_en": "claw / hand", "meaning_component": "爫 (caring hands)", "sound_component": "冖 (protective shelter) + 友 (friend)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Depicts tender hands (爫) stretching a shelter (冖) over a cherished companion (友).", "visual_mnemonic_story_en": "A protective canopy (冖) extends gentle hands (爫) over a beloved friend (友).", "visual_mnemonic_story_es": "Un techo protector (冖) extiende manos cariñosas (爫) para amparar al amigo querido (友).", "tone_mnemonic_anchor": "51", "cangjie": "BBE", "traditional": "愛"}, {"character": "护", "pinyin": "hù", "meaning_en": "protect; guard; shield; shelter", "meaning_es": "proteger; cuidar; guardar; defender", "radical": "手", "radical_meaning_en": "hand", "meaning_component": "扌 (hand protecting/defending)", "sound_component": "户 (hù, household door)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character combining protective hand (扌) with home portal (户), conveying guarding the threshold.", "visual_mnemonic_story_en": "Hands (扌) stand guard at the entryway door (户) to protect those inside.", "visual_mnemonic_story_es": "Unas manos firmes (扌) guardan la puerta de casa (户) para proteger a la familia.", "tone_mnemonic_anchor": "51", "cangjie": "QHS", "traditional": "護"}], "extended_reading_passages": [{"id": "#1", "hanzi": "真正的爱护不是将幼苗置于温室中免受风雨，而是在它成长时给予坚定的庇护与守望。唯有懂得尊重自然的规律，悉心呵护弱小而不横加干涉，才能让生命在辽阔的天地间自由舒展，长成参天大树。", "pinyin": "Zhēnzhèng de àihù bú shì jiāng yòumiáo zhìyú wēnshì zhōng miǎnshòu fēngyǔ, érshì zài tā chéngzhǎng shí jǐyǔ jiāndìng de bìhù yǔ shǒuwàng. Wéiyǒu dǒngdé zūnzhòng zìrán de guīlǜ, xīxīn hēhù ruòxiǎo ér bù héngjiā gānshè, cáinǐng ràng shēngmìng zài liáokuò de tiāndì jiān zìyóu shūzhǎn, zhǎng chéng cāntiān dàshù.", "en": "True care does not mean locking seedlings in a greenhouse away from rain, but offering steady guardianship as they grow. Only by respecting nature's rhythm and tenderly protecting the young can life thrive freely into towering trees.", "es": "Cuidar de verdad no consiste en encerrar los brotes en un invernadero, sino en brindarles cobijo constante mientras crecen. Solo respetando la naturaleza y protegiendo a los frágiles sin asfixiarlos puede la vida florecer en árboles robustos."}, {"id": "#2", "hanzi": "在现代公共文化遗产保护与城市更新的交汇点上，全社会爱护历史古迹的意识成为衡量城市文明的重要标尺。通过立法规范古建筑修缮标准，引导市民自发参与文物巡查，方能实现珍贵历史文脉的永续传承。", "pinyin": "Zài xiàndài gōnggòng wénhuà yíchǎn bǎohù yǔ chéngshì gēngxīn de jiāohuìdiǎn shàng, quán shèhuì àihù lìshǐ gǔjì de yìshí chéngwéi héngliáng chéngshì wénmíng de zhòngyào biāochǐ. Tōngguò lìfǎ guīfàn gǔ jiànzhù xiūshàn biāozhǔn, yǐndǎo shìmín zìfā cānyù wénwù xúnchá, fāng néng shíxiàn zhēnguì lìshǐ wénmài de yǒngxù chuánchéng.", "en": "At the crossroads of heritage preservation and urban renewal, societal care for historical relics measures urban civility. Regulating restoration standards and guiding citizens to monitor heritage ensure that precious cultural roots endure.", "es": "En la intersección entre patrimonio y renovación urbana, la conciencia social de cuidar los monumentos mide la madurez de una ciudad. Regular la restauración de edificios antiguos y fomentar la participación ciudadana preserva las raíces culturales."}]}, {"meanings_summary": {"en": "marriage; matrimony; marital relationship", "es": "matrimonio; unión conyugal; nupcias"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Taking a bride at twilight dusk (婚) establishes the lifelong family affinity (姻) of sacred marriage.", "composite_memory_hook_es": "Celebrar las nupcias al crepúsculo (婚) crea el lazo de afinidad eterna (姻) en el matrimonio.", "cultural_and_cognitive_roots": "Both characters bear the woman radical (女); ancient Chinese matrimony merged the bridegroom's home welcoming at dusk ('hūn') with the alliance between two lineages ('yīn'). Thus, 婚姻 represents both emotional bonding and institutional kinship.", "tone_sandhi_and_pitch_modulation": "55-55 pitch contour. Both syllables are high level 1st tones (55); maintain an even, sustained pitch without dragging."}, "semantic_boundary_contrasts": {"core_nuance": "婚姻 specifically designates the formal institution, legal contract, and marital status of being husband and wife.", "contrasts": [{"id": "1", "compared_word": "婚姻 vs. 婚礼", "pinyin": "hūnlǐ", "analysis": "婚礼 is the one-time ceremonial wedding celebration or nuptial service, whereas 婚姻 refers to the ongoing institution, contract, and relationship."}, {"id": "2", "compared_word": "婚姻 vs. 感情", "pinyin": "gǎnqíng", "analysis": "感情 refers to subjective emotional feelings or affection between any persons, whereas 婚姻 is a socially ratified and legalized status."}, {"id": "3", "compared_word": "婚姻 vs. 恋爱", "pinyin": "liàn'ài", "analysis": "恋爱 denotes romantic courtship and dating before or without marriage, whereas 婚姻 entails civil rights and legal obligations."}]}, "traps_and_cognates": {"look_alikes": [{"character": "昏", "pinyin": "hūn", "meaning_en": "dusk; faint", "distinction_note": "Lacks the left woman radical 女"}, {"character": "荤", "pinyin": "hūn", "meaning_en": "meat; pungent food", "distinction_note": "Features grass radical 艹 on top of 军"}, {"character": "咽", "pinyin": "yān / yàn", "meaning_en": "throat; swallow", "distinction_note": "Has mouth radical 口 on the left instead of 女"}, {"character": "烟", "pinyin": "yān", "meaning_en": "smoke; cigarette", "distinction_note": "Has fire radical 火 on the left instead of 女"}], "etymological_cognates": [{"character": "嫁", "pinyin": "jià", "gloss_en": "marry off a daughter"}, {"character": "娶", "pinyin": "qǔ", "gloss_en": "marry a woman as wife"}, {"character": "妻", "pinyin": "qī", "gloss_en": "wife in the 女 radical network"}, {"character": "妇", "pinyin": "fù", "gloss_en": "married woman; matron"}]}, "id": "13", "hanzi": "婚姻", "pinyin": "hūn yīn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the legally or socially recognized union of two people as partners in a personal relationship", "definition_es": "unión legal y socialmente reconocida de dos personas como pareja conyugal", "example_phrase": "婚姻幸福 (happy marriage)"}], "example_sentences": [{"id": "#1", "hanzi": "在长达数十年的婚姻旅程中，相互信任与包容是化解生活琐事争执、保持感情历久弥新的坚实基石。", "pinyin": "Zài chángdá shù shí nián de hūnyīn lǚchéng zhōng, xiānghù xìnrèn yǔ bāoróng shì huàjiě shēnghuó suǒshì zhēngzhí, bǎochí gǎnqíng lìjiǔmíxīn de jiānshí jīshí.", "en": "Across a decades-long marital journey, mutual trust and tolerance are the solid cornerstone resolving daily domestic squabbles and keeping affection fresh.", "es": "A lo largo de décadas de matrimonio, la confianza y la tolerancia mutuas son la piedra angular para resolver roces diarios y mantener vivo el amor."}, {"id": "#2", "hanzi": "社会学学者通过跟踪调查指出，当代青年群体对婚姻制度的认知正从功能性结盟转向精神契合度优先。", "pinyin": "Shèhuìxué xuézhě tōngguò gēnzōng diàochá zhǐchū, dāngdài qīngnián qúntǐ duì hūnyīn zhìdù de rènzhī zhèng cóng gōngnéngxìng jiéméng zhuǎnxiàng jīngshén qìhédù yōuxiān.", "en": "Sociologists point out via longitudinal surveys that modern youth's perception of marriage is shifting from functional alliance toward spiritual compatibility.", "es": "A través de estudios sociológicos, se observa que los jóvenes conciben el matrimonio no como una alianza utilitaria, sino como una afinidad espiritual prioritaria."}], "collocations": [{"hanzi": "婚姻家庭", "en": "marriage and family"}, {"hanzi": "美满婚姻", "en": "happy / blessed marriage"}, {"hanzi": "婚姻法", "en": "marriage law"}, {"hanzi": "走进婚姻", "en": "enter into marriage"}, {"hanzi": "婚姻危机", "en": "marital crisis"}, {"hanzi": "包办婚姻", "en": "arranged marriage"}], "idioms": [{"hanzi": "男婚女嫁", "pinyin": "nán hūn nǚ jià", "meaning_en": "men and women marrying; getting married as a normal part of life"}, {"hanzi": "千里姻缘", "pinyin": "qiān lǐ yīn yuán", "meaning_en": "romantic affinity bringing people together from a thousand miles apart"}, {"hanzi": "秦晋之好", "pinyin": "qín jìn zhī hǎo", "meaning_en": "match between two families; firm matrimonial alliance"}, {"hanzi": "结为连理", "pinyin": "jié wéi lián lǐ", "meaning_en": "join together as intertwining branches; tie the knot"}], "character_decomposition": [{"character": "婚", "pinyin": "hūn", "meaning_en": "marry; wedding; bridegroom taking bride", "meaning_es": "casarse; matrimonio; desposar", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (woman / bride)", "sound_component": "昏 (hūn, dusk/evening wedding rites)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts taking a woman (女) as wife at dusk (昏), the auspicious time for ancient matrimonial rituals.", "visual_mnemonic_story_en": "At twilight dusk (昏), the carriage arrives to welcome the bride (女) into her new home.", "visual_mnemonic_story_es": "Al caer el crepúsculo (昏), el carruaje llega para recibir a la novia (女) en su nuevo hogar.", "tone_mnemonic_anchor": "55", "cangjie": "VHPA", "traditional": ""}, {"character": "姻", "pinyin": "yīn", "meaning_en": "marriage affinity; in-law relationship", "meaning_es": "afinidad matrimonial; lazo por matrimonio", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (woman, forming kinship ties)", "sound_component": "因 (yīn, origin/basis)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character pairing woman (女) with cause/foundation (因), denoting family ties forged through marriage.", "visual_mnemonic_story_en": "A woman (女) becomes the source and reason (因) uniting two completely separate families.", "visual_mnemonic_story_es": "Una mujer (女) se convierte en el motivo y la causa (因) que entrelaza a dos familias.", "tone_mnemonic_anchor": "55", "cangjie": "VWK", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "美满的婚姻绝非一劳永逸的誓言，而是两个人共同构筑的避风港。当最初的激情随岁月沉淀，唯有彼此的真诚与体谅，才能在日复一日的平淡琐碎中抵御风雨，让婚姻成为灵魂深处最温暖的依靠。", "pinyin": "Měimǎn de hūnyīn jué fēi yíláoyǒngyì de shìyán, érshì liǎng gè rén gòngtóng gòuzhù de bìfēnggǎng. Dāng zuìchū de jīqíng suí suìyuè chéndiàn, wéiyǒu bǐcǐ de zhēnchéng yǔ tǐliàng, cáinǐng zài rìfùyírì de píngdàn suǒsuì zhōng dǐyù fēngyǔ, ràng hūnyīn chéngwéi línghún shēnchù zuì wēnnuǎn de yīkào.", "en": "A fulfilling marriage is no one-and-done vow, but a shared haven built by two people. When initial passion settles with years, only sincerity and mutual understanding weather life's storms, making marriage the warmest anchor of the soul.", "es": "Un matrimonio pleno no es un juramento estático, sino un refugio edificado entre dos. Cuando la pasión juvenil madura con los años, solo la sinceridad y la comprensión mutua resisten las tormentas, convirtiendo la unión en el ancla más cálida del alma."}, {"id": "#2", "hanzi": "从法理学视角审视，现代婚姻制度兼具人身伦理属性与重大财产法效力。民法典婚姻家庭编通过完善婚前财产登记与夫妻共同债务认定标准，为保护弱势配偶权益与维护交易安全提供了坚实的制度保障。", "pinyin": "Cóng fǎlǐxué shìjiǎo shěnshì, xiàndài hūnyīn zhìdù jiānjù rénshēn lúnlǐ shǔxìng yǔ zhòngdà cáichǎnfǎ xiàolì. Mínfǎdiǎn hūnyīn jiātíng biān tōngguò wánshàn hūnqián cáichǎn dēngjì yǔ fūqī gòngtóng zhàiwù rèndìng biāozhǔn, wèi bǎohù ruòshì pèi'ǒu quányì yǔ wéihù jiāoyì ānquán tígōng le jiānshí de zhìdù bǎozhàng.", "en": "From a legal perspective, modern marriage embodies ethical personal relations and significant property rights. The Civil Code protects vulnerable spouses and preserves transaction security through refined premarital asset registration and joint debt standards.", "es": "Desde la jurisprudencia, el matrimonio moderno conjuga lazos éticos personales con efectos patrimoniales. El Código Civil protege a los cónyuges vulnerables y garantiza la seguridad jurídica regulando el patrimonio prematrimonial y las deudas comunes."}]}, {"meanings_summary": {"en": "to quarrel; to have a row; to bicker; verbal dispute", "es": "pelear; discutir; reñir; tener una discusión acalorada"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Loud, clamoring mouths (吵) locking into a rigid verbal confrontation frame (架) sparks a bitter quarrel.", "composite_memory_hook_es": "Bocas ruidosas (吵) que chocan en un forcejeo violento (架) dan lugar a una acalorada pelea verbal.", "cultural_and_cognitive_roots": "Chinese vernacular uses 'jià' (frame/scaffolding) metaphorically to describe squaring off in conflict; pairing it with vocal racket ('chǎo') designates verbal fights, contrasting with physical blows ('dǎjià').", "tone_sandhi_and_pitch_modulation": "214-51 contour. The 3rd tone of chǎo is pronounced as a half-3rd tone (21 low pitch) when immediately preceding the 4th tone of jià (51)."}, "semantic_boundary_contrasts": {"core_nuance": "吵架 refers specifically to loud, angry, emotional verbal quarreling or bickering between individuals.", "contrasts": [{"id": "1", "compared_word": "吵架 vs. 争论", "pinyin": "zhēnglùn", "analysis": "争论 refers to intellectual, academic, or professional argumentation where parties debate reasons objectively, whereas 吵架 is emotional venting and shouting."}, {"id": "2", "compared_word": "吵架 vs. 打架", "pinyin": "dǎjià", "analysis": "吵架 is strictly verbal warfare, whereas 打架 involves physical violence, punching, or brawling."}, {"id": "3", "compared_word": "吵架 vs. 发生争执", "pinyin": "fāshēng zhēngzhí", "analysis": "发生争执 is a formal, written-register description for experiencing disagreement, while 吵架 is everyday spoken Chinese for shouting matches."}]}, "traps_and_cognates": {"look_alikes": [{"character": "抄", "pinyin": "chāo", "meaning_en": "copy; plagiarize", "distinction_note": "Has hand radical 扌 on the left instead of mouth 口"}, {"character": "秒", "pinyin": "miǎo", "meaning_en": "second (time)", "distinction_note": "Has grain radical 禾 on the left instead of mouth 口"}, {"character": "驾", "pinyin": "jià", "meaning_en": "drive; harness", "distinction_note": "Features horse radical 马 at the bottom instead of wood 木"}, {"character": "贺", "pinyin": "hè", "meaning_en": "congratulate", "distinction_note": "Features shell radical 贝 at the bottom instead of wood 木"}], "etymological_cognates": [{"character": "闹", "pinyin": "nào", "gloss_en": "noisy; make a scene"}, {"character": "争", "pinyin": "zhēng", "gloss_en": "contend; dispute"}, {"character": "吵", "pinyin": "chǎo", "gloss_en": "noisy; root morpheme"}, {"character": "打", "pinyin": "dǎ", "gloss_en": "strike; partner morpheme in 打架"}]}, "id": "14", "hanzi": "吵架", "pinyin": "chǎo jià", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Colloquial", "definition_en": "to engage in an angry, loud verbal altercation or dispute with someone", "definition_es": "sostener una riña o disputa verbal acalorada y en voz alta con alguien", "example_phrase": "跟邻居吵架 (quarrel with a neighbor)"}], "example_sentences": [{"id": "#1", "hanzi": "昨天下午因为对周末出游计划意见不合，我和同桌大声吵架，但今天早上我们又笑着和好了。", "pinyin": "Zuótiān xiàwǔ yīnwèi duì zhōumò chūyóu jìhuà yìjiàn bù hé, wǒ hé tóngzhuō dàshēng chǎojià, dàn jīntiān zǎoshang wǒmen yòu xiào zhe héhǎo le.", "en": "Yesterday afternoon, having differing opinions on weekend outing plans, my deskmate and I had a loud quarrel, but this morning we laughed and reconciled.", "es": "Ayer por la tarde, por no ponernos de acuerdo sobre el paseo del fin de semana, mi compañero y yo tuvimos una fuerte discusión, pero esta mañana nos reconciliamos con una sonrisa."}, {"id": "#2", "hanzi": "人际沟通培训讲师指出，团队成员在方案研讨中就事论事的激烈争论是正常的，但绝不能演化为情绪化的人身攻击与吵架。", "pinyin": "Rénjì gōutōng péixùn jiǎngshī zhǐchū, tuánduì chéngyuán zài fāng'àn yántǎo zhōng jiùshìlùnshì de jīliè zhēnglùn shì zhèngcháng de, dàn jué bù néng yǎnhuà wéi qíngxùhuà de rénshēng gōngjī yǔ chǎojià.", "en": "The interpersonal communication trainer noted that spirited, objective debate over proposals among team members is healthy, but it must never degenerate into personal bickering.", "es": "El instructor de comunicación interpersonal señaló que el debate técnico apasionado es productivo, pero nunca debe degenerar en ataques personales ni discusiones destructivas."}], "collocations": [{"hanzi": "激烈吵架", "en": "quarrel fiercely"}, {"hanzi": "大吵一架", "en": "have a big row"}, {"hanzi": "频繁吵架", "en": "quarrel frequently"}, {"hanzi": "夫妻吵架", "en": "spouses bickering"}, {"hanzi": "当街吵架", "en": "quarrel in the public street"}, {"hanzi": "吵架闹别扭", "en": "squabble and give the cold shoulder"}], "idioms": [{"hanzi": "吵吵闹闹", "pinyin": "chāo chao nào nào", "meaning_en": "noisy and turbulent; constantly squabbling"}, {"hanzi": "鸡犬不宁", "pinyin": "jī quǎn bù níng", "meaning_en": "even fowls and dogs are disturbed; utterly tumultuous"}, {"hanzi": "唇枪舌剑", "pinyin": "chún qiāng shé jiàn", "meaning_en": "lips as spears and tongues as swords; fierce war of words"}, {"hanzi": "各执一词", "pinyin": "gè zhí yì cí", "meaning_en": "each sticks to their own version of the story"}], "character_decomposition": [{"character": "吵", "pinyin": "chǎo", "meaning_en": "make noise; quarrel; clamor; noisy", "meaning_es": "hacer ruido; pelear; discutir; ruidoso", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (mouth, making vocal racket)", "sound_component": "少 (shǎo, phonetic match)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character pairing loud mouth (口) with 少 (shǎo), describing noisy verbal squabbling.", "visual_mnemonic_story_en": "Opening a loud mouth (口) with small (少) self-restraint creates clamor.", "visual_mnemonic_story_es": "Abrir una boca (口) ruidosa con poca (少) prudencia provoca escándalo y disputas.", "tone_mnemonic_anchor": "214", "cangjie": "RFH", "traditional": ""}, {"character": "架", "pinyin": "jià", "meaning_en": "frame; rack; support; fight/brawl", "meaning_es": "estante; armazón; pelear; riña", "radical": "木", "radical_meaning_en": "wood", "meaning_component": "木 (wooden timber frame)", "sound_component": "加 (jiā, add/impose phonetics)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Depicts assembling wooden timbers (木) by adding (加) them together; extended colloquially to clashing or throwing hands/words in a fight (打架/吵架).", "visual_mnemonic_story_en": "Putting together added force (加) over timber stakes (木) builds a fighting posture.", "visual_mnemonic_story_es": "Aplicar fuerza adicional (加) sobre estacas de madera (木) levanta una postura de pelea.", "tone_mnemonic_anchor": "51", "cangjie": "KRD", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "人与人之间的相处难免会有摩擦，但无休止的吵架只会消耗彼此的情感。真正成熟的沟通，是在情绪翻涌时懂得克制退让，用倾听代替指责。化解矛盾需要的不是争辩输赢，而是理解对方的委屈。", "pinyin": "Rén yǔ rén zhījiān de xiāngchǔ nánmiǎn huì yǒu mócā, dàn wúxiūzhǐ de chǎojià zhǐ huì xiāohào bǐcǐ de qínggǎn. Zhēnzhèng chéngshú de gōutōng, shì zài qíngxù fānyǒng shí dǒngdé kèzhì tuìràng, yòng qīngtīng dàitì zhǐzé. Huàjiě máodùn xūyào de bú shì zhēngbiàn shūyíng, érshì lǐjiě duìfāng de wěiqu.", "en": "Friction is inevitable among people, but endless quarreling merely drains mutual affection. Mature communication means practicing restraint when emotions surge and listening rather than blaming. Resolving conflict requires understanding, not winning arguments.", "es": "Los roces en el trato humano son inevitables, pero pelear sin cesar agota el cariño mutuo. La madurez consiste en contenerse cuando las emociones hierven y escuchar en vez de acusar. Resolver discordias exige comprender los sentimientos del otro."}, {"id": "#2", "hanzi": "在现代企业团队协作中，将人际吵架与业务研讨严格区分，是保障项目平稳推进的关键组织规则。健康的团队文化鼓励针对技术难点各抒己见，但严禁将业务分歧异化为人身攻击与非理性情绪宣泄。", "pinyin": "Zài xiàndài qǐyè tuánduì xiézuò zhōng, jiāng rénjì chǎojià yǔ yèwù yántǎo yángé qūfēn, shì bǎozhàng xiàngmù píngwěn tuījìn de guānjiàn zǔzhī guīzé. Jiànkāng de tuánduì wénhuà gǔlì zhēnduì jìshù nándiǎn gèshūjǐjiàn, dàn yánjìn jiāng yèwù fēnqí yìhuà wéi rénshēng gōngjī yǔ fēilǐxìng qíngxù xuānxiè.", "en": "In modern corporate teamwork, strictly demarcating interpersonal bickering from technical deliberation is vital for project advancement. Healthy cultures encourage diverse views on technical hurdles while banning personal attacks and emotional outbursts.", "es": "En la colaboración empresarial moderna, separar los altercados personales del debate técnico asegura el avance del proyecto. Una cultura sólida fomenta el debate de ideas pero prohíbe que las discrepancias degeneren en ataques personales."}]}, {"meanings_summary": {"en": "(of husband and wife) to respect each other like honored guests; mutual respect in marriage", "es": "(entre cónyuges) respetarse mutuamente como huéspedes de honor; respeto conyugal ejemplar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Treating each other (相) with solemn reverence (敬) just as (如) one honors an esteemed guest (宾) defines matrimonial decorum.", "composite_memory_hook_es": "Tratarse mutuamente (相) con profundo respeto (敬) igual que (如) a un huésped distinguido (宾) define la virtud matrimonial.", "cultural_and_cognitive_roots": "Originating in the Spring and Autumn Annals (左传·僖公三十三年), when Xi Que and his wife were observed weeding fields together with mutual courtesy like honoring an imperial guest. It became the highest traditional ideal of marital decorum without excessive casualness.", "tone_sandhi_and_pitch_modulation": "55-51-35-55 pitch pattern. Articulate four balanced syllables with distinct high level (55), falling (51), rising (35), and high level (55) contours."}, "semantic_boundary_contrasts": {"core_nuance": "相敬如宾 specifically characterizes married couples treating one another with dignified courtesy, mutual deference, and unflagging decorum.", "contrasts": [{"id": "1", "compared_word": "相敬如宾 vs. 举案齐眉", "pinyin": "jǔ'ànqíméi", "analysis": "Both describe marital respect, but 举案齐眉 historically highlighted the wife's dutiful deference to the husband, whereas 相敬如宾 emphasizes symmetrical, mutual respect between both partners."}, {"id": "2", "compared_word": "相敬如宾 vs. 恩爱如初", "pinyin": "ēn'àirúchū", "analysis": "恩爱如初 emphasizes the undiminished emotional passion and affection of early romance, while 相敬如宾 emphasizes polite restraint, decorum, and mutual reverence."}, {"id": "3", "compared_word": "相敬如宾 vs. 亲密无间", "pinyin": "qīnmìwújiàn", "analysis": "亲密无间 denotes boundless casual intimacy without formalities, whereas 相敬如宾 maintains a respectful, courteous boundary to avoid domestic contempt."}]}, "traps_and_cognates": {"look_alikes": [{"character": "警", "pinyin": "jǐng", "meaning_en": "warn; police", "distinction_note": "Features 言 (speech) at the bottom instead of 攵 alone"}, {"character": "惊", "pinyin": "jīng", "meaning_en": "startle; surprise", "distinction_note": "Has heart radical 忄 on the left with 京"}, {"character": "滨", "pinyin": "bīn", "meaning_en": "shore; coast", "distinction_note": "Has water radical 氵 on the left side of 宾"}, {"character": "摈", "pinyin": "bìn", "meaning_en": "discard; reject", "distinction_note": "Has hand radical 扌 on the left side of 宾"}], "etymological_cognates": [{"character": "礼", "pinyin": "lǐ", "gloss_en": "ritual propriety; decorum"}, {"character": "客", "pinyin": "kè", "gloss_en": "guest; visitor under the roof radical"}, {"character": "待", "pinyin": "dài", "gloss_en": "treat; receive guests"}, {"character": "尊", "pinyin": "zūn", "gloss_en": "revere; honor with wine vessel"}]}, "id": "15", "hanzi": "相敬如宾", "pinyin": "xiāng jìng rú bīn", "level": "HSK 5", "part_of_speech": "Idiom", "senses": [{"sense_number": "1", "part_of_speech": "Idiom", "register": "Literary", "definition_en": "married couples treating each other with the profound courtesy, decorum, and deference due to an honored guest", "definition_es": "tratarse los cónyuges con la consideración, reverencia y cortesía debidas a un huésped de honor", "example_phrase": "夫妻相敬如宾 (husband and wife respect each other like guests)"}], "example_sentences": [{"id": "#1", "hanzi": "这对学者夫妇相伴走过半个世纪的风雨，在日常生活中始终相敬如宾，被后辈学者传为佳话。", "pinyin": "Zhè duì xuézhě fūfù xiāngbàn zǒuguò bàn gè shìjì de fēngyǔ, zài rìcháng shēnghuó zhōng shǐzhōng xiāngjìngrúbīn, bèi hòubèi xuézhě chuán wéi jiāhuà.", "en": "This scholar couple walked through half a century of trials together, always respecting each other like honored guests in daily life, hailed by younger scholars as an exemplary union.", "es": "Este matrimonio de académicos compartió medio siglo de vicisitudes tratándose siempre con mutuo respeto ejemplar, admirados por las nuevas generaciones."}, {"id": "#2", "hanzi": "中国传统家风研究专家指出，“相敬如宾”不仅是一种婚姻处世哲学，更是维护古代家族制度秩序稳定的伦理基石。", "pinyin": "Zhōngguó chuántǒng jiāfēng yánjiū zhuānjiā zhǐchū, “xiāngjìngrúbīn” bùjǐn shì yì zhǒng hūnyīn chǔshì zhéxué, gèng shì wéihù gǔdài jiāzú zhìdù zhìxù wěndìng de lúnlǐ jīshí.", "en": "Experts on traditional Chinese family values note that 'respecting each other like guests' is not merely a philosophy of marriage, but an ethical cornerstone ensuring family stability.", "es": "Especialistas en tradiciones familiares chinas señalan que respetarse como huéspedes en el matrimonio constituye la base ética de la armonía y estabilidad del hogar."}], "collocations": [{"hanzi": "夫妻相敬如宾", "en": "husband and wife respect each other like guests"}, {"hanzi": "相敬如宾数十年", "en": "respect each other like guests for decades"}, {"hanzi": "始终相敬如宾", "en": "remain courteous and respectful like guests throughout"}, {"hanzi": "相敬如宾的生活", "en": "a life of mutual marital courtesy"}, {"hanzi": "相敬如宾的相处模式", "en": "a relationship dynamic of mutual deference"}, {"hanzi": "做到了相敬如宾", "en": "achieved mutual deference in marriage"}], "idioms": [{"hanzi": "举案齐眉", "pinyin": "jǔ àn qí méi", "meaning_en": "lift the food tray to eyebrow level; exemplary spousal respect and harmony"}, {"hanzi": "琴瑟和鸣", "pinyin": "qín sè hé míng", "meaning_en": "harmony of zither and lute; blissful marital accord"}, {"hanzi": "夫唱妇随", "pinyin": "fū chàng fù suí", "meaning_en": "husband and wife in happy harmony"}, {"hanzi": "白头偕老", "pinyin": "bái tóu xié lǎo", "meaning_en": "live together until white hair; grow old together"}], "character_decomposition": [{"character": "相", "pinyin": "xiāng", "meaning_en": "mutually; each other", "meaning_es": "mutuamente; el uno al otro", "radical": "目", "radical_meaning_en": "eye", "meaning_component": "目 (eye looking) + 木 (tree/target observed)", "sound_component": "木 (phonetic association)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts an eye (目) carefully examining a tree (木), extended to mutually gazing and interacting.", "visual_mnemonic_story_en": "An eye (目) looks across at a slender tree (木), symbolizing mutual observation.", "visual_mnemonic_story_es": "Un ojo (目) contempla un árbol (木), reflejando una interacción y mirada mutua.", "tone_mnemonic_anchor": "55", "cangjie": "DUB", "traditional": ""}, {"character": "敬", "pinyin": "jìng", "meaning_en": "respect; honor; revere", "meaning_es": "respetar; venerar; honrar", "radical": "攵", "radical_meaning_en": "strike / action", "meaning_component": "攵 (disciplined action)", "sound_component": "苟 (jìng, alert posture)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts adopting an alert, humble stance (苟) under self-discipline (攵), denoting reverence.", "visual_mnemonic_story_en": "Under self-discipline (攵), one bows attentively with profound respect (敬).", "visual_mnemonic_story_es": "Con autocontrol sereno (攵), uno se inclina mostrando respeto y reverencia.", "tone_mnemonic_anchor": "51", "cangjie": "TKOK", "traditional": ""}, {"character": "如", "pinyin": "rú", "meaning_en": "as if; like; similar to", "meaning_es": "como; al igual que; semejante a", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (woman / harmony)", "sound_component": "口 (mouth)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Ideogram of speech (口) complying harmoniously with instruction (女), signifying 'like' or 'accordance'.", "visual_mnemonic_story_en": "Speaking from the mouth (口) with the graceful compliance of a lady (女) makes actions resemble words.", "visual_mnemonic_story_es": "Expresarse desde la boca (口) con elegancia (女) asegura que todo transcurra conforme a lo debido.", "tone_mnemonic_anchor": "35", "cangjie": "VR", "traditional": ""}, {"character": "宾", "pinyin": "bīn", "meaning_en": "guest; visitor; receive with honor", "meaning_es": "huésped; invitado de honor", "radical": "宀", "radical_meaning_en": "roof", "meaning_component": "宀 (hall/mansion welcoming guests)", "sound_component": "兵 / 贝 (bīn, precious gift exchange)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Depicts a guest welcomed under the roof (宀) presented with gifts of cowrie shells (贝).", "visual_mnemonic_story_en": "Under the mansion roof (宀), gifts are exchanged to honor the arriving guest (宾).", "visual_mnemonic_story_es": "Bajo el techo señorial (宀), se ofrecen presentes para agasajar al huésped de honor (宾).", "tone_mnemonic_anchor": "55", "cangjie": "JOMC", "traditional": "賓"}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国古人将相敬如宾视为夫妻相处的最高境界。爱情最初由激情点燃，但要在数十年的柴米油盐中免于厌倦，唯有以礼相待。将伴侣视作尊贵的宾客，言语有度，举止有礼，才能让婚姻在岁月流转中沉淀出温润的优雅。", "pinyin": "Zhōngguó gǔrén jiāng xiāngjìngrúbīn shìwéi fūqī xiāngchǔ de zuìgāo jìngjiè. Àiqíng zuìchū yóu jīqíng diǎnrán, dàn yào zài shù shí nián de cháimǐyóuyán zhōng miǎnyú yànjuàn, wéiyǒu yǐ lǐ xiāng dài. Jiāng bànlǚ shìzuò zūnguì de bīnkè, yányǔ yǒudù, jǔzhǐ yǒulǐ, cáinǐng ràng hūnyīn zài suìyuè liúzhuǎn zhōng chéndiàn chū wēnrùn de yōuyǎ.", "en": "Ancient Chinese regarded mutual respect like guests as the summit of matrimony. Passion kindles love, but avoiding domestic weariness over decades requires courtesy. Treating your partner as an honored guest allows marriage to distill gentle elegance over time.", "es": "Los antiguos concebían el respeto mutuo como la cúspide conyugal. La pasión enciende el amor, pero para sortear el tedio cotidiano durante décadas se precisa cortesía. Considerar al cónyuge como un huésped de honor destila una serena elegancia matrimonial."}, {"id": "#2", "hanzi": "在现代文化语境中，相敬如宾这一传统成语常被赋予关于婚姻边界感的新内涵。现代家庭咨询顾问指出，过度亲昵往往容易模糊彼此的心理界限，引发不必要的控制欲。保持如宾客般的相互尊重与独立空间，是构建健康伙伴式婚姻的重要法则。", "pinyin": "Zài xiàndài wénhuà yǔjìng zhōng, xiāngjìngrúbīn zhè yì chuántǒng chéngyǔ cháng bèi fùyǔ guānyú hūnyīn biānjiègǎn de xīn nèihán. Xiàndài jiātíng zīxún gùwèn zhǐchū, guòdù qīnnì wǎngwǎng róngyì móhu bǐcǐ de xīnlǐ jièxiàn, yǐnfā búbìyào de kòngzhìyù. Bǎochí rú bīnkè bān de xiānghù zūnzhòng yǔ dúlì kōngjiān, shì gòujiàn jiànkāng huǒbànshì hūnyīn de zhòngyào fǎzé.", "en": "In contemporary contexts, respecting each other like guests gains new meaning around marital psychological boundaries. Counselors note that unchecked familiarity blurs boundaries and fuels possessiveness. Preserving courteous space is a vital rule for healthy partnership marriage.", "es": "En la psicología contemporánea, respetarse como huéspedes cobra nuevo sentido sobre los límites personales en la pareja. La excesiva confianza borra las fronteras afectivas y alienta el afán de control. Mantener un espacio de respeto mutuo forja una convivencia sana y equilibrada."}]}, {"meanings_summary": {"en": "secretly; inwardly; quietly to oneself", "es": "en secreto; para sus adentros; secretamente; interiormente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Repeating the character for hidden darkness (暗暗) depicts internal feelings concealed deep inside without a trace.", "composite_memory_hook_es": "Duplicar el carácter de la penumbra secreta (暗暗) retrata pensamientos guardados para los adentros.", "cultural_and_cognitive_roots": "Reduplication of monosyllabic adjectives/adverbs in Chinese produces subjective emotional vividness. 'Àn' (unseen darkness) reduplicated conveys intense psychological interiority shielded from the public gaze.", "tone_sandhi_and_pitch_modulation": "51-51 pitch contour. In natural speech, reduplicated adverbs may soften slightly on the second syllable, yet both retain falling tonal trajectories."}, "semantic_boundary_contrasts": {"core_nuance": "暗暗 specifies psychological states, private thoughts, or covert intentions kept hidden from outward manifestation.", "contrasts": [{"id": "1", "compared_word": "暗暗 vs. 偷偷", "pinyin": "tōutōu", "analysis": "偷偷 stresses physical stealth and sneaking around to evade physical detection, while 暗暗 describes purely psychological internal feelings and unspoken intentions."}, {"id": "2", "compared_word": "暗暗 vs. 悄悄", "pinyin": "qiāoqiāo", "analysis": "悄悄 emphasizes lowering volume or moving without sound, whereas 暗暗 implies completely private contemplation without any outward reveal."}, {"id": "3", "compared_word": "暗暗 vs. 秘密", "pinyin": "mìmì", "analysis": "秘密 is an adjective/noun meaning confidential or classified, whereas 暗暗 is strictly an adverb modifying internal psychological verbs."}]}, "traps_and_cognates": {"look_alikes": [{"character": "明", "pinyin": "míng", "meaning_en": "bright; clear", "distinction_note": "Features 月 (moon) on the right instead of 音 (sound); direct antonym"}, {"character": "晴", "pinyin": "qíng", "meaning_en": "sunny; clear sky", "distinction_note": "Features 青 on the right rather than 音"}, {"character": "暗", "pinyin": "àn", "meaning_en": "dark", "distinction_note": "Headword character itself"}, {"character": "喑", "pinyin": "yīn", "meaning_en": "mute; silent", "distinction_note": "Features mouth radical 口 on the left instead of sun 日"}], "etymological_cognates": [{"character": "默", "pinyin": "mò", "gloss_en": "silent; quiet"}, {"character": "潜", "pinyin": "qián", "gloss_en": "submerged; covert"}, {"character": "隐", "pinyin": "yǐn", "gloss_en": "hidden; concealed"}, {"character": "秘", "pinyin": "mì", "gloss_en": "secret; confidential"}]}, "id": "16", "hanzi": "暗暗", "pinyin": "àn àn", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "acting or feeling inwardly without revealing thoughts or intentions to others", "definition_es": "sentir o actuar interiormente sin exteriorizar las intenciones ni pensamientos", "example_phrase": "暗暗下定决心 (inwardly resolve to oneself)"}], "example_sentences": [{"id": "#1", "hanzi": "看到好友在舞台上取得耀眼的成就，我由衷替他高兴，同时也在心底暗暗下定决心要更加努力。", "pinyin": "Kàndào hǎoyǒu zài wǔtái shàng qǔdé yàoyǎn de chéngjiù, wǒ yóuzhōng tì tā gāoxìng, tóngshí yě zài xīndǐ àn'àn xiàdìng juéxīn yào gèngjiā nǔlì.", "en": "Seeing my close friend achieve dazzling success on stage, I was genuinely happy for him and simultaneously resolved inwardly to work harder.", "es": "Al ver a mi buen amigo triunfar en el escenario, me alegré sinceramente por él y a la vez decidí para mis adentros esforzarme con mayor ahínco."}, {"id": "#2", "hanzi": "面对竞争对手在核心技术专利上的先发优势，研发主管在会议室里暗暗盘算着弯道超车的替代方案。", "pinyin": "Miànduì jìngzhēng duìshǒu zài héxīn jìshù zhuānlì shàng de xiānfā yōushì, yánfā zhǔguǎn zài huìyìshì lǐ àn'àn pánsuàn zhe wāndào chāochē de tìdài fāng'àn.", "en": "Confronting the rival's first-mover advantage in core technology patents, the R&D director sat in the conference room inwardly calculating alternative leapfrogging schemes.", "es": "Frente a la ventaja de la competencia en patentes tecnológicas, el director de desarrollo calculaba en silencio estrategias alternativas para superarlos."}], "collocations": [{"hanzi": "暗暗高兴", "en": "rejoice secretly to oneself"}, {"hanzi": "暗暗下决心", "en": "inwardly make up one's mind"}, {"hanzi": "暗暗吃惊", "en": "secretly astonished"}, {"hanzi": "暗暗发誓", "en": "vow silently inwardly"}, {"hanzi": "暗暗观察", "en": "observe quietly and unnoticed"}, {"hanzi": "暗暗佩服", "en": "admire someone in secret"}], "idioms": [{"hanzi": "明察暗访", "pinyin": "míng chá àn fǎng", "meaning_en": "investigate openly and secretly; thorough undercover probe"}, {"hanzi": "暗度陈仓", "pinyin": "àn dù chén cāng", "meaning_en": "cross Chencang in secret; do something clandestine under distraction"}, {"hanzi": "潜移默化", "pinyin": "qián yí mò huà", "meaning_en": "exert a subtle, imperceptible influence over time"}, {"hanzi": "弃暗投明", "pinyin": "qì àn tóu míng", "meaning_en": "abandon the darkness and cross over to the light"}], "character_decomposition": [{"character": "暗", "pinyin": "àn", "meaning_en": "dark; dim; secret; hidden", "meaning_es": "oscuro; tenue; secreto; oculto", "radical": "日", "radical_meaning_en": "sun / light", "meaning_component": "日 (sun eclipsed/dimmed)", "sound_component": "音 (yīn, sound/tone)", "stroke_count": "13", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character combining the sun (日) with sound (音); sunlight obscured leaving only unseen sound vibrations in the dark.", "visual_mnemonic_story_en": "When the sun (日) sets, only unseen voices and musical sounds (音) carry in the quiet darkness.", "visual_mnemonic_story_es": "Al ocultarse el sol (日), solo las voces y sonidos musicales (音) resuenan en la tranquila penumbra.", "tone_mnemonic_anchor": "51", "cangjie": "AYTA", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "站在喧嚣的人群中，少年看着橱窗里那把精致的吉他，心头暗暗涌起一阵莫名的冲动。生活的困顿从未磨灭心中的乐章，他在心底暗暗起誓，终有一日要用自己的琴弦，弹奏出属于黎明的滚烫旋律。", "pinyin": "Zhàn zài xuānxiāo de rénqún zhōng, shàonián kànzhe chúchuāng lǐ nà bǎ jīngzhì de jítā, xīntóu àn'àn yǒngqǐ yí zhèn mòmíng de chōngdòng. Shēnghuó de kùndùn cóngwèi mómiè xīnzhōng de yuèzhāng, tā zài xīndǐ àn'àn qǐshì, zhōng yǒu yí rì yào yòng zìjǐ de qínxián, tánzòu chū shǔyú límíng de gǔntàng xuánlǜ.", "en": "Standing among noisy crowds, the youth gazed at the exquisite guitar in the display window, feeling a surge of emotion. Hardship had never silenced his inner music; he vowed in secret to play dawn's fervent melody one day.", "es": "Entre la bulliciosa multitud, el joven contemplaba la guitarra del escaparate sintiendo un impulso íntimo. Las penurias jamás apagaron su música interior; se prometió en secreto que algún día tocaría la melodía del amanecer."}, {"id": "#2", "hanzi": "在激烈的国际半导体科技博弈中，各大科研机构都在暗暗积蓄原始创新力量。面对高精度光刻技术专利壁垒，研究团队在数年寂寞攻关中暗暗校准测量参数，终于突破了微纳制造核心装备的工艺瓶颈。", "pinyin": "Zài jīliè de guójì bàndǎotǐ kējì bóyì zhōng, gè dà kēyán jīgòu dōu zài àn'àn jīxù yuánshǐ chuàngxīn lìliàng. Miànduì gāojīngdù guāngkè jìshù zhuānlì bìlěi, yánjiū tuánduì zài shù nián jìmò gōngguān zhōng àn'àn jiàozhǔn cèliáng cānshù, zhōngyú tūpò le wēi-nà zhìzào héxīn zhuāngbèi de gōngyì píngjǐng.", "en": "In the intense rivalry over semiconductors, major institutes have been quietly building innovation strength. Confronting lithography patent walls, researchers spent years calibrating parameters in quiet diligence, breaking fabrication bottlenecks.", "es": "En la carrera de los semiconductores, los centros de investigación acumulan fuerzas en silencio. Ante las barreras de patentes en fotolitografía, el equipo calibró parámetros durante años de discreto empeño hasta superar el obstáculo tecnológico."}]}, {"meanings_summary": {"en": "to take turns; to rotate; round; wheel", "es": "turnar; tocarle el turno a; rueda; ronda"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Just as a cart wheel (轮) circles continuously, human turns and rounds rotate in orderly cycles.", "composite_memory_hook_es": "Igual que la rueda de un carro (轮) gira sin cesar, los turnos humanos rotan en ciclos ordenados.", "cultural_and_cognitive_roots": "The cart wheel ('lún') is an archetypal Chinese cognitive metaphor for cyclical movement, cosmic cycles (Samsara 轮回), and equitable rotation of responsibilities among individuals.", "tone_sandhi_and_pitch_modulation": "35 pitch contour. A single rising 2nd tone that starts mid-pitch and ascends clearly to high pitch without falling."}, "semantic_boundary_contrasts": {"core_nuance": "轮 focuses on cyclical succession, orderly rotation, or the arrival of a scheduled sequential turn.", "contrasts": [{"id": "1", "compared_word": "轮 vs. 替", "pinyin": "tì", "analysis": "替 means to substitute or stand in for someone else out of necessity, whereas 轮 indicates taking turns according to a planned sequential order."}, {"id": "2", "compared_word": "轮 vs. 换", "pinyin": "huàn", "analysis": "换 refers to exchanging or swapping items or positions, whereas 轮 denotes cyclical progression along a roster."}, {"id": "3", "compared_word": "轮 vs. 次", "pinyin": "cì", "analysis": "次 is a generic measure word for occurrences, whereas 轮 specifically marks rounds in a match, cycles of negotiations, or rotations."}]}, "traps_and_cognates": {"look_alikes": [{"character": "辆", "pinyin": "liàng", "meaning_en": "measure word for vehicles", "distinction_note": "Right side is 两 rather than 仑"}, {"character": "输", "pinyin": "shū", "meaning_en": "lose; transport", "distinction_note": "Right side is 俞 rather than 仑"}, {"character": "论", "pinyin": "lùn", "meaning_en": "discuss; theory", "distinction_note": "Has speech radical 讠 on the left instead of cart 车"}, {"character": "伦", "pinyin": "lún", "meaning_en": "ethics; logic", "distinction_note": "Has person radical 亻 on the left instead of cart 车"}], "etymological_cognates": [{"character": "仑", "pinyin": "lún", "gloss_en": "order; logic; phonetic matrix"}, {"character": "转", "pinyin": "zhuǎn", "gloss_en": "turn; rotate sharing the cart radical"}, {"character": "轨", "pinyin": "guǐ", "gloss_en": "track; orbital path of wheels"}, {"character": "轩", "pinyin": "xuān", "gloss_en": "carriage with high canopy"}]}, "id": "17", "hanzi": "轮", "pinyin": "lún", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to take turns; to rotate in sequence; to be one's turn to act", "definition_es": "tomar turnos; rotar sucesivamente; corresponderle el turno a alguien", "example_phrase": "轮到谁了 (whose turn is it?)"}, {"sense_number": "2", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "measure word for rounds of negotiations, rounds of matches, or big round celestial bodies", "definition_es": "clasificador para rondas de negociaciones, partidos o astros redondos", "example_phrase": "新一轮谈判 (a new round of talks)"}], "example_sentences": [{"id": "#1", "hanzi": "按照我们宿舍制定的值日生规则，今天放学后该轮到我和李明一起负责打扫教室走廊了。", "pinyin": "Ànzhào wǒmen sùshè zhìdìng de zhírìshēng guīzé, jīntiān fàngxué hòu gāi lún dào wǒ hé Lǐ Míng yìqǐ fùzé dǎsǎo jiàoshì zǒuláng le.", "en": "According to the duty roster formulated in our dormitory, after school today it is my and Li Ming's turn to clean the classroom corridor.", "es": "Según el turno de limpieza fijado en nuestro dormitorio, hoy al salir de clase nos toca a Li Ming y a mí limpiar el pasillo de las aulas."}, {"id": "#2", "hanzi": "多边贸易谈判代表团在日内瓦结束了第二轮密集磋商，就关税减免清单的阶段性执行达成了初步共识。", "pinyin": "Duōbiān màoyì tánpàn dàibiǎotuán zài Rìnèiwǎ jiéshù le dì-èr lún mìjí cuōshāng, jiù guānshuì jiǎnmiǎn qīngdān de jiēduànxìng zhíxíng dáchéng le chūbù gòngshí.", "en": "The multilateral trade negotiation delegation concluded its second round of intensive consultations in Geneva, reaching an initial consensus on phased tariff reduction lists.", "es": "La delegación de negociaciones comerciales multilaterales concluyó su segunda ronda de consultas en Ginebra, logrando un consenso preliminar sobre desgravaciones arancelarias."}], "collocations": [{"hanzi": "轮到我", "en": "my turn"}, {"hanzi": "轮流值班", "en": "take turns on duty"}, {"hanzi": "新一轮", "en": "a brand new round"}, {"hanzi": "轮流发言", "en": "take turns speaking"}, {"hanzi": "风水轮流转", "en": "fortune rotates round and round"}, {"hanzi": "一轮明月", "en": "a bright round moon"}], "idioms": [{"hanzi": "摩拳擦掌", "pinyin": "mó quán cā zhǎng", "meaning_en": "rub one's fists and palms; eager to take one's turn to fight"}, {"hanzi": "轮番上阵", "pinyin": "lún fān shàng zhèn", "meaning_en": "take the field in alternating shifts; attack in relays"}, {"hanzi": "风水轮流转", "pinyin": "fēng shuǐ lún liú zhuàn", "meaning_en": "the wheel of fortune keeps turning"}, {"hanzi": "珠圆玉润", "pinyin": "zhū yuán yù rùn", "meaning_en": "round as pearls and smooth as jade; elegant articulation"}], "character_decomposition": [{"character": "轮", "pinyin": "lún", "meaning_en": "wheel; turn; rotate; disk", "meaning_es": "rueda; turno; rotar; disco", "radical": "车", "radical_meaning_en": "cart / vehicle", "meaning_component": "车 (cart/chariot vehicle)", "sound_component": "仑 (lún, orderly sequence)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character combining cart (车) with ordered sequence (仑), denoting the cyclical revolution of vehicle wheels.", "visual_mnemonic_story_en": "A wooden cart (车) rolls forward on wheels turning in orderly rhythm (仑).", "visual_mnemonic_story_es": "Un carro (车) avanza sobre ruedas que giran en orden constante (仑).", "tone_mnemonic_anchor": "35", "cangjie": "KQOP", "traditional": "輪"}], "extended_reading_passages": [{"id": "#1", "hanzi": "岁月如车轮般滚滚向前，春去秋来，寒暑交替。生命的每个阶段都有它独特的景致，年少时的欢愉终会轮换为成年后的担当。懂得在人生的四季流转中顺应自然，便能在静观万物中收获内心的豁达。", "pinyin": "Suìyuè rú chēlún bān gǔngǔn qiánxiàng, chūn qù qiū lái, hánshǔ jiāotì. Shēngmìng de měi gè jiēduàn dōu yǒu tā dútè de jǐngzhì, niánshào shí de huányú zhōng huì lúnhuàn wéi chéngnián hòu de dāndāng. Dǒngdé zài rénshēng de sìjì liúzhuǎn zhōng shùnyìng zìrán, biàn néng zài jìngguān wànwù zhōng shōuhuò nèixīn de huòdá.", "en": "Time rolls forward like a wheel; spring departs and autumn arrives as seasons alternate. Each stage of life possesses distinct scenery, where youth's mirth yields in turn to adult duty. Yielding to nature's cycles grants profound inner peace.", "es": "El tiempo avanza como una rueda; la primavera cede su lugar al otoño en un ciclo constante. Cada etapa vital encierra su propia belleza, donde el júbilo juvenil se transforma en responsabilidad adulta, brindando serenidad a quien fluye con los cambios."}, {"id": "#2", "hanzi": "为防范金融系统周期性信贷风险，宏观调控部门启动了新一轮逆周期监管措施。各大商业银行轮流展开信贷资产质量压力测试，重点排查地方隐性债务与高杠杆行业风险，为实体经济平稳健康运行筑牢安全底线。", "pinyin": "Wèi fángfàn jīnróng xìtǒng zhōuqīxìng xìndài fēngxiǎn, hóngguān tiáokòng bùmén qǐdòng le xīn yì lún nìzhōuqī jiānguǎn cuòshī. Gè dà shāngyè yínháng lúnliú zhǎnkāi xìndài zīchǎn zhìliàng yālì cèshì, zhòngdiǎn páichá dìfāng yǐnxìng zhàiwù yǔ gāo gànggǎn hángyè fēngxiǎn, wèi shítǐ jīngjì píngwěn jiànkāng yùnxíng zhùláo ānquán dǐxiàn.", "en": "To guard against cyclical credit risks in finance, regulators launched a new round of countercyclical oversight measures. Commercial banks took turns conducting stress tests on asset quality, screening local debt and highly leveraged sectors to fortify economic stability.", "es": "Para prevenir riesgos crediticios cíclicos, los reguladores financieros iniciaron una nueva ronda de medidas contracíclicas. Los bancos comerciales realizaron pruebas de resistencia por turnos, evaluando deudas ocultas y sectores de alto apalancamiento para blindar la economía."}]}, {"meanings_summary": {"en": "impatient; irritated; restless", "es": "impaciente; fastidiado; mosqueado; sin paciencia"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Incapable of (不) enduring (耐) the burning mental heat of vexation (烦) produces blatant impatience.", "composite_memory_hook_es": "Ser incapaz de (不) aguantar (耐) el fuego molesto en la cabeza (烦) se traduce en impaciencia manifiesta.", "cultural_and_cognitive_roots": "Traditional Chinese medicine links 'fán' to internal heat in the heart and liver scorching the mind; 'bùnài' means inability to absorb this friction, leading to visible annoyance.", "tone_sandhi_and_pitch_modulation": "Tone sandhi applies to 不: preceding the 4th tone nài (51), 不 changes from 4th tone (51) to 2nd tone (35): pronounced bú nài fán (35-51-35)."}, "semantic_boundary_contrasts": {"core_nuance": "不耐烦 expresses visible irritation, restlessness, and annoyance caused by waiting or dealing with tedious matters.", "contrasts": [{"id": "1", "compared_word": "不耐烦 vs. 着急", "pinyin": "zháojí", "analysis": "着急 reflects intense worry or eagerness due to running out of time, whereas 不耐烦 expresses annoyance, grumpy irritation, or disgust with delay."}, {"id": "2", "compared_word": "不耐烦 vs. 讨厌", "pinyin": "tǎoyàn", "analysis": "讨厌 means to dislike, loathe, or find someone repulsive, whereas 不耐烦 is a temporary emotional state of exasperation and short temper."}, {"id": "3", "compared_word": "不耐烦 vs. 厌烦", "pinyin": "yànfán", "analysis": "厌烦 denotes being deeply sick and tired of long-term repetition or monotony, whereas 不耐烦 is an immediate behavioral reaction to frustration."}]}, "traps_and_cognates": {"look_alikes": [{"character": "项", "pinyin": "xiàng", "meaning_en": "item; neck", "distinction_note": "Features 工 on the left of 页 instead of 火"}, {"character": "顺", "pinyin": "shùn", "meaning_en": "smooth; along", "distinction_note": "Features 川 on the left of 页 instead of 火"}, {"character": "耍", "pinyin": "shuǎ", "meaning_en": "play; fool", "distinction_note": "Features 而 over 女 rather than beside 寸"}, {"character": "寸", "pinyin": "cùn", "meaning_en": "inch", "distinction_note": "Only the right component of 耐"}], "etymological_cognates": [{"character": "忍", "pinyin": "rěn", "gloss_en": "endure; blade over heart"}, {"character": "燥", "pinyin": "zào", "gloss_en": "restless; irritable fire radical"}, {"character": "恼", "pinyin": "nǎo", "gloss_en": "angry; annoyed heart radical"}, {"character": "急", "pinyin": "jí", "gloss_en": "urgent; anxious"}]}, "id": "18", "hanzi": "不耐烦", "pinyin": "bù nài fán", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "impatient, annoyed, or irritated by delay, monotony, or tediousness", "definition_es": "que muestra impaciencia, fastidio o molestia ante retrasos o repeticiones", "example_phrase": "脸上露出不耐烦的神情 (wear an impatient expression)"}], "example_sentences": [{"id": "#1", "hanzi": "在拥挤闷热的火车站候车大厅里等待了四个小时后，排队的乘客们逐渐变得焦躁不安且很不耐烦。", "pinyin": "Zài yōngjǐ mēnrè de huǒchēzhàn hòuchē dàtīng lǐ děngdài le sì gè xiǎoshí hòu, páiduì de chéngkè men zhújiàn biànde jiāozào bù'ān qiě hěn bùnàifán.", "en": "After waiting four hours in the crowded, sweltering railway station waiting hall, the queuing passengers gradually grew restless and very impatient.", "es": "Tras esperar cuatro horas en la abarrotada sala de la estación bajo un calor sofocante, los viajeros en fila empezaron a impacientarse y fastidiarse."}, {"id": "#2", "hanzi": "无论客户提出多么琐碎苛刻的要求，优秀的客服经理始终保持微笑与倾听，绝不在言语间流露出丝毫不耐烦。", "pinyin": "Wúlùn kèhù tíchū duōme suǒsuì kèkè de yāoqiú, yōuxiù de kèfú jīnglǐ shǐzhōng bǎochí wēixiào yǔ qīngtīng, jué bú zài yányǔ jiān liúlù chū sīháo bùnàifán.", "en": "No matter how trivial or demanding the client's requests were, the stellar customer service manager always maintained a smile and never betrayed the slightest impatience.", "es": "Sin importar cuán minuciosas fueran las exigencias del cliente, el gestor de atención conservó la sonrisa y la escucha sin mostrar el menor asomo de fastidio."}], "collocations": [{"hanzi": "显得不耐烦", "en": "appear impatient"}, {"hanzi": "不耐烦的神情", "en": "impatient expression"}, {"hanzi": "极为不耐烦", "en": "extremely impatient"}, {"hanzi": "开始不耐烦", "en": "start becoming impatient"}, {"hanzi": "挥手表示不耐烦", "en": "wave hands impatiently"}, {"hanzi": "不耐烦地打断", "en": "interrupt impatiently"}], "idioms": [{"hanzi": "心急如焚", "pinyin": "xīn jí rú fén", "meaning_en": "heart burning with anxiety; extremely anxious and impatient"}, {"hanzi": "急不可待", "pinyin": "jí bù kě dài", "meaning_en": "too impatient to wait; unable to hold back"}, {"hanzi": "焦躁不安", "pinyin": "jiāo zào bù'ān", "meaning_en": "fretful and fidgety; agitated with impatience"}, {"hanzi": "百折不挠", "pinyin": "bǎi zhé bù náo", "meaning_en": "indomitable; unyielding patience in face of hundreds of setbacks"}], "character_decomposition": [{"character": "不", "pinyin": "bù", "meaning_en": "not; no; negative prefix", "meaning_es": "no; prefijo negativo", "radical": "一", "radical_meaning_en": "one", "meaning_component": "一 (sky ceiling/barrier)", "sound_component": "不 (inherent negation sound)", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Anciently depicted a bird flying up to the heavens but unable to ascend further (negation).", "visual_mnemonic_story_en": "A bird attempts to fly upward but hits an immovable ceiling line (一), indicating 'not'.", "visual_mnemonic_story_es": "Un ave intenta volar alto pero topa contra una línea barrera (一), señalando la negación 'no'.", "tone_mnemonic_anchor": "51", "cangjie": "MF", "traditional": ""}, {"character": "耐", "pinyin": "nài", "meaning_en": "endure; bear; withstand; patient", "meaning_es": "soportar; aguantar; tolerar; resistir", "radical": "而", "radical_meaning_en": "and / facial whiskers", "meaning_component": "而 (whiskers/beard)", "sound_component": "寸 (inch/law penalty of shaving whiskers)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Originally an ancient judicial punishment (寸) of shaving facial whiskers (而); one who endured the disgrace displayed patience.", "visual_mnemonic_story_en": "Shaving whiskers (而) with an inch blade (寸) tests a man's endurance and patience.", "visual_mnemonic_story_es": "Afeitar la barba (而) con una pequeña cuchilla (寸) pone a prueba la paciencia y aguante del hombre.", "tone_mnemonic_anchor": "51", "cangjie": "MBDI", "traditional": ""}, {"character": "烦", "pinyin": "fán", "meaning_en": "troubled; vexed; irritated; bother", "meaning_es": "molesto; fastidiado; agobiado; preocupado", "radical": "火", "radical_meaning_en": "fire", "meaning_component": "火 (fire burning inside)", "sound_component": "页 (head/feverish temples)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character pairing fire (火) with head (页), denoting a feverish headache from agitation.", "visual_mnemonic_story_en": "Flames of fire (火) flare in the mind and head (页), causing intense vexation.", "visual_mnemonic_story_es": "Llamas de fuego (火) arden en la cabeza (页), provocando fastidio e irritación profunda.", "tone_mnemonic_anchor": "35", "cangjie": "FMBO", "traditional": "煩"}], "extended_reading_passages": [{"id": "#1", "hanzi": "快节奏的现代生活催生了太多的浮躁，人们在红灯前频繁按喇叭，在网页加载时露出不耐烦的神色。然而，生命中最珍贵的东西往往需要时间慢慢发酵。学会放下不耐烦，耐住性子等待，才能看清生命本来的从容美感。", "pinyin": "Kuài jièzòu de xiàndài shēnghuó cuīshēng le tài duō de fúzào, rénmen zài hóngdēng qián pínfán àn lǎba, zài wǎngyè jiāzài shí lùchū bùnàifán de shénsè. Rán'ér, shēngmìng zhōng zuì zhēnguì de dōngxi wǎngwǎng xūyào shíjiān mànman fājiào. Xuéhuì fàngxià bùnàifán, nàizhù xìngzi děngdài, cáinǐng kànqīng shēngmìng běnlái de cóngróng měigǎn.", "en": "Fast-paced living breeds impetuousness: people honk at red lights and wear impatient looks when webpages load. Yet life's treasures require patient fermentation. Releasing impatience and waiting steadily reveals life's tranquil beauty.", "es": "El ritmo frenético engendra impaciencia: la gente toca el claxon en los semáforos y muestra fastidio si una página tarda en cargar. Sin embargo, lo más valioso requiere madurar con calma. Desprenderse de la impaciencia rescata la serenidad de la vida."}, {"id": "#2", "hanzi": "在复杂精密的科研实验与工程调试过程中，任何急躁与不耐烦都可能导致前功尽弃。面对海量数据的异常波动与反复失败，顶尖科学家之所以能取得突破，往往正是凭借着把枯燥实验重复千百次而不显丝毫浮躁的超常耐心。", "pinyin": "Zài fùzá jīngmì de kēyán shíyàn yǔ gōngchéng tiáoshì guòchéng zhōng, rènhé jízào yǔ bùnàifán dōu kěnéng dǎozhì qiángōngjìnqì. Miànduì hǎiliàng shùjù de yìcháng bōdòng yǔ fǎnfù shībài, dǐngjiān kēxuéjiā zhī suǒyǐ néng qǔdé tūpò, wǎngwǎng zhèng shì píngjiè zhe bǎ kūzào shíyàn chóngfù qiānbǎi cì ér bù xiǎn sīháo fúzào de chāocháng nàixīn.", "en": "In precision scientific experiments and engineering debugging, any haste and impatience can ruin all prior gains. Facing anomalous data and repeated setbacks, top scientists achieve breakthroughs through extraordinary patience, repeating tests thousands of times without haste.", "es": "En la investigación científica y calibración técnica, cualquier impaciencia arruina el trabajo previo. Ante fallos y fluctuaciones de datos, los grandes científicos logran descubrimientos gracias a una paciencia tenaz que repite experimentos mil veces sin decaer."}]}, {"meanings_summary": {"en": "to lean on; to rely on; to depend on; near; by", "es": "apoyarse en; depender de; fiarse de; arrimarse a; cerca de"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Leaning your body firmly against a steadfast pillar (靠) gives you the reliable support needed to face hardship.", "composite_memory_hook_es": "Apoyar la espalda contra un pilar sólido (靠) brinda el respaldo necesario para resistir la dificultad.", "cultural_and_cognitive_roots": "The proverb '在家靠父母，出门靠朋友' (at home rely on parents, abroad rely on friends) reflects traditional Chinese relational networking (关系). True maturity balances communal reliance with self-reliance ('靠人不如靠己').", "tone_sandhi_and_pitch_modulation": "51 pitch contour. A crisp, resolute falling 4th tone (51) that emphasizes firm physical or psychological grounding."}, "semantic_boundary_contrasts": {"core_nuance": "靠 denotes physically leaning against a supportive structure, or depending on individuals, skills, or resources for survival.", "contrasts": [{"id": "1", "compared_word": "靠 vs. 依", "pinyin": "yī", "analysis": "依 is formal/literary meaning to depend or comply, whereas 靠 is universal in both physical actions ('leaning on a wall') and colloquial reliance ('靠自己')."}, {"id": "2", "compared_word": "靠 vs. 赖", "pinyin": "lài", "analysis": "赖 often carries pejorative connotations of clingy dependency or shirking accountability (如‘耍赖’), while 靠 denotes legitimate, earnest reliance or self-sustenance."}, {"id": "3", "compared_word": "靠 vs. 挨", "pinyin": "āi", "analysis": "挨 emphasizes close proximity or physical touching side-by-side, while 靠 implies applying weight or leaning for support."}]}, "traps_and_cognates": {"look_alikes": [{"character": "告", "pinyin": "gào", "meaning_en": "tell; report", "distinction_note": "Lacks the bottom 非 component of 靠"}, {"character": "非", "pinyin": "fēi", "meaning_en": "wrong; not", "distinction_note": "Lacks the top 告 component of 靠"}, {"character": "排", "pinyin": "pái", "meaning_en": "line up; row", "distinction_note": "Features hand radical 扌 on the left with 非"}, {"character": "悲", "pinyin": "bēi", "meaning_en": "sad; sorrow", "distinction_note": "Features 心 (heart) at the bottom instead of 告 on top"}], "etymological_cognates": [{"character": "依", "pinyin": "yī", "gloss_en": "rely on; comply with"}, {"character": "附", "pinyin": "fù", "gloss_en": "attach; adhere to"}, {"character": "赖", "pinyin": "lài", "gloss_en": "depend; lean on"}, {"character": "倚", "pinyin": "yǐ", "gloss_en": "lean against; rely"}]}, "id": "19", "hanzi": "靠", "pinyin": "kào", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to rest against; to physically lean against something for support", "definition_es": "recostarse o apoyarse físicamente contra algo", "example_phrase": "背靠墙壁 (lean with back against the wall)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to depend on; to rely upon for support or sustenance", "definition_es": "depender de; confiar o apoyarse moral o materialmente en alguien", "example_phrase": "靠双手生活 (depend on one's own hands to live)"}], "example_sentences": [{"id": "#1", "hanzi": "在连续加班十二个小时后，疲惫不堪的他一坐在地铁座位上，就忍不住把头靠在身后的车窗上睡着了。", "pinyin": "Zài liánxù jiābān shí'èr gè xiǎoshí hòu, píbèibùkān de tā yí zuò zài dìtiě zuòwèi shàng, jiù rěnbuzhù bǎ tóu kào zài shēnhòu de chēchuāng shàng shuìzháo le.", "en": "After working overtime for twelve consecutive hours, exhausted, as soon as he sat on the subway he leaned his head against the window and fell asleep.", "es": "Tras trabajar doce horas seguidas, agotado, en cuanto se sentó en el metro recostó la cabeza en la ventanilla y se quedó profundamente dormido."}, {"id": "#2", "hanzi": "初创科技企业要想在激烈的市场竞争中生存壮大，归根结底必须靠自主核心技术的突破，而非单纯依赖资本输血。", "pinyin": "Chūchuàng kējì qǐyè yào xiǎng zài jīliè de shìchǎng jìngzhēng zhōng shēngcún zhuàngdà, guīgēnjiédǐ bìxū kào zìzhǔ héxīn jìshù de tūpò, ér fēi dānchún yīlài zīběn shūxiè.", "en": "For startup tech firms to survive and thrive amidst fierce competition, in the final analysis they must rely on breakthroughs in autonomous proprietary technology rather than capital subsidies.", "es": "Para que una empresa emergente prospere en un mercado competitivo, debe apoyarse ante todo en la innovación tecnológica propia y no solo en inyecciones de capital."}], "collocations": [{"hanzi": "依靠自己", "en": "rely on oneself"}, {"hanzi": "靠窗座位", "en": "window seat"}, {"hanzi": "靠山", "en": "backing; patron; sponsor"}, {"hanzi": "值得信赖依靠", "en": "worthy of trust and reliance"}, {"hanzi": "靠谱", "en": "reliable; trustworthy"}, {"hanzi": "靠近边缘", "en": "approach near the edge"}], "idioms": [{"hanzi": "无依无靠", "pinyin": "wú yī wú kào", "meaning_en": "helpless and destitute; have no one to rely upon"}, {"hanzi": "牢不可破", "pinyin": "láo bù kě pò", "meaning_en": "unbreakable; completely solid foundation to lean on"}, {"hanzi": "坐吃山空", "pinyin": "zuò chī shān kōng", "meaning_en": "sit idle and eat till mountains are empty without relying on work"}, {"hanzi": "自力更生", "pinyin": "zì lì gēng shēng", "meaning_en": "rely on one's own efforts; regeneration through self-reliance"}], "character_decomposition": [{"character": "靠", "pinyin": "kào", "meaning_en": "lean on; rely; near; depend", "meaning_es": "apoyarse; depender; cerca; arrimar", "radical": "非", "radical_meaning_en": "oppose / not", "meaning_component": "告 (tell/declare) + 非 (opposing wings/buttress)", "sound_component": "告 (gào, phonetic association)", "stroke_count": "15", "composition_type": "上下结构", "etymology_and_mnemonic": "Anciently depicted back-to-back bird wings opposing and leaning against each other (非) to provide physical stability.", "visual_mnemonic_story_en": "Opposing wings (非) lean firmly against the post (告), supporting each other upright.", "visual_mnemonic_story_es": "Alas opuestas (非) se apoyan con firmeza contra un soporte (告) sosteniéndose en pie.", "tone_mnemonic_anchor": "51", "cangjie": "HRMYY", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "成长是一场逐渐学会依靠自己的跋涉。少年时，我们习惯靠在父母宽厚的臂弯里避风；成年后，我们终于明白，世间最坚固的靠山不是他人的馈赠，而是自己脚踏实地踩出的每一步脚印。", "pinyin": "Chéngzhǎng shì yì chǎng zhújiàn xuéhuì yīkào zìjǐ de báshè. Shàonián shí, wǒmen xíguàn kào zài fùmǔ kuānhòu de bìwān lǐ bìfēng; chéngnián hòu, wǒmen zhōngyú míngbai, shìjiān zuì jiāngù de kàoshān bú shì tārén de kuìzèng, érshì zìjǐ jiǎotàshídì cǎi chū de měi yí bù jiǎoyìn.", "en": "Growing up is a journey of gradually learning to rely on oneself. In youth, we lean in parents' warm embrace; in adulthood, we realize the sturdiest refuge is not others' gifts, but our own steady footprints on the ground.", "es": "Crecer es aprender a apoyarse en uno mismo. De niños nos cobijamos en el abrazo protector de los padres; de adultos comprendemos que el mayor respaldo no procede de regalos ajenos, sino de nuestras propias pisadas firmes."}, {"id": "#2", "hanzi": "在现代产业经济转型升级的浪潮中，资源型城市必须打破过度靠山吃山的路径依赖。通过培育高新技术产业与数字创意经济，变资源红利为创新红利，才能真正实现高质量与可持续发展。", "pinyin": "Zài xiàndài chǎnyè jīngjì zhuǎnxíng shēngjí de làngcháo zhōng, zīyuán xíng chéngshì bìxū dǎpò guòdù kàoshānchīshān de lùjìng yīlài. Tōngguò péiyù gāoxīnjìshù chǎnyè yǔ shùzì chuàngyì jīngjì, biàn zīyuán hónglì wéi chuàngxīn hónglì, cáinǐng zhēnzhèng shíxiàn gāozhìliàng yǔ kěchíxù fāzhǎn.", "en": "Amid industrial restructuring, resource-based cities must break their path dependency on mineral extraction. By fostering high-tech sectors and digital creativity, shifting resource windfalls to innovation dividends, they achieve sustainable growth.", "es": "En la reconversión industrial, las ciudades mineras deben romper la dependencia pasiva de los recursos naturales. Al cultivar sectores tecnológicos y creativos, transforman la riqueza extractiva en innovación sostenible de alta calidad."}]}, {"meanings_summary": {"en": "shoulder; shoulders; ability to bear responsibility", "es": "hombro; hombros; capacidad de asumir responsabilidades"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Both characters share the body flesh radical (月): the upper load-bearing bone (肩) and lateral torso muscle (膀) form our sturdy shoulders.", "composite_memory_hook_es": "Ambos caracteres llevan el radical de carne corporal (月): la estructura de carga (肩) y el músculo lateral (膀) componen los hombros.", "cultural_and_cognitive_roots": "Across Chinese literary and sociological idioms, the shoulder ('jiān') represents moral capacity for filial duty, civic duty, and protection ('挑起重担'). To have shoulders ('有肩膀') means to be dependable.", "tone_sandhi_and_pitch_modulation": "55-214 pitch contour. In colloquial spoken Mandarin, 膀 is frequently reduced to a light neutral tone (jiānbang), whereas formal reading preserves the dipping 3rd tone (214)."}, "semantic_boundary_contrasts": {"core_nuance": "肩膀 refers to the physical shoulder anatomy, and figuratively to the locus of moral burden and duty.", "contrasts": [{"id": "1", "compared_word": "肩膀 vs. 臂膀", "pinyin": "bìbǎng", "analysis": "臂膀 combines arm and shoulder highlighting protective wing-like embrace or capable assisting hands, whereas 肩膀 stresses bearing upward weight and duty."}, {"id": "2", "compared_word": "肩膀 vs. 挑子", "pinyin": "tiāozi", "analysis": "挑子 is the physical carrying pole or metaphorical load itself (如‘撂挑子’), while 肩膀 is the bodily or psychological capacity carrying that load."}, {"id": "3", "compared_word": "肩膀 vs. 脊梁", "pinyin": "jǐliáng", "analysis": "脊梁 represents the central spine or moral backbone of courage, whereas 肩膀 focuses on willingness to shoulder burdens."}]}, "traps_and_cognates": {"look_alikes": [{"character": "房", "pinyin": "fáng", "meaning_en": "room; house", "distinction_note": "Features 方 at the bottom instead of 肉/月"}, {"character": "扇", "pinyin": "shān / shàn", "meaning_en": "fan", "distinction_note": "Features 羽 (feathers) inside 户 instead of 肉/月"}, {"character": "榜", "pinyin": "bǎng", "meaning_en": "roster; placard", "distinction_note": "Has wood radical 木 on the left instead of 月"}, {"character": "膀", "pinyin": "bǎng", "meaning_en": "shoulder; wing", "distinction_note": "Headword character itself"}], "etymological_cognates": [{"character": "臂", "pinyin": "bì", "gloss_en": "arm sharing flesh radical"}, {"character": "胸", "pinyin": "xiōng", "gloss_en": "chest; thorax"}, {"character": "背", "pinyin": "bèi", "gloss_en": "back"}, {"character": "胛", "pinyin": "jiǎ", "gloss_en": "shoulder blade"}]}, "id": "20", "hanzi": "肩膀", "pinyin": "jiān bǎng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the anatomical upper joint connecting the human arm with the torso", "definition_es": "articulación superior que une el brazo con el tronco del cuerpo humano", "example_phrase": "宽阔的肩膀 (broad shoulders)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Metaphorical", "definition_en": "capacity to shoulder burdens, responsibilities, or familial duties", "definition_es": "capacidad moral para soportar cargas o asumir responsabilidades", "example_phrase": "有肩膀的男人 (a man who takes responsibility)"}], "example_sentences": [{"id": "#1", "hanzi": "小时候每次去游乐园看花车巡游，父亲总会把我高高抱起，让我坐在他宽厚结实的肩膀上纵情欢呼。", "pinyin": "Xiǎoshíhou měi cì qù yóulèyuán kàn huāchē xúnyóu, fùqīn zǒng huì bǎ wǒ gāogāo bàoqǐ, ràng wǒ zuò zài tā kuānhòu jiēshi de jiānbǎng shàng zòngqíng huānhū.", "en": "Whenever we went to the amusement park for parades in my childhood, father would lift me high onto his broad shoulders to cheer with delight.", "es": "De niño, en las cabalgatas del parque de atracciones, mi padre me subía en alto para que me sentara en sus hombros anchos y aclamara feliz."}, {"id": "#2", "hanzi": "新时代青年应当勇于将时代的重任扛在自己的肩膀上，在科技攻关与基层治理一线展现担当与作为。", "pinyin": "Xīn shídài qīngnián yīngdāng yǒngyú jiāng shídài de zhòngrèn káng zài zìjǐ de jiānbǎng shàng, zài kējì gōngguān yǔ jīcéng zhìlǐ yīxiàn zhǎnxiàn dāndāng yǔ zuòwéi.", "en": "Youth of the new era should courageously carry the era's heavy responsibilities on their shoulders, demonstrating accountability on scientific and community frontlines.", "es": "La juventud contemporánea debe asumir con valentía las responsabilidades históricas sobre sus hombros, demostrando compromiso en la ciencia y la sociedad."}], "collocations": [{"hanzi": "宽厚的肩膀", "en": "broad and solid shoulders"}, {"hanzi": "拍拍肩膀", "en": "pat on the shoulder"}, {"hanzi": "肩膀酸痛", "en": "sore / aching shoulders"}, {"hanzi": "扛在肩膀上", "en": "carry on one's shoulders"}, {"hanzi": "并起肩膀", "en": "stand shoulder to shoulder"}, {"hanzi": "结实的肩膀", "en": "sturdy shoulders"}], "idioms": [{"hanzi": "并肩作战", "pinyin": "bìng jiān zuò zhàn", "meaning_en": "fight shoulder to shoulder in combat"}, {"hanzi": "摩肩接踵", "pinyin": "mó jiān jiē zhǒng", "meaning_en": "shoulders rubbing and heels touching; crowded densely"}, {"hanzi": "比肩同行", "pinyin": "bǐ jiān tóng xíng", "meaning_en": "walk side by side as peers"}, {"hanzi": "息肩之所", "pinyin": "xī jiān zhī suǒ", "meaning_en": "a place to put down one's burdens and rest"}], "character_decomposition": [{"character": "肩", "pinyin": "jiān", "meaning_en": "shoulder; bear burdens", "meaning_es": "hombro; sobrellevar cargas", "radical": "肉", "radical_meaning_en": "meat / flesh", "meaning_component": "月/肉 (flesh of the body)", "sound_component": "户 (hù, door frame/collarbone)", "stroke_count": "8", "composition_type": "半包围结构", "etymology_and_mnemonic": "Depicts torso flesh (月) beneath the collarbone doorway (户), forming the shoulder joint supporting loads.", "visual_mnemonic_story_en": "Flesh (月) supporting the collarbone arch (户) forms a muscular shoulder to bear weights.", "visual_mnemonic_story_es": "La carne (月) bajo el arco clavicular (户) forma un hombro fuerte para cargar pesos.", "tone_mnemonic_anchor": "55", "cangjie": "HSB", "traditional": ""}, {"character": "膀", "pinyin": "bǎng", "meaning_en": "upper arm; shoulder wing; bladder", "meaning_es": "brazo superior; hombro; ala", "radical": "肉", "radical_meaning_en": "meat / flesh", "meaning_component": "月/肉 (flesh/body muscle)", "sound_component": "旁 (páng, side)", "stroke_count": "14", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character combining flesh (月) with side (旁), describing the lateral muscle wings of the torso.", "visual_mnemonic_story_en": "The flesh (月) expanding on both sides (旁) of the torso forms the broad shoulder flank.", "visual_mnemonic_story_es": "La masa muscular (月) a ambos lados (旁) del torso forma el hombro y costado.", "tone_mnemonic_anchor": "214", "cangjie": "BYBS", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "父亲的肩膀曾是我童年仰望天空的起点。那宽厚的双肩不仅扛起过沉重的农具，更替全家人挡住了漫天风雪。当岁月的重担悄然压弯他的脊背，我才读懂那双肩膀上沉淀的无声深情。", "pinyin": "Fùqīn de jiānbǎng céng shì wǒ tóngnián yǎngwàng tiānkōng de qǐdiǎn. Nà kuānhòu de shuāngjiān bùjǐn kángqǐ guò chénzhòng de nóngjù, gèng tì quánjiā rén dǎngzhù le màntiān fēngxuě. Dāng suìyuè de zhòngdàn qiǎorán yāwān tā de jǐbèi, wǒ cái dúdǒng nà shuāng jiānbǎng shàng chéndiàn de wúshēng shēnqíng.", "en": "Father's shoulders were the vantage point from which my childhood gazed at the sky. Those broad shoulders bore heavy farm tools and sheltered the family from storms. As years bent his back, I understood the deep love in those shoulders.", "es": "Los hombros de mi padre fueron el mirador desde el cual contemplé el cielo en mi niñez. Aquellos hombros cargaron aperos pesados y resguardaron al hogar de las tormentas. Al verlos encorvados por los años, comprendí la honda devoción que sostenían."}, {"id": "#2", "hanzi": "站在科技变革的风口浪尖，青年科研工作者的肩膀承载着国家战略科技自立自强的历史重托。唯有耐得住寂寞、勇于啃硬骨头，把个人学术追求融入现代化建设洪流，才能在科技前沿展现坚实的青年担当。", "pinyin": "Zhàn zài kējì biàngé de fēngkǒulàngjiān, qīngnián kēyán gōngzuòzhě de jiānbǎng chéngzài zhe guójiā zhànlüè kējì zìlìzìqiáng de lìshǐ zhòngtuō. Wéiyǒu nàidēzhù jìmò, yǒngyú kěn yìnggǔtou, bǎ gèrén xuéshù zhuīqiú róngrù xiàndàihuà jiànshè hóngliú, cáinǐng zài kējì qiányán zhǎnxiàn jiānshí de qīngnián dāndāng.", "en": "At the forefront of technological transformation, the shoulders of young scientists bear the historic mandate of technological self-reliance. Overcoming solitude and tackling hard problems on the frontier showcase youth's firm commitment.", "es": "En la vanguardia de la transformación científica, los hombros de los jóvenes investigadores soportan el reto histórico de la soberanía tecnológica. Afrontar los problemas difíciles en la frontera del saber demuestra su madura responsabilidad."}]}, {"meanings_summary": {"en": "to shout; to yell; to cry out; to call someone", "es": "gritar; vocear; llamar a alguien; clamar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A wide-open mouth (口) bellows a commanding cry (咸) that carries across the hills: that is shouting (喊).", "composite_memory_hook_es": "Una boca abierta (口) proyecta una orden sonora (咸) que retumba en el valle: eso es gritar (喊).", "cultural_and_cognitive_roots": "Derived from military calls and village collective alerts ('呐喊'); raising the voice carries primal social functions: warning of imminent peril or uniting collective morale.", "tone_sandhi_and_pitch_modulation": "214 pitch contour. A deep dipping 3rd tone; when placed before other 3rd tones, it changes to 2nd tone (35); in isolation, it drops low and rises distinctly."}, "semantic_boundary_contrasts": {"core_nuance": "喊 denotes forcefully raising the acoustic volume of the voice to project distance cries, alerts, or emotional shouts.", "contrasts": [{"id": "1", "compared_word": "喊 vs. 叫", "pinyin": "jiào", "analysis": "叫 can mean calling someone's name, being named, animal sounds, or ordering, whereas 喊 focuses specifically on projecting loud vocal volume into the air."}, {"id": "2", "compared_word": "喊 vs. 呼", "pinyin": "hū", "analysis": "呼 is more formal/literary (e.g., 呼唤, 欢呼), while 喊 is colloquial and physically direct (e.g., 大喊大叫)."}, {"id": "3", "compared_word": "喊 vs. 嚷", "pinyin": "rǎng", "analysis": "嚷 carries the negative nuance of noisy, disorderly blustering or making an irritating fuss, while 喊 is a neutral acoustic description."}]}, "traps_and_cognates": {"look_alikes": [{"character": "减", "pinyin": "jiǎn", "meaning_en": "reduce; subtract", "distinction_note": "Has water radical 冫/氵 on the left instead of mouth 口"}, {"character": "缄", "pinyin": "jiān", "meaning_en": "seal; close", "distinction_note": "Has silk radical 纟 on the left instead of mouth 口"}, {"character": "感", "pinyin": "gǎn", "meaning_en": "feel; sense", "distinction_note": "Features 心 (heart) at the bottom beneath 咸"}, {"character": "咸", "pinyin": "xián", "meaning_en": "salty; all", "distinction_note": "The phonetic stem itself lacking mouth radical 口"}], "etymological_cognates": [{"character": "叫", "pinyin": "jiào", "gloss_en": "call; shout; yell"}, {"character": "唤", "pinyin": "huàn", "gloss_en": "summon; call out"}, {"character": "呼", "pinyin": "hū", "gloss_en": "exhale; cry aloud"}, {"character": "咆", "pinyin": "páo", "gloss_en": "roar; bluster"}]}, "id": "21", "hanzi": "喊", "pinyin": "hǎn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to utter a loud vocal cry, shout, or call out someone's name", "definition_es": "emitir gritos o alzar la voz con fuerza para llamar o alertar", "example_phrase": "大声呼喊 (shout loudly)"}], "example_sentences": [{"id": "#1", "hanzi": "在人声鼎沸的火车站广场上，母亲远远看到刚下火车的儿子，激动地挥着手大声喊着他的名字。", "pinyin": "Zài rénshēngdǐngfèi de huǒchēzhàn guǎngchǎng shàng, mǔqīn yuǎnyuǎn kàndào gāng xià huǒchē de érzi, jīdòng de huī zhe shǒu dàshēng hǎn zhe tā de míngzi.", "en": "In the bustling railway station square, spotting her son who had just stepped off the train from afar, the mother excitedly waved and shouted his name.", "es": "En la concurrida plaza de la estación, al divisar de lejos a su hijo que bajaba del tren, la madre agitó el brazo emocionada llamándolo a gritos por su nombre."}, {"id": "#2", "hanzi": "在发生山体滑坡地质险情时，巡防网格员第一时间敲响铜锣并沿街高喊预警口号，迅速疏散群众。", "pinyin": "Zài fāshēng shāntǐ huápō dìzhì xiǎnqíng shí, xúnfáng wǎnggéyuán dì-yī shíjiān qiāoxiǎng tóngluó bìng yánjiē gāohǎn yùjǐng kǒuhào, xùnsù shūsàn qúnzhòng.", "en": "When a dangerous landslide occurred, the patrol officer immediately sounded the brass gong and shouted warning alerts along the street, rapidly evacuating residents.", "es": "Ante la amenaza de un deslizamiento de tierra, el vigilante hizo sonar el gong y recorrió las calles gritando alertas para evacuar rápidamente a los vecinos."}], "collocations": [{"hanzi": "大声喊", "en": "shout at the top of one's voice"}, {"hanzi": "高喊口号", "en": "shout slogans aloud"}, {"hanzi": "喊救命", "en": "shout for help"}, {"hanzi": "大喊大叫", "en": "shout and scream rowdily"}, {"hanzi": "喊停", "en": "call a halt / yell stop"}, {"hanzi": "喊他一声", "en": "call him over"}], "idioms": [{"hanzi": "大喊大叫", "pinyin": "dà hǎn dà jiào", "meaning_en": "shout and scream loudly; kick up a row"}, {"hanzi": "摇旗呐喊", "pinyin": "yáo qí nà hǎn", "meaning_en": "wave flags and shout battle cries; cheer on and support"}, {"hanzi": "贼喊捉贼", "pinyin": "zéi hǎn zhuō zéi", "meaning_en": "a thief crying 'catch thief'; divert attention by blaming others"}, {"hanzi": "人喊马叫", "pinyin": "rén hǎn mǎ jiào", "meaning_en": "men shouting and horses neighing; hustle and din of motion"}], "character_decomposition": [{"character": "喊", "pinyin": "hǎn", "meaning_en": "shout; yell; call; cry out", "meaning_es": "gritar; vocear; llamar", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (mouth, projecting vocal cries)", "sound_component": "咸 (xián, collective/all phonetics)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character pairing mouth (口) with 咸 (xián), meaning to raise a loud unified call heard by all.", "visual_mnemonic_story_en": "Opening the mouth (口) wide with weapons raised (咸) to bellow a battle cry across the fields.", "visual_mnemonic_story_es": "Abrir la boca (口) de par en par alzando lanzas (咸) para lanzar un potente grito al viento.", "tone_mnemonic_anchor": "214", "cangjie": "RIHR", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "站在青翠巍峨的苍山之巅，面对无边无际的云海翻涌，胸中所有的郁结都在那一刻化作了一声悠长的大喊。山风穿透胸膛，回声在幽谷间荡气回肠，将少年的热血与梦想送向了天际。", "pinyin": "Zhàn zài qīngcuì wēi'é de cāngshān zhī diān, miànduì wúbiānwújì de yúnhǎi fānyǒng, xiōng zhōng suǒyǒu de yùjié dōu zài nà yí kè huàzuò le yì shēng yōucháng de dàhǎn. Shānfēng chuāntòu xiōngtáng, huíshēng zài yōugǔ jiān dàngqìhuícháng, jiāng shàonián de rèxuè yǔ mèngxiǎng sòngxiàng le tiānjì.", "en": "Standing atop the verdant peaks facing boundless seas of surging clouds, all gloom within the chest dissolved into a resounding shout. Mountain breezes pierced through as echoes lingered, carrying dreams toward the sky.", "es": "En la cima de las montañas frente a un mar de nubes ondulantes, el desasosiego del pecho se disolvió en un grito prolongado. La brisa serrana y el eco en el valle elevaron los sueños juveniles hacia el firmamento."}, {"id": "#2", "hanzi": "在现代海上应急搜救体系中，声光双重遇险求救信号能够大幅提升搜寻效率。即便在卫星通信失效的极端海况下，水上扩音喊话设备依然是搜救船只在浓雾视距内实施喊话联络与生命指引的可靠手段。", "pinyin": "Zài xiàndài hǎishàng yìngjí sōujiù tǐxì zhōng, shēng guāng shuāngzhòng yùxiǎn qiújiù xìnhào nénggòu dàfú tíshēng sōuxún xiàolǜ. Jíbīan zài wèixīng tōngxìn shīxiào de jíduān hǎikuàng xià, shuǐshàng kuòyīn hǎnhuà shèbèi yīrán shì sōujiù chuánzhī zài nóngwù shìjù nèi shíshī hǎnhuà liánluò yǔ shēngmìng zhǐyǐn de kěkào shǒuduàn.", "en": "In maritime emergency search and rescue systems, dual acoustic-optical distress signals elevate search efficiency. When satellite communication fails in extreme seas, amplification hailing gear remains a dependable method for guiding survivors in dense fog.", "es": "En el salvamento marítimo, las señales acústicas y ópticas multiplican la eficacia del rescate. Ante el fallo de satélites en tormentas, los megáfonos de largo alcance siguen siendo un medio seguro para guiar vidas entre la niebla."}]}, {"meanings_summary": {"en": "to stretch; to extend; to reach out; to unfold", "es": "estirar; extender; alargar; tender"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A person (亻) standing upright straightens and extends outward (申) like a stretching gymnast.", "composite_memory_hook_es": "Una persona (亻) de pie se estira y alarga en línea recta (申) desplegando sus brazos.", "cultural_and_cognitive_roots": "Philosophically linked to the ancient concept of 'qū shēn' (bending and extending, 屈伸) in the Book of Changes (易经): life alternates between contracting for defense and extending for progress.", "tone_sandhi_and_pitch_modulation": "55 pitch contour. A steady, clean high level 1st tone (55) that conveys open elongation."}, "semantic_boundary_contrasts": {"core_nuance": "伸 emphasizes extending bodily limbs or physical flexible objects outward from a folded or curled posture.", "contrasts": [{"id": "1", "compared_word": "伸 vs. 展", "pinyin": "zhǎn", "analysis": "展 focuses on unfolding flat surfaces (e.g., flags, wings, drawings), whereas 伸 focuses on reaching or stretching out linear limbs (e.g., 手, 腿)."}, {"id": "2", "compared_word": "伸 vs. 延", "pinyin": "yán", "analysis": "延 refers to temporal extensions of deadlines or abstract spatial routes (e.g., 延长, 延伸), while 伸 denotes physical bodily movements."}, {"id": "3", "compared_word": "伸 vs. 缩", "pinyin": "suō", "analysis": "缩 is the exact antonym of 伸, meaning to contract, shrink, or recoil inward."}]}, "traps_and_cognates": {"look_alikes": [{"character": "神", "pinyin": "shén", "meaning_en": "spirit; god", "distinction_note": "Features altar radical 礻 on the left instead of person 亻"}, {"character": "审", "pinyin": "shěn", "meaning_en": "judge; examine", "distinction_note": "Features roof radical 宀 on top of 申"}, {"character": "坤", "pinyin": "kūn", "meaning_en": "earth; female principle", "distinction_note": "Has earth radical 土 on the left with 申"}, {"character": "绅", "pinyin": "shēn", "meaning_en": "gentry", "distinction_note": "Has silk radical 纟 on the left with 申"}], "etymological_cognates": [{"character": "申", "pinyin": "shēn", "gloss_en": "extend; express; root morpheme"}, {"character": "展", "pinyin": "zhǎn", "gloss_en": "unfold; spread open"}, {"character": "延", "pinyin": "yán", "gloss_en": "extend; prolong"}, {"character": "长", "pinyin": "cháng", "gloss_en": "long; length"}]}, "id": "22", "hanzi": "伸", "pinyin": "shēn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to stretch or extend limbs, body parts, or objects outward from a bent state", "definition_es": "extender o alargar extremidades o partes del cuerpo desplegándolas", "example_phrase": "伸手求助 (reach out a hand for help)"}], "example_sentences": [{"id": "#1", "hanzi": "清晨推开阳台的落地窗，迎着初升的朝阳，他惬意地伸了一个大大的懒腰，顿觉浑身精力充沛。", "pinyin": "Qīngchén tuīkāi yángtái de luòdìchuāng, yíng zhe chūshēng de zhāoyáng, tā qièyì de shēn le yí gè dàdà de lǎnyāo, dùnjué húnshēn jīnglì chōngpèi.", "en": "Pushing open the French windows in the early morning toward the rising sun, he pleasantly stretched his body, feeling fully invigorated.", "es": "Al abrir las ventanas del balcón al alba hacia el sol naciente, se estiró perezosamente con deleite, sintiéndose lleno de renovada energía."}, {"id": "#2", "hanzi": "在发生重大地震灾害的第一时间，邻近省份的应急救援力量迅速向灾区伸出援手，紧急调拨大型搜救装备。", "pinyin": "Zài fāshēng zhòngdà dìzhèn zāihài de dì-yī shíjiān, línjìn shěngfèn de yìngjí jiùyuán lìliàng xùnsù xiàng zāiqū shēnchū yuánshǒu, jǐnjí diàobō dàxíng sōujiù zhuāngbèi.", "en": "Immediately after the major earthquake struck, emergency rescue forces from neighboring provinces swiftly extended a helping hand to the disaster area, mobilizing heavy equipment.", "es": "Tras el fuerte terremoto, las brigadas de auxilio de las provincias vecinas extendieron una mano solidaria a la zona afectada, enviando equipos de rescate pesado."}], "collocations": [{"hanzi": "伸手", "en": "reach out a hand"}, {"hanzi": "伸懒腰", "en": "stretch oneself lazily"}, {"hanzi": "伸出援手", "en": "extend a helping hand"}, {"hanzi": "伸腿", "en": "stretch one's legs"}, {"hanzi": "伸展肢体", "en": "stretch and flex limbs"}, {"hanzi": "向外延伸", "en": "extend outward"}], "idioms": [{"hanzi": "能屈能伸", "pinyin": "néng qū néng shēn", "meaning_en": "able to bend and stretch; adaptable to circumstances"}, {"hanzi": "缩手缩脚", "pinyin": "suō shǒu suō jiǎo", "meaning_en": "cautious and hesitating; shrinking back hands and feet"}, {"hanzi": "引颈受戮", "pinyin": "yǐn jǐng shòu lù", "meaning_en": "stretch out one's neck for the sword; submit meekly to slaughter"}, {"hanzi": "大显身手", "pinyin": "dà xiǎn shēn shǒu", "meaning_en": "fully display one's prowess and skills"}], "character_decomposition": [{"character": "伸", "pinyin": "shēn", "meaning_en": "stretch; extend; reach out; expand", "meaning_es": "estirar; extender; prolongar; desplegar", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person flexing limbs)", "sound_component": "申 (shēn, lightning/straight line extending)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character combining person (亻) with lightning bolt piercing straight through (申), conveying extending the body straight.", "visual_mnemonic_story_en": "A person (亻) straightens their arms and spine in a straight vertical line (申) like lightning.", "visual_mnemonic_story_es": "Una persona (亻) estira sus brazos y columna en una línea recta (申) igual que un rayo.", "tone_mnemonic_anchor": "55", "cangjie": "OLWL", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "寒冬悄然褪去，春回大地，沉睡的柳枝在细雨中缓缓伸出了鹅黄色的嫩芽。生命的美好正在于这种向阳而生的力量，无论曾经经历怎样的霜冻，只要春风吹拂，便能重新伸展身姿，拥抱明媚的人间。", "pinyin": "Hándōng qiǎorán tuìqù, chūn huí dàdì, chénshuì de liǔzhī zài xìyǔ zhōng huǎnhuǎn shēnchū le éhuángsè de nènyá. Shēngmìng de měihǎo zhèng zài yú zhè zhǒng xiàngyáng'érshēng de lìliàng, wúlùn céngjīng jīnglì zěnyàng de shuāngdòng, zhǐyào chūnfēng chuīfú, biàn néng chóngxīn shēnzhǎn shēnzī, yōngbào míngmèi de rénjiān.", "en": "Winter quietly retreats and spring returns as slumbering willow branches stretch yellow buds in the rain. Life's grace lies in this solar power: no matter the frost endured, once spring breezes blow, it stretches anew to embrace sunshine.", "es": "El crudo invierno se retira y las ramas del sauce dormido extienden tiernos brotes amarillos bajo la llovizna. La belleza vital reside en crecer hacia la luz: tras las heladas, la brisa primaveral permite desplegarse y abrazar la vida."}, {"id": "#2", "hanzi": "在现代机械工程与智能机器人研发领域，仿生机械臂的伸缩关节设计是实现高精度微创手术的核心技术。研发人员通过模拟人体肌肉纤维的伸缩力学特性，使机械手术爪在狭窄空间内兼具柔顺伸展与精微作业能力。", "pinyin": "Zài xiàndài jīxiè gōngchéng yǔ zhìnéng jīqìrén yánfā lǐngyù, fǎngshēng jīxièbì de shēnsuō guānjié shèjì shì shíxiàn gāojīngdù wēichuàng shǒushù de héxīn jìshù. Yánfā rényuán tōngguò mónǐ réntǐ jīròu xiānwéi de shēnsuō lìxué tèxìng, shǐ jīxiè shǒushùzhuǎ zài xiázhǎi kōngjiān nèi jiānjù róushùn shēnzhǎn yǔ jīngwēi zuòyè nénglì.", "en": "In robotics, telescopic joint design for bionic robotic arms is core to minimally invasive surgery. By simulating human muscle fiber mechanics, surgical claws achieve supple extension and micrometric dexterity in tight spaces.", "es": "En la robótica biomédica, el diseño de articulaciones extensibles para brazos biónicos es clave en cirugía mínimamente invasiva. Al imitar las fibras musculares humanas, las pinzas quirúrgicas logran extenderse con precisión en cavidades reducidas."}]}, {"meanings_summary": {"en": "finger; digits of the hand", "es": "dedo; dedos de la mano"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The hand's (手) pointing appendages (指) are our agile fingers.", "composite_memory_hook_es": "Los extremos señaladores (指) de la mano (手) componen nuestros hábiles dedos.", "cultural_and_cognitive_roots": "The proverb '十指连心' (ten fingers connect to the heart) reflects the neurological truth that fingertips possess the highest density of tactile receptors, metaphorically linking manual touch with emotional empathy.", "tone_sandhi_and_pitch_modulation": "Tone sandhi: two consecutive 3rd tones (214-214) shift the first syllable to a rising 2nd tone (35): pronounced shóuzhǐ (35-214)."}, "semantic_boundary_contrasts": {"core_nuance": "手指 refers specifically and anatomically to the individual digits extending from the hand.", "contrasts": [{"id": "1", "compared_word": "手指 vs. 手掌", "pinyin": "shǒuzhǎng", "analysis": "手掌 is the flat broad palm of the hand, whereas 手指 refers to the articulated digits extending from the palm."}, {"id": "2", "compared_word": "手指 vs. 手头", "pinyin": "shǒutóu", "analysis": "手头 is an abstract idiom referring to one's current financial or material condition (e.g., 手头紧), unrelated to anatomy."}, {"id": "3", "compared_word": "手指 vs. 脚趾", "pinyin": "jiǎozhǐ", "analysis": "手指 refers to fingers of the hand, whereas 脚趾 refers to toes of the foot."}]}, "traps_and_cognates": {"look_alikes": [{"character": "毛", "pinyin": "máo", "meaning_en": "hair; fur", "distinction_note": "Bottom stroke bends rightward with a hook (乚) rather than a curved sweep"}, {"character": "牛", "pinyin": "niú", "meaning_en": "ox; cow", "distinction_note": "Vertical stroke pierces top horizontal stroke; distinct from 手"}, {"character": "脂", "pinyin": "zhī", "meaning_en": "fat; grease", "distinction_note": "Has meat/moon radical 月 on the left instead of hand 扌"}, {"character": "诣", "pinyin": "yì", "meaning_en": "attainment; visit", "distinction_note": "Has speech radical 讠 on the left instead of hand 扌"}], "etymological_cognates": [{"character": "掌", "pinyin": "zhǎng", "gloss_en": "palm; sole"}, {"character": "拳", "pinyin": "quán", "gloss_en": "fist"}, {"character": "甲", "pinyin": "jiǎ", "gloss_en": "fingernail; armor"}, {"character": "爪", "pinyin": "zhuǎ", "gloss_en": "claw; talon"}]}, "id": "23", "hanzi": "手指", "pinyin": "shǒu zhǐ", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "any of the five jointed terminal appendages of the human hand", "definition_es": "cada una de las cinco extremidades articuladas de la mano humana", "example_phrase": "手指灵活 (nimble fingers)"}], "example_sentences": [{"id": "#1", "hanzi": "年轻的钢琴家坐在聚光灯下，十根修长的手指在黑白琴键上飞速跃动，流淌出令人沉醉的激昂乐章。", "pinyin": "Niánqīng de gāngqínjiā zuò zài jùguāngdēng xià, shí gēn xiūcháng de shǒuzhǐ zài hēibái qínjiàn shàng fēisù yuèdòng, liútǎng chū lìng rén chénzuì de jī'áng yuèzhāng.", "en": "Under the spotlight, the young pianist sat as his ten slender fingers danced swiftly over the black and white keys, pouring forth an intoxicating movement.", "es": "Bajo los reflectores, el joven pianista tocaba mientras sus diez dedos alargados danzaban sobre las teclas blancas y negras, desgranando una melodía apasionada."}, {"id": "#2", "hanzi": "随着现代智能终端的普及，多模态生物识别技术已通过采集手指静脉纹理特征，实现了金融级安全认证。", "pinyin": "Suízhe xiàndài zhìnéng zhōngduān de pǔjí, duōmótài shēngwù shíbié jìshù yǐ tōngguò cǎijí shǒuzhǐ jìngmài wénlǐ tèzhēng, shíxiàn le jīnróng jí ānquán rènzhèng.", "en": "With the ubiquity of smart terminals, multimodal biometric recognition has achieved financial-grade authentication by capturing finger vein patterns.", "es": "Con el auge de los dispositivos inteligentes, la identificación biométrica multimodal autentica transacciones financieras captando el mapa de venas del dedo."}], "collocations": [{"hanzi": "手指灵活", "en": "nimble / dexterous fingers"}, {"hanzi": "掰手指", "en": "count on one's fingers"}, {"hanzi": "手指受伤", "en": "injured finger"}, {"hanzi": "十根手指", "en": "ten fingers"}, {"hanzi": "手指肚", "en": "pad of the finger / fingertip"}, {"hanzi": "咬破手指", "en": "bite one's finger"}], "idioms": [{"hanzi": "了如指掌", "pinyin": "liǎo rú zhǐ zhǎng", "meaning_en": "know something as clearly as the palm and fingers of one's hand"}, {"hanzi": "屈指可数", "pinyin": "qū zhǐ kě shǔ", "meaning_en": "can be counted on one's fingers; very few in number"}, {"hanzi": "指鹿为马", "pinyin": "zhǐ lù wéi mǎ", "meaning_en": "point to a deer and call it a horse; deliberate falsehood"}, {"hanzi": "十指连心", "pinyin": "shí zhǐ lián xīn", "meaning_en": "all ten fingers connect to the heart; pain deeply felt"}], "character_decomposition": [{"character": "手", "pinyin": "shǒu", "meaning_en": "hand; skilled person", "meaning_es": "mano; persona diestra", "radical": "手", "radical_meaning_en": "hand", "meaning_component": "手 (pictogram of palm and five fingers)", "sound_component": "手 (inherent phoneme)", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Pictogram of an open human palm displaying outstretched fingers.", "visual_mnemonic_story_en": "An open hand (手) extends five distinct finger lines ready to grasp.", "visual_mnemonic_story_es": "Una mano abierta (手) extiende sus dedos lista para asir y trabajar.", "tone_mnemonic_anchor": "214", "cangjie": "Q", "traditional": ""}, {"character": "指", "pinyin": "zhǐ", "meaning_en": "finger; point; direct; indicate", "meaning_es": "dedo; apuntar; indicar; señalar", "radical": "手", "radical_meaning_en": "hand", "meaning_component": "扌 (hand radical)", "sound_component": "旨 (zhǐ, purpose/delicious marker)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character pairing hand (扌) with pointing out intention (旨), denoting the pointing finger.", "visual_mnemonic_story_en": "The hand's foremost tool (扌) points directly toward the target destination (旨).", "visual_mnemonic_story_es": "La herramienta frontal de la mano (扌) señala directamente hacia el objetivo (旨).", "tone_mnemonic_anchor": "214", "cangjie": "QPA", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "母亲那一双布满老茧的手指，曾抚平过我童年无数次的跌倒与哭泣。岁月在她的指节上刻下了粗糙的沟壑，但当那双温暖的手指轻轻拂过额头，所有的疲惫与委屈都会在刹那间烟消云散。", "pinyin": "Mǔqīn nà yì shuāng bùmǎn lǎojiǎn de shǒuzhǐ, céng fǔpíng guò wǒ tóngnián wúshù cì de diēdǎo yǔ kūqì. Suìyuè zài tā de zhǐjié shàng kèxià le cūcāo de gōuhè, dàn dāng nà shuāng wēnnuǎn de shǒuzhǐ qīngqīng fúguò étóu, suǒyǒu de píbèi yǔ wěiqu dōu huì zài chànà jiān yānxiāoyúnsàn.", "en": "Mother's calloused fingers smoothed away countless falls and tears in my childhood. Years carved rough furrows into her knuckles, but when those warm fingers brushed across my brow, all weariness vanished instantly.", "es": "Los dedos encallecidos de mi madre calmaron incontables caídas de mi infancia. El paso del tiempo grabó surcos en sus nudillos, pero cuando rozaban mi frente con ternura, cualquier fatiga se disipaba al instante."}, {"id": "#2", "hanzi": "在工业机器人高精装配领域，微米级多指柔性灵巧手代表着精密机械制造的尖端水平。通过在仿生手指末端集成阵列式触觉传感器，机器人能够在毫秒间精准感知接触面摩擦力，实现脆弱元件的安全抓取。", "pinyin": "Zài gōngyè jīqìrén gāojīng zhuāngpèi lǐngyù, wēimǐ jí duōzhǐ róuxìng língqiǎo shǒu dàibiǎo zhe jīngmì jīxiè zhìzào de jiānduān shuǐpíng. Tōngguò zài fǎngshēng shǒuzhǐ mòduān jíchéng zhènlièshì chùjué chuángǎnqì, jīqìrén nénggòu zài háomiǎo jiān jīngzhǔn gǎnzhī jiēchùmiàn mócālì, shíxiàn cuìruò yuánjiàn de ānquán zhuāqǔ.", "en": "In precision industrial robotics, multifacted dexterous hands represent manufacturing frontiers. Integrating tactile sensor arrays on bionic fingertips enables robots to sense friction within milliseconds, safely gripping fragile components.", "es": "En la robótica de montaje, las manos biónicas multidedo representan la vanguardia técnica. Integrar sensores táctiles en las yemas permite detectar la fricción en milisegundos para manipular componentes delicados sin dañarlos."}]}, {"meanings_summary": {"en": "crooked; askew; winding; irregularly shaped; wobbling", "es": "torcido; chueco; torcido y desparejo; zigzagueante; desgarbado"}, "mnemonics_and_roots": {"composite_memory_hook_en": "What is not straight (歪) combined with hands wrenching and twisting (扭) produces a crooked, wobbly mess (歪歪扭扭).", "composite_memory_hook_es": "Lo que no es recto (歪) junto a manos que retuercen (扭) da lugar a trazos torcidos y desparejos (歪歪扭扭).", "cultural_and_cognitive_roots": "AABB reduplication emphasizes visual irregularity and playful clumsiness; in Chinese calligraphy culture where uprightness (正) signifies moral virtue, 歪扭 portrays innocent lack of discipline or physical decay.", "tone_sandhi_and_pitch_modulation": "55-55-214-214 contour. In colloquial speech, the second syllable often takes a light or neutral tone (wāi-wai-niǔ-niu)."}, "semantic_boundary_contrasts": {"core_nuance": "歪歪扭扭 specifically describes lines, handwriting, pathways, or physical movement that are crooked, irregular, and lack straightness.", "contrasts": [{"id": "1", "compared_word": "歪歪扭扭 vs. 弯弯曲曲", "pinyin": "wānwānqūqū", "analysis": "弯弯曲曲 describes smooth, natural, flowing bends (e.g., winding rivers, serpentine mountain roads), whereas 歪歪扭扭 suggests clumsy, unsightly, or irregular jagged crookedness."}, {"id": "2", "compared_word": "歪歪扭扭 vs. 崎岖", "pinyin": "qíqū", "analysis": "崎岖 emphasizes rugged, steep, rocky mountain topography difficult to traverse, whereas 歪歪扭扭 characterizes unaligned visual lines or stumbling footsteps."}, {"id": "3", "compared_word": "歪歪扭扭 vs. 潦草", "pinyin": "liáocǎo", "analysis": "潦草 strictly describes hasty, illegible handwriting or careless work, while 歪歪扭扭 denotes uneven alignment and physical deviation."}]}, "traps_and_cognates": {"look_alikes": [{"character": "正", "pinyin": "zhèng", "meaning_en": "upright; straight", "distinction_note": "Lacks the top 不 component of 歪; direct semantic antonym"}, {"character": "纽", "pinyin": "niǔ", "meaning_en": "button; knot", "distinction_note": "Has silk radical 纟 on the left instead of hand 扌"}, {"character": "妞", "pinyin": "niū", "meaning_en": "girl; lass", "distinction_note": "Has woman radical 女 on the left instead of hand 扌"}, {"character": "羞", "pinyin": "xiū", "meaning_en": "shy; shame", "distinction_note": "Features 羊 (sheep) over 丑 instead of hand 扌"}], "etymological_cognates": [{"character": "斜", "pinyin": "xié", "gloss_en": "slanting; tilted"}, {"character": "曲", "pinyin": "qū", "gloss_en": "bent; curved"}, {"character": "偏", "pinyin": "piān", "gloss_en": "deviated; off-center"}, {"character": "拐", "pinyin": "guǎi", "gloss_en": "turn corner; swerve"}]}, "id": "24", "hanzi": "歪歪扭扭", "pinyin": "wāi wai niǔ niǔ", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "crooked, uneven, askew, or irregularly aligned (often of handwriting, lines, or walking)", "definition_es": "torcido, desalineado o irregular (se dice de la caligrafía, líneas o el andar)", "example_phrase": "字写得歪歪扭扭 (handwriting is crooked and uneven)"}], "example_sentences": [{"id": "#1", "hanzi": "六岁的小外甥刚开始学写汉字，在练习本上用铅笔一笔一画写出歪歪扭扭的“爸爸妈妈”，模样十分可爱。", "pinyin": "Liù suì de xiǎo wàishēng gāng kāishǐ xué xiě hànzì, zài liànxí běn shàng yòng qiānbǐ yìbǐyíhuà xiě chū wāiwāiniǔniǔ de “bàba māma”, múyàng shífēn kě'ài.", "en": "My six-year-old nephew who just started learning Chinese characters wrote 'mom and dad' in crooked, uneven pencil strokes, looking utterly adorable.", "es": "Mi sobrino de seis años acaba de empezar a escribir hanzi, y trazó a lápiz un entrañable y torcido 'papá y mamá' en su libreta."}, {"id": "#2", "hanzi": "地震发生后，原本笔直宽阔的乡间柏油马路在强烈的地质断裂挤压下，瞬间撕裂成数段歪歪扭扭的残破断道。", "pinyin": "Dìzhèn fāshēng hòu, yuánběn bǐzhí kuānkuò de xiāngjiān bǎiyóu mǎlù zài qiángliè de dìzhì duànliè jǐyā xià, shùnjiān sīliè chéng shù duàn wāiwāiniǔniǔ de cánpò duàndào.", "en": "After the earthquake, the once straight and wide rural asphalt road was instantly torn into crooked, buckled fragments by fault line shearing.", "es": "Tras el terremoto, la carretera asfaltada antes recta quedó quebrada en varios tramos zigzagueantes y deformes por la fractura geológica."}], "collocations": [{"hanzi": "字迹歪歪扭扭", "en": "crooked handwriting"}, {"hanzi": "走得歪歪扭扭", "en": "walk wobbly / staggering"}, {"hanzi": "排得歪歪扭扭", "en": "arranged unevenly and crooked"}, {"hanzi": "歪歪扭扭的线条", "en": "wobbly, crooked lines"}, {"hanzi": "歪歪扭扭的篱笆", "en": "a crooked, askew fence"}, {"hanzi": "小路歪歪扭扭", "en": "a winding, uneven path"}], "idioms": [{"hanzi": "东倒西歪", "pinyin": "dōng dǎo xī wāi", "meaning_en": "toppling over in all directions; unsteady and rickety"}, {"hanzi": "七扭八歪", "pinyin": "qī niǔ bā wāi", "meaning_en": "crooked and twisted in all directions"}, {"hanzi": "歪门邪道", "pinyin": "wāi mén xié dào", "meaning_en": "crooked ways and dishonest practices"}, {"hanzi": "歪风邪气", "pinyin": "wāi fēng xié qì", "meaning_en": "unhealthy tendencies and perverse atmospheres"}], "character_decomposition": [{"character": "歪", "pinyin": "wāi", "meaning_en": "crooked; askew; devious; inclined", "meaning_es": "torcido; ladeado; chueco; inclinado", "radical": "止", "radical_meaning_en": "stop / foot", "meaning_component": "不 (not) + 正 (upright/straight)", "sound_component": "不 / 正 (compound ideograph)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Brilliant compound ideograph joining 'not' (不) atop 'upright' (正): what is not straight is crooked (歪).", "visual_mnemonic_story_en": "Placing 'not' (不) directly over 'upright' (正) literally creates 'not straight' = crooked.", "visual_mnemonic_story_es": "Colocar 'no' (不) sobre 'recto' (正) genera literalmente 'no recto' = torcido.", "tone_mnemonic_anchor": "55", "cangjie": "MFMYM", "traditional": ""}, {"character": "扭", "pinyin": "niǔ", "meaning_en": "turn; twist; wrench; wrenching motion", "meaning_es": "torcer; retorcer; girar; contorsionar", "radical": "手", "radical_meaning_en": "hand", "meaning_component": "扌 (hand twisting)", "sound_component": "丑 (chǒu, claw/twisted knot)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character combining hand (扌) with a knotted hand/cord (丑), describing twisting with force.", "visual_mnemonic_story_en": "Hands (扌) wrench and twist a stubborn knotted rope (丑).", "visual_mnemonic_story_es": "Las manos (扌) retuercen una cuerda anudada y rebelde (丑).", "tone_mnemonic_anchor": "214", "cangjie": "QNG", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "翻开泛黄的旧日记本，那几页用铅笔写下的字迹歪歪扭扭，记录着童年最纯真的秘密。虽然笔画稚嫩甚至偶有涂改，但每一笔都饱含着对世界最初的敬畏。那些歪歪扭扭的字迹，正是生命最鲜活的印记。", "pinyin": "Fānkāi fànhuáng de jiù rìjìběn, nà jǐ yè yòng qiānbǐ xiěxià de zìjì wāiwāiniǔniǔ, jìlù zhe tóngnián zuì chúnzhēn de mìmì. Suīrán bǐhuà zhìnèn shènzhì ǒu yǒu túgǎi, dàn měi yí bǐ dōu bǎohán zhe duì shìjiè zuìchū de jìngwèi. Nàxiē wāiwāiniǔniǔ de zìjì, zhèng shì shēngmìng zuì xiānhuó de yìnjì.", "en": "Opening the yellowed old diary, those pages written in crooked pencil strokes record childhood's purest secrets. Though strokes were immature and smudged, each stroke contained awe toward the world, becoming life's most vivid imprint.", "es": "Al abrir el viejo diario amarillento, aquellas páginas a lápiz con trazos torcidos guardan los secretos más puros de la infancia. Aunque los trazos eran torpes, reflejaban asombro por el mundo, convirtiéndose en huellas vivas del pasado."}, {"id": "#2", "hanzi": "在古建筑保护修复工程中，老工匠们面对岁月侵蚀导致歪歪扭扭的木构架梁柱，始终坚持修旧如旧的原则。通过微创纠偏与碳纤维加固技术，既校正了结构的安全承载极限，又完整保留了岁月沉淀的历史沧桑美感。", "pinyin": "Zài gǔ jiànzhù bǎohù xiūfù gōngchéng zhōng, lǎo gōngjiàng men miànduì suìyuè qīnshí dǎozhì wāiwāiniǔniǔ de mù gòujià liángzhù, shǐzhōng jiānchí xiūjiùrújìu de yuánzé. Tōngguò wēichuàng jiūpiān yǔ tànxiānwéi jiāgù jìshù, jì jiàozhèng le jiégòu de ānquán chéngzài jíxiàn, yòu wánzhěng bǎoliú le suìyuè chéndiàn de lìshǐ cāngsāng měigǎn.", "en": "In restoring historical architecture, veteran artisans confronting timbers distorted and askew by centuries abide by the principle of restoring the old as it was. Correcting load thresholds via micro-realignment preserves authentic aged beauty.", "es": "En la restauración patrimonial, los maestros artesanos ante vigas de madera torcidas por los siglos aplican el principio de reparar conservando la vejez. Reajustar la carga estructural rescata la seguridad sin borrar la pátina histórica."}]}, {"meanings_summary": {"en": "to hand over; to pass; to deliver; in succession", "es": "pasar; entregar en mano; transmitir; sucesivamente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Moving along the postal path (辶) from one sequential station to the next (弟) delivers and hands over the message.", "composite_memory_hook_es": "Avanzar por el camino postal (辶) de estación en estación (弟) permite entregar y pasar el mensaje en mano.", "cultural_and_cognitive_roots": "Originating in China's ancient imperial postal relay courier system ('驿递'), where couriers on horseback handed off confidential dispatches across post stations to achieve rapid long-distance delivery.", "tone_sandhi_and_pitch_modulation": "51 pitch contour. A crisp, direct falling 4th tone (51) that evokes the decisive physical motion of passing an item into another's hands."}, "semantic_boundary_contrasts": {"core_nuance": "递 emphasizes handing an object directly to another person with the hand, or transmitting sequentially across stations.", "contrasts": [{"id": "1", "compared_word": "递 vs. 给", "pinyin": "gěi", "analysis": "给 is the universal preposition/verb for giving, whereas 递 specifically denotes the physical kinetic gesture of extending one's hand to pass an object across a short distance."}, {"id": "2", "compared_word": "递 vs. 送", "pinyin": "sòng", "analysis": "送 implies transporting something over longer distances or presenting a gift, whereas 递 focuses on immediate hand-to-hand transfer."}, {"id": "3", "compared_word": "递 vs. 呈", "pinyin": "chéng", "analysis": "呈 is an elevated administrative verb for formal upward submission to superiors, while 递 is applicable across casual and professional contexts."}]}, "traps_and_cognates": {"look_alikes": [{"character": "梯", "pinyin": "tī", "meaning_en": "ladder; stairs", "distinction_note": "Features wood radical 木 on the left instead of motion 辶"}, {"character": "涕", "pinyin": "tì", "meaning_en": "tears; nasal mucus", "distinction_note": "Features water radical 氵 on the left instead of motion 辶"}, {"character": "第", "pinyin": "dì", "meaning_en": "ordinal prefix", "distinction_note": "Features bamboo radical 竹 on top of 弟"}, {"character": "弟", "pinyin": "dì", "meaning_en": "younger brother", "distinction_note": "The internal phonetic component itself"}], "etymological_cognates": [{"character": "送", "pinyin": "sòng", "gloss_en": "send; deliver in the 辶 radical family"}, {"character": "达", "pinyin": "dá", "gloss_en": "reach; arrive"}, {"character": "传", "pinyin": "chuán", "gloss_en": "pass on; transmit"}, {"character": "交", "pinyin": "jiāo", "gloss_en": "hand over; exchange"}]}, "id": "25", "hanzi": "递", "pinyin": "dì", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to hand something to someone; pass along by hand", "definition_es": "entregar algo en mano a alguien; pasar un objeto", "example_phrase": "递上一杯热茶 (hand over a cup of hot tea)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Formal", "definition_en": "to transmit, forward, or escalate in successive order", "definition_es": "transmitir o avanzar en orden progresivo", "example_phrase": "逐级呈递 (escalate successively)"}], "example_sentences": [{"id": "#1", "hanzi": "看到爷爷在书桌前揉着酸痛的眼睛，懂事的小孙女赶忙倒了一杯温水，双手轻轻递到爷爷手中。", "pinyin": "Kàndào yéye zài shūzhuō qián róu zhe suāntòng de yǎnjing, dǒngshì de xiǎo sūnnǚ gǎnmáng dào le yì bēi wēnshuǐ, shuāngshǒu qīngqīng dì dào yéye shǒu zhōng.", "en": "Seeing grandpa rubbing his tired eyes at the desk, the thoughtful granddaughter poured warm water and gently handed it to him with both hands.", "es": "Al ver al abuelo frotarse los ojos cansados en el escritorio, la atenta nieta sirvió agua tibia y se la entregó con ambas manos con delicadeza."}, {"id": "#2", "hanzi": "在外资企业入驻审批流程中，行政服务大厅推行一窗通办改革，企业无须在各个审批部门间反复递交材料。", "pinyin": "Zài wàizī qǐyè rùzhù shěnpī liúchéng zhōng, xíngzhèng fúwù dàtīng tuīxíng yì chuāng tōng bàn gǎigé, qǐyè wúxū zài gè gè shěnpī bùmén jiān fǎnfù dìjiāo cáiliào.", "en": "In foreign enterprise settlement approval, the administrative service hall implemented single-window reforms so firms need not repeatedly submit documents across departments.", "es": "En la aprobación de inversiones extranjeras, la ventanilla única eliminó la necesidad de que las empresas entreguen documentación repetidamente en distintas oficinas."}], "collocations": [{"hanzi": "递交申请", "en": "submit / hand in an application"}, {"hanzi": "递送包裹", "en": "deliver parcels"}, {"hanzi": "递过来", "en": "hand it over here"}, {"hanzi": "投递员", "en": "mail carrier / deliverer"}, {"hanzi": "顺手递给", "en": "hand over in passing"}, {"hanzi": "递增", "en": "increase progressively"}], "idioms": [{"hanzi": "暗度陈仓", "pinyin": "àn dù chén cāng", "meaning_en": "advance secretly while making feints elsewhere"}, {"hanzi": "循序渐进", "pinyin": "xún xù jiàn jìn", "meaning_en": "proceed in an orderly, step-by-step manner"}, {"hanzi": "投桃报李", "pinyin": "tóu táo bào lǐ", "meaning_en": "give a plum in return for a peach; exchange gifts"}, {"hanzi": "送往迎来", "pinyin": "sòng wǎng yíng lái", "meaning_en": "see off departing guests and welcome arriving ones"}], "character_decomposition": [{"character": "递", "pinyin": "dì", "meaning_en": "hand over; pass; deliver; transfer", "meaning_es": "entregar; pasar; remitir; transmitir", "radical": "辵", "radical_meaning_en": "walk / movement", "meaning_component": "辶 (motion along a path)", "sound_component": "弟 (dì, younger brother / sequential steps)", "stroke_count": "10", "composition_type": "半包围结构", "etymology_and_mnemonic": "Phono-semantic character pairing movement along roads (辶) with succession/stages (弟), depicting relay runners handing over mail.", "visual_mnemonic_story_en": "A messenger moves along the path (辶) passing relay items to the next brother in sequence (弟).", "visual_mnemonic_story_es": "Un mensajero avanza por el camino (辶) entregando el relevo en mano al siguiente compañero (弟).", "tone_mnemonic_anchor": "51", "cangjie": "YCNH", "traditional": "遞"}], "extended_reading_passages": [{"id": "#1", "hanzi": "有时候，人世间最动人的关怀往往不需要千言万语。雨天里陌生人递来的一把雨伞，冬夜里摊主递来的一碗热汤，这些看似不经意的动作，却能在冰冷的世界里传递无限暖意，照亮彼此前行的夜路。", "pinyin": "Yǒushíhou, rénshìjiān zuì dòngrén de guānhuái wǎngwǎng bù xūyào qiānyánwànyǔ. Yǔtiān lǐ mòshēngrén dì lái de yì bǎ yǔsǎn, dōngyè lǐ tānzhǔ dì lái de yì wǎn rètāng, zhèxiē kànsì bùjīngyì de dòngzuò, què néng zài bīnglěng de shìjiè lǐ chuándì wúxiàn nuǎnyì, zhàoliàng bǐcǐ qiánxíng de yèlù.", "en": "Sometimes the most touching kindness requires no words: an umbrella handed by a stranger in the rain, a bowl of hot soup passed on a winter night. These casual gestures transmit warmth through a chilly world, lighting the road ahead.", "es": "A veces la mayor bondad no precisa palabras: un paraguas tendido por un desconocido bajo la lluvia o un tazón de sopa caliente entregado en una noche fría transmiten una calidez infinita que alumbra el camino en la penumbra."}, {"id": "#2", "hanzi": "在现代智慧物流生态系统中，自动化分拣与最后一公里即时递送效率已成为核心指标。依托高精度定位与无人配送车网络，冷链医药与关键生鲜包裹的递送时效大幅压缩，为城市保供构筑了敏捷韧性的物流通道。", "pinyin": "Zài xiàndài zhìhuì wùliú shēngtài xìtǒng zhōng, zìdònghuà fēnjiǎn yǔ zuìhòu yì gōnglǐ jíshí dìsòng xiàolǜ yǐ chéngwéi héxīn zhǐbiāo. Yītuō gāojīngdù dìngwèi yǔ wúrén pèisòng chē wǎngluò, lěngliàn yīyào yǔ guānjiàn shēngxiān bāoguǒ de dìsòng shíxiào dàfú yāsuō, wèi chéngshì bǎogōng gòuzhù le mǐnjié rènxìng de wùliú tōngdào.", "en": "In smart logistics, automated sorting and last-mile on-demand delivery efficiency are key indicators. Leveraging geolocation and autonomous delivery vehicles, pharmaceutical and fresh deliveries compress timelines, building agile supply corridors.", "es": "En la logística inteligente, la clasificación automatizada y la entrega inmediata de última milla son prioritarias. Con geolocalización y vehículos autónomos, la entrega de fármacos y alimentos reduce tiempos forjando canales de suministro ágiles."}]}, {"meanings_summary": {"en": "head; skull; brains; mental capacity", "es": "cabeza; cráneo; seso; inteligencia; mente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The brain (脑) encased within the fleshly cranial pouch (袋) forms our head and mind (脑袋).", "composite_memory_hook_es": "El cerebro (脑) alojado dentro de la cavidad o saco craneal (袋) conforma nuestra cabeza y mente (脑袋).", "cultural_and_cognitive_roots": "Metaphorically visualizes the human cranium as a biological pouch ('dài') containing brains ('nǎo'); colloquial Chinese frequently uses 'nǎodai' to indicate practical wits ('商业脑袋') or impulsive decisions ('拍脑袋').", "tone_sandhi_and_pitch_modulation": "214-51 contour. In standard colloquial Mandarin, the second syllable is almost universally pronounced in a neutral tone (nǎodai / nǎodɑi)."}, "semantic_boundary_contrasts": {"core_nuance": "脑袋 refers colloquially to the physical head and anatomical skull, or informally to a person's mental wits and ingenuity.", "contrasts": [{"id": "1", "compared_word": "脑袋 vs. 头部", "pinyin": "tóubù", "analysis": "头部 is a formal medical, scientific, and technical anatomical term, whereas 脑袋 is everyday, vivid spoken Chinese."}, {"id": "2", "compared_word": "脑袋 vs. 头脑", "pinyin": "tóunǎo", "analysis": "头脑 refers primarily to cognitive reasoning, mental capacity, or organizational leadership (e.g., 清醒的头脑), while 脑袋 can refer literally to the physical head."}, {"id": "3", "compared_word": "脑袋 vs. 脑海", "pinyin": "nǎohǎi", "analysis": "脑海 is a poetic/literary term denoting the subjective theatre of memory and consciousness (e.g., 浮现在脑海中), not physical anatomy."}]}, "traps_and_cognates": {"look_alikes": [{"character": "恼", "pinyin": "nǎo", "meaning_en": "annoyed; irritated", "distinction_note": "Features heart radical 忄 on the left instead of flesh 月"}, {"character": "贷", "pinyin": "dài", "meaning_en": "loan; borrow", "distinction_note": "Features shell radical 贝 at the bottom instead of clothing 衣"}, {"character": "装", "pinyin": "zhuāng", "meaning_en": "attire; load", "distinction_note": "Features 壮 on top instead of 代 above 衣"}, {"character": "囊", "pinyin": "náng", "meaning_en": "pocket; bag", "distinction_note": "Much more complex radical structure for pouch"}], "etymological_cognates": [{"character": "头", "pinyin": "tóu", "gloss_en": "head; chief"}, {"character": "颅", "pinyin": "lú", "gloss_en": "skull; cranium"}, {"character": "胞", "pinyin": "bāo", "gloss_en": "cell; uterine sac"}, {"character": "肚", "pinyin": "dù", "gloss_en": "belly; stomach sac"}]}, "id": "26", "hanzi": "脑袋", "pinyin": "nǎo dai", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the human physical head or cranium containing the brain", "definition_es": "la cabeza física humana que aloja el cerebro", "example_phrase": "摸摸脑袋 (scratch or touch one's head)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Colloquial", "definition_en": "intellect, mental wits, or cleverness", "definition_es": "inteligencia, seso o agudeza mental", "example_phrase": "很有商业脑袋 (have a great head for business)"}], "example_sentences": [{"id": "#1", "hanzi": "小弟弟做错了数学算术题，有些害羞地挠了挠毛茸茸的小脑袋，逗得全家人都哈哈大笑。", "pinyin": "Xiǎo dìdi zuòcuò le shùxué suànshù tí, yǒuxiē hàixiū de náo le náo máorōngrōng de xiǎo nǎodai, dòu de quánjiā rén dōu hāhā dàxiào.", "en": "Having made a mistake on his math arithmetic problem, my little brother shyly scratched his fluffy little head, making the whole family burst into laughter.", "es": "Al equivocarse en la cuenta de matemáticas, mi hermanito se rascó la cabecita con timidez, haciendo reír a toda la familia a carcajadas."}, {"id": "#2", "hanzi": "现代神经认知科学与类脑计算研究发现，人类脑袋在处理高维度模糊信息时表现出的超低能耗与高容错性，为下一代神经形态芯片提供了重要启发。", "pinyin": "Xiàndài shénjīng rènzhī kēxué yǔ lèi nǎo jìsuàn yánjiū fāxiàn, rénlèi nǎodai zài chǔlǐ gāo wéidù móhu xìnxī shí biǎoxiàn chū de chāodī nénghào yǔ gāo róngcuòxìng, wèi xià yí dài shénjīng xíngtài xīnpiàn tígōng le zhòngyào qǐfā.", "en": "Neurocognitive science and brain-inspired computing have revealed that the ultra-low energy consumption and high fault tolerance of human brains in processing complex fuzzy data inspire neuromorphic chips.", "es": "La neurociencia cognitiva ha descubierto que el bajo consumo energético y la tolerancia a fallos del cerebro humano al procesar datos complejos inspiran el diseño de chips neuromórficos."}], "collocations": [{"hanzi": "摸摸脑袋", "en": "pat or rub one's head"}, {"hanzi": "歪着脑袋", "en": "cock one's head to one side"}, {"hanzi": "脑袋灵活", "en": "quick-witted / sharp head"}, {"hanzi": "拍脑袋决定", "en": "make a knee-jerk decision off the top of one's head"}, {"hanzi": "脑袋发懵", "en": "one's head is dazed / befuddled"}, {"hanzi": "摇晃脑袋", "en": "shake one's head"}], "idioms": [{"hanzi": "头晕脑胀", "pinyin": "tóu yūn nǎo zhàng", "meaning_en": "dizzy and light-headed; head swelling with fatigue"}, {"hanzi": "呆头呆脑", "pinyin": "dāi tóu dāi nǎo", "meaning_en": "slow-witted and wooden-headed; mutton-headed"}, {"hanzi": "探头探脑", "pinyin": "tàn tóu tàn nǎo", "meaning_en": "pop one's head in and peer around slyly"}, {"hanzi": "没头没脑", "pinyin": "méi tóu méi nǎo", "meaning_en": "without head or tail; completely senseless and abrupt"}], "character_decomposition": [{"character": "脑", "pinyin": "nǎo", "meaning_en": "brain; cranium; intellect", "meaning_es": "cerebro; seso; entendimiento", "radical": "肉", "radical_meaning_en": "meat / flesh", "meaning_component": "月/肉 (flesh/body organ)", "sound_component": "囟 / 凶 (xìn, fontanelle of skull)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts bodily tissue (月) housed under the cranial fontanelle (囟/凶) with hair fibers, representing the physical brain.", "visual_mnemonic_story_en": "The vital organ of flesh (月) protected inside the skull (凶/匕) powers thoughts and wits.", "visual_mnemonic_story_es": "El órgano vital de carne (月) resguardado dentro del cráneo (凶/匕) impulsa las ideas y la lucidez.", "tone_mnemonic_anchor": "214", "cangjie": "BYUK", "traditional": "腦"}, {"character": "袋", "pinyin": "dai", "meaning_en": "pouch; bag; pocket; sack", "meaning_es": "bolsa; saco; faltriquera", "radical": "衣", "radical_meaning_en": "clothing", "meaning_component": "衣 (fabric garment/container)", "sound_component": "代 (dài, replacement/generation)", "stroke_count": "11", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic character pairing garment (衣) with 代 (dài), denoting a fabric pouch sewn to hold precious contents.", "visual_mnemonic_story_en": "A pouch of cloth garment (衣) holds valuables across generations (代).", "visual_mnemonic_story_es": "Una bolsa de tela (衣) contiene objetos valiosos que pasan de una generación a otra (代).", "tone_mnemonic_anchor": "51", "cangjie": "OPYV", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "夕阳的余晖洒在静谧的村庄里，老爷爷戴着老花镜，一边看着报纸，一边轻轻抚摸着膝头孙子毛茸茸的小脑袋。屋檐下微风拂过，岁月安详得如同一幅水墨画。小小的脑袋里装满了对外头世界的奇思妙想。", "pinyin": "Xīyáng de yúhuī sǎ zài jìngmì de cūnzhuāng lǐ, lǎoyéye dài zhe lǎohuājìng, yìbiān kàn zhe bàozhǐ, yìbiān qīngqīng fǔmō zhe xītóu sūnzi máorōngrōng de xiǎo nǎodai. Wūyán xià wēifēng fúguò, suìyuè ānxiáng de rútóng yì fú shuǐmòhuà. Xiǎoxiǎo de nǎodai lǐ zhuāngmǎn le duì wàitóu shìjiè de qísīmiàoxiǎng.", "en": "Sunset glow bathed the tranquil village as grandfather read his paper while stroking the fluffy head of his grandson on his knee. Under the eaves breezes blew, peaceful as a wash painting. That little head was full of wonder for the world.", "es": "La luz del atardecer doraba la aldea tranquila mientras el abuelo leía acariciando la cabecita de su nieto en su regazo. La brisa bajo el alero evocaba una pintura apacible. Aquella cabecita rebosaba asombro por el mundo exterior."}, {"id": "#2", "hanzi": "在智能网联汽车的研发试验中，碰撞假人脑袋加速度传感器是测定被动安全防护等级的关键指标。工程师通过精确计算碰撞瞬间假人脑袋承受的动能冲击峰值，不断优化安全气囊点爆算法与吸能转向柱结构。", "pinyin": "Zài zhìnéng wǎnglián qìchē de yánfā shìyàn zhōng, pèngzhuàng jiǎrén nǎodai jiāsùdù chuángǎnqì shì cèdìng bèidòng ānquán fánghù děngjí de guānjiàn zhǐbiāo. Gōngchéngshī tōngguò jīngquè jìsuàn pèngzhuàng shùnjiān jiǎrén nǎodai chéngshòu de dòngnéng chōngjī fēngzhí, bùduàn yōuhuà ānquán qìnáng diǎnbào suànfǎ yǔ xīnén zhuǎnxiàngzhù jiégòu.", "en": "In crash testing for intelligent vehicles, crash dummy head acceleration sensors are key indicators measuring passive protection. By calculating impact peaks on the head, engineers optimize airbag deployment algorithms and steering columns.", "es": "En los ensayos automovilísticos de seguridad, los sensores de aceleración en la cabeza de los maniquíes miden la protección pasiva. Calcular el impacto recibido en la cabeza permite perfeccionar los algoritmos de los airbags y columnas de dirección."}]}, {"meanings_summary": {"en": "lady; Madam; Ms.; gentlewoman", "es": "señora; señorita; dama; distinguida dama"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A woman (女) endowed with the honor and wisdom of a scholar (士) is addressed as an esteemed lady (女士).", "composite_memory_hook_es": "Una mujer (女) investida con la distinción y cultura de un letrado (士) recibe el honroso título de dama (女士).", "cultural_and_cognitive_roots": "Historically, 'shì' designated the educated gentry class. In modern Chinese diplomacy and civil society, pairing 'nǚ' with 'shì' elevated female address to universal parity with 'xiānsheng' (先生), honoring female dignity without marital distinction.", "tone_sandhi_and_pitch_modulation": "214-51 contour. The dipping 3rd tone of nǚ is pronounced as a half-3rd tone (21 low) before the crisp falling 4th tone of shì (51)."}, "semantic_boundary_contrasts": {"core_nuance": "女士 is a neutral, polite, and respectful formal address for an adult woman regardless of marital status.", "contrasts": [{"id": "1", "compared_word": "女士 vs. 夫人", "pinyin": "fūrén", "analysis": "夫人 is a high-register diplomatic or ceremonial term specifically indicating someone's wife (Madam/First Lady), whereas 女士 applies generally to any woman."}, {"id": "2", "compared_word": "女士 vs. 小姐", "pinyin": "xiǎojiě", "analysis": "小姐 traditionally means Miss/unmarried woman, but can carry ambiguous or service-industry connotations in certain mainland contexts; 女士 is universally safe and respectful."}, {"id": "3", "compared_word": "女士 vs. 太太", "pinyin": "tàitai", "analysis": "太太 is a colloquial or domestic term referring specifically to a married woman/wife, whereas 女士 ignores marital status entirely."}]}, "traps_and_cognates": {"look_alikes": [{"character": "土", "pinyin": "tǔ", "meaning_en": "soil; earth", "distinction_note": "Bottom horizontal stroke is longer than the top stroke, whereas in 士 top stroke is longer"}, {"character": "干", "pinyin": "gān", "meaning_en": "do; dry", "distinction_note": "Top stroke is horizontal and vertical stroke extends through top"}, {"character": "子", "pinyin": "zǐ", "meaning_en": "child", "distinction_note": "Has a curved hook and horizontal stroke; distinct from 女"}, {"character": "刃", "pinyin": "rèn", "meaning_en": "blade edge", "distinction_note": "Different structure entirely"}], "etymological_cognates": [{"character": "妇", "pinyin": "fù", "gloss_en": "married woman; matron"}, {"character": "娘", "pinyin": "niáng", "gloss_en": "mother; young woman"}, {"character": "贤", "pinyin": "xián", "gloss_en": "virtuous; worthy person"}, {"character": "儒", "pinyin": "rú", "gloss_en": "Confucian scholar"}]}, "id": "27", "hanzi": "女士", "pinyin": "nǚ shì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Formal", "definition_en": "polite, respectful term of address or reference for an adult woman regardless of marital status", "definition_es": "tratamiento cortés y respetuoso para una mujer adulta independiente de su estado civil", "example_phrase": "女士们，先生们 (ladies and gentlemen)"}], "example_sentences": [{"id": "#1", "hanzi": "在盛大的国际慈善晚宴开始前，主持人面带微笑走向舞台中央，礼貌地说道：“各位女士，各位先生，欢迎大家莅临。”", "pinyin": "Zài shèngdà de guójì císhàn wǎnyàn kāishǐ qián, zhǔchírén miàn dài wēixiào zǒuxiàng wǔtái zhōngyāng, lǐmào de shuōdào: “Gèwèi nǚshì, gèwèi xiānsheng, huānyíng dàjiā lìlín.”", "en": "Before the grand international charity banquet commenced, the host walked to center stage with a smile and politely announced: 'Ladies and gentlemen, welcome.'", "es": "Antes de iniciar la gala benéfica internacional, el presentador se acercó al escenario con una sonrisa diciendo con cortesía: 'Damas y caballeros, bienvenidos a todos'."}, {"id": "#2", "hanzi": "这位享有盛誉的杰出女科学家荣获国家最高科学技术奖，成为首位获此殊荣的当代女性学者，社会各界称赞她是科学界的卓越女士。", "pinyin": "Zhè wèi xiǎngyǒu shèngyù de jiéchū nǚ kēxuéjiā rónghuò guójiā zuìgāo kējì jiǎng, chéngwéi shǒuwèi huò cǐ shūróng de dāngdài nǚxìng xuézhě, shèhuì gèjiè chēngzàn tā shì kēxuéjiè de zhuóyuè nǚshì.", "en": "This renowned female scientist won the State Preeminent Science and Technology Award, hailed by society as an outstanding lady of the scientific community.", "es": "Esta destacada científica obtuvo el máximo galardón tecnológico nacional, siendo aclamada por la sociedad como una dama insigne de la comunidad científica."}], "collocations": [{"hanzi": "女士们先生们", "en": "ladies and gentlemen"}, {"hanzi": "年轻女士", "en": "young lady"}, {"hanzi": "女士优先", "en": "ladies first"}, {"hanzi": "尊敬的女士", "en": "distinguished / respected lady"}, {"hanzi": "职业女士", "en": "career woman / professional lady"}, {"hanzi": "女士专区", "en": "ladies' exclusive section"}], "idioms": [{"hanzi": "巾帼英雄", "pinyin": "jīn guó yīng xióng", "meaning_en": "heroine; female hero of great renown"}, {"hanzi": "温文尔雅", "pinyin": "wēn wén ěr yǎ", "meaning_en": "gentle, cultivated, and refined in manner"}, {"hanzi": "贤妻良母", "pinyin": "xián qī liáng mǔ", "meaning_en": "a good wife and loving mother; model matriarch"}, {"hanzi": "大家闺秀", "pinyin": "dà jiā guī xiù", "meaning_en": "lady of noble birth; well-bred daughter of an eminent family"}], "character_decomposition": [{"character": "女", "pinyin": "nǚ", "meaning_en": "woman; female; daughter", "meaning_es": "mujer; femenino; hija", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (pictogram of kneeling graceful woman)", "sound_component": "女 (inherent female phoneme)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Oracle bone pictogram of a woman kneeling demurely with arms crossed over her lap in ancient decorum.", "visual_mnemonic_story_en": "A graceful figure (女) kneels serenely with crossed sleeves, embodying feminine grace.", "visual_mnemonic_story_es": "Una figura esbelta (女) se arrodilla con serenidad y brazos cruzados, personificando la elegancia femenina.", "tone_mnemonic_anchor": "214", "cangjie": "V", "traditional": ""}, {"character": "士", "pinyin": "shì", "meaning_en": "scholar; gentleman; warrior; cultivated person", "meaning_es": "erudito; caballero; letrado; persona culta", "radical": "士", "radical_meaning_en": "scholar / warrior", "meaning_component": "十 (ten/beginning) + 一 (one/completion)", "sound_component": "士 (inherent scholar sound)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Depicts one who knows matters from one to ten (一至十), designating an educated gentleman or scholar-warrior.", "visual_mnemonic_story_en": "A scholar stands tall with shoulders broader than the base (士), mastering knowledge.", "visual_mnemonic_story_es": "Un letrado erguido con hombros anchos (士) domina el saber desde el inicio al fin.", "tone_mnemonic_anchor": "51", "cangjie": "J", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "她是一位优雅而从容的女士，无论岁月如何在眼角留下细纹，她的眼神始终澄澈而坚定。她用温和的言语化解生活中的龃龉，用坚韧的脊梁扛起家庭的担当。这种由内而外散发的从容风度，正是当代女性最动人的风采。", "pinyin": "Tā shì yí wèi yōuyǎ ér cóngróng de nǚshì, wúlùn suìyuè rúhé zài yǎnjiǎo liúxià xìwén, tā de yǎnshén shǐzhōng chéngchè ér jiāndìng. Tā yòng wēnhé de yányǔ huàjiě shēnghuó zhōng de jǔyǔ, yòng jiānrèn de jǐliáng kángqǐ jiātíng de dāndāng. Zhè zhǒng yóunèijíwài sànfā de cóngróng fēngdù, zhèng shì dāngdài nǚxìng zuì dòngrén de fēngcǎi.", "en": "She was an elegant and serene lady; no matter the fine lines carved by time, her gaze remained limpid and firm. She dissolved disputes with gentle words and carried family duties with resilience, radiating true modern feminine grace.", "es": "Era una dama elegante y serena; por más huellas que dejaran los años, su mirada permanecía diáfana y firme. Suavizaba desavenencias con palabras amables y sostenía al hogar con firmeza, personificando la templanza contemporánea."}, {"id": "#2", "hanzi": "在联合国妇女署推动的可持续发展论坛上，多位杰出女性领袖就提高女性科技工作者话语权发表专题演讲。代表们指出，为女性科研人员消除职业晋升隐形壁垒，助力每一位卓越女士施展才华，是推动全球科技公平创新的重要基石。", "pinyin": "Zài Liánhéguó Fùnǚshǔ tuīdòng de kěchíxù fāzhǎn lùntán shàng, duō wèi jiéchū nǚxìng lǐngxiù jiù tígāo nǚxìng kējì gōngzuòzhě huàyǔquán fābiǎo zhuāntí yǎnjiǎng. Dàibiǎo men zhǐchū, wèi nǚxìng kēyán rényuán xiāochú zhíyè jìnshēng yǐnxíng bìlěi, zhùlì měi yí wèi zhuóyuè nǚshì shīzhǎn cáihuá, shì tuīdòng quánqiú kējì gōngpíng chuàngxīn de zhòngyào jīshí.", "en": "At the UN Women forum, female leaders delivered speeches on elevating female scientists' voice. Delegates stressed that dismantling career barriers and empowering ladies to display their talents constitute a cornerstone for equitable global innovation.", "es": "En el foro de ONU Mujeres, varias líderes intervinieron para fortalecer la voz de las científicas. Señalaron que derribar techos de cristal y apoyar el talento de cada dama investigadora es indispensable para la innovación equitativa global."}]}, {"meanings_summary": {"en": "to narrate; to recount; to relate; narration", "es": "narrar; relatar; contar; exponer; narración"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Arranging facts in order (叙) and tracking their path step by step (述) delivers a thorough narration (叙述).", "composite_memory_hook_es": "Ordenar los hechos en secuencia (叙) y seguir su curso paso a paso (述) logra una narración acabada (叙述).", "cultural_and_cognitive_roots": "Derived from the ancient historiographical dictum of Confucius: '述而不作，信而好古' (transmit, don't innovate; trust and love antiquity). 'Xùshù' embodies objective, faithful chronological reporting without fictional distortion.", "tone_sandhi_and_pitch_modulation": "51-51 pitch contour. Two crisp 4th tones; maintain falling contours on both syllables without slurring into a flat cadence."}, "semantic_boundary_contrasts": {"core_nuance": "叙述 focuses on sequentially setting forth the development of an event or story in an orderly, objective manner.", "contrasts": [{"id": "1", "compared_word": "叙述 vs. 描写", "pinyin": "miáoxiě", "analysis": "叙述 recounts chronological progression of events (what happened), whereas 描写 paints vivid sensory impressions, scenery, or facial expressions (how it looked)."}, {"id": "2", "compared_word": "叙述 vs. 说明", "pinyin": "shuōmíng", "analysis": "说明 explains concepts, principles, rules, or instructions, whereas 叙述 chronicles temporal sequences of incidents."}, {"id": "3", "compared_word": "叙述 vs. 议论", "pinyin": "yìlùn", "analysis": "议论 expresses viewpoints, arguments, and commentary, whereas 叙述 establishes narrative facts."}]}, "traps_and_cognates": {"look_alikes": [{"character": "斜", "pinyin": "xié", "meaning_en": "slanting; tilted", "distinction_note": "Features 斗 on the right instead of 又"}, {"character": "途", "pinyin": "tú", "meaning_en": "way; route", "distinction_note": "Features 余 inside 辶 rather than 术"}, {"character": "术", "pinyin": "shù", "meaning_en": "technique; art", "distinction_note": "Lacks the movement radical 辶"}, {"character": "述", "pinyin": "shù", "meaning_en": "recount", "distinction_note": "Headword character itself"}], "etymological_cognates": [{"character": "说", "pinyin": "shuō", "gloss_en": "speak; tell"}, {"character": "讲", "pinyin": "jiǎng", "gloss_en": "explain; lecture"}, {"character": "记", "pinyin": "jì", "gloss_en": "record; remember"}, {"character": "陈", "pinyin": "chén", "gloss_en": "lay out; state"}]}, "id": "28", "hanzi": "叙述", "pinyin": "xù shù", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to relate, recount, or describe events or a sequence of actions in oral or written form", "definition_es": "relatar o exponer acontecimientos y hechos de forma ordenada, oral o escrita", "example_phrase": "详细叙述事情经过 (recount in detail what happened)"}], "example_sentences": [{"id": "#1", "hanzi": "在警方的案情询问室里，目击证人喝了一口热水平复情绪后，开始清晰地叙述案发当晚所见到的全部情景。", "pinyin": "Zài jǐngfāng de ànqíng xùnwènshì lǐ, mùjī zhèngrén hē le yì kǒu rèshuǐ píngfù qíngxù hòu, kāishǐ qīngxī de xùshù ànfā dāngwǎn suǒ jiàndào de quánbù qíngjǐng.", "en": "In the police interrogation room, after sipping warm water to calm his nerves, the eyewitness began to clearly recount everything seen on the night of the crime.", "es": "En la sala policial, tras calmarse con un sorbo de agua tibia, el testigo comenzó a relatar con claridad todo lo que presenció la noche del suceso."}, {"id": "#2", "hanzi": "这部历史文献长卷以宏阔的叙事笔触，详尽叙述了近代工商业家族在时代巨变波澜中的创业艰辛与命运起伏。", "pinyin": "Zhè bù lìshǐ wénxiàn chángjuàn yǐ hóngkuò de xùshì bǐchù, xiángjìn xùshù le jìndài gōngshāngyè jiāzú zài shídài jùbiàn bōlán zhōng de chuàngyè jiānxīn yǔ mìngyùn qǐfú.", "en": "With an expansive narrative brush, this historical documentary volume recounts in detail the entrepreneurial hardships and vicissitudes of a modern industrial family.", "es": "Con una prosa narrativa monumental, este volumen histórico relata minuciosamente las vicisitudes y afanes de un clan empresarial frente a los grandes cambios de la época."}], "collocations": [{"hanzi": "详细叙述", "en": "recount in detail"}, {"hanzi": "简要叙述", "en": "briefly narrate / summarize"}, {"hanzi": "叙述经过", "en": "recount the process / course of events"}, {"hanzi": "叙述事实", "en": "narrate facts"}, {"hanzi": "叙述手法", "en": "narrative technique / device"}, {"hanzi": "按时间顺序叙述", "en": "narrate in chronological order"}], "idioms": [{"hanzi": "娓娓道来", "pinyin": "wěi wěi dào lái", "meaning_en": "narrate ceaselessly and charmingly; talk in an engaging flow"}, {"hanzi": "长话短说", "pinyin": "cháng huà duǎn shuō", "meaning_en": "make a long story short"}, {"hanzi": "平铺直叙", "pinyin": "píng pū zhí xù", "meaning_en": "straightforward and dull narration; tell a story without dramatic flair"}, {"hanzi": "借题发挥", "pinyin": "jiè tí fā huī", "meaning_en": "seize upon an incident or topic to air one's own views"}], "character_decomposition": [{"character": "叙", "pinyin": "xù", "meaning_en": "narrate; recount; chat; arrange in order", "meaning_es": "narrar; relatar; conversar; ordenar", "radical": "又", "radical_meaning_en": "again / hand", "meaning_component": "余 (surplus/self) + 又 (hand making marks)", "sound_component": "余 (yú, phonetic harmony)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Anciently depicted arranging building materials or genealogical lines in order (余/又), extended to sequential narration.", "visual_mnemonic_story_en": "A hand (又) neatly arranges leftover history scrolls (余) in sequence to narrate the chronicle.", "visual_mnemonic_story_es": "Una mano (又) ordena rollos históricos (余) de manera secuencial para relatar la crónica.", "tone_mnemonic_anchor": "51", "cangjie": "ODNE", "traditional": "敘"}, {"character": "述", "pinyin": "shù", "meaning_en": "recount; state; transmit; follow", "meaning_es": "relatar; exponer; transmitir; seguir", "radical": "辵", "radical_meaning_en": "walk / movement", "meaning_component": "辶 (walk/follow a path)", "sound_component": "术 (shù, technique/path)", "stroke_count": "8", "composition_type": "半包围结构", "etymology_and_mnemonic": "Depicts walking along a defined path (辶/术) transmitting ancient ancestral traditions without invention.", "visual_mnemonic_story_en": "Stepping along the road (辶) using refined art and technique (术) to relate truth.", "visual_mnemonic_story_es": "Caminar por la senda (辶) aplicando el arte de la elocuencia (术) para relatar la verdad.", "tone_mnemonic_anchor": "51", "cangjie": "YID", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "文学的魅力往往在于如何叙述时光的流逝。优秀的作家不需要浮夸的辞藻，只需用沉静克制的语言，将普通人在命运沉浮中的欢笑与泪水娓娓道来。这种真实的叙述，往往比虚构的戏剧更能震撼心灵。", "pinyin": "Wénxué de mèilì wǎngwǎng zài yú rúhé xùshù shíguāng de liúshì. Yōuxiù de zuòjiā bù xūyào fúkuā de cízǎo, zhǐ xū yòng chénjìng kèzhì de yǔyán, jiāng pǔtōngrén zài mìngyùn chénfú zhōng de huānxiào yǔ lèishuǐ wěiwěidàolái. Zhè zhǒng zhēnshí de xùshù, wǎngwǎng bǐ xūgòu de xìjù gèng néng zhènhàn xīnlíng.", "en": "The charm of literature lies in how it recounts the passage of time. Master writers need no bombast; with serene language they relate ordinary people's joy and tears amid fate's tides. Such authentic narration touches souls deeply.", "es": "El encanto de la literatura radica en cómo relata el transcurso del tiempo. Los grandes autores no precisan artificios; con lenguaje sobrio desgranan las alegrías y llantos cotidianos. Esta narración auténtica conmueve el alma con hondura."}, {"id": "#2", "hanzi": "在司法审判实践中，案件事实的客观叙述是法官准确适用法律裁判的前提。当事人陈述若出现逻辑断裂或自相矛盾，审判人员需通过多方举证质证，排除非理性情绪干扰，还原清晰可靠的案发事实链条。", "pinyin": "Zài sīfǎ shěnpàn shíjiàn zhōng, ànjiàn shìshí de kèguān xùshù shì fǎguān zhǔnquè shìyòng fǎlǜ cáipàn de qiántí. Dāngshìrén chénshù ruò chūxiàn luójí duànliè huò zìxiāngmáodùn, shěnpàn rényuán xū tōngguò duōfāng jǔzhèng zhìzhèng, páichú fēilǐxìng qíngxù gānrǎo, huányuán qīngxī kěkào de ànfā shìshí liàntiáo.", "en": "In judicial adjudication, objective narration of case facts is the prerequisite for accurate application of law. When testimonies show contradictions, judges cross-examine evidence to eliminate emotion and reconstruct facts.", "es": "En la práctica judicial, el relato objetivo de los hechos es el presupuesto indispensable para aplicar la ley con justicia. Si los testimonios incurren en contradicciones, los jueces contrastan pruebas para reconstruir la cadena fáctica verídica."}]}, {"meanings_summary": {"en": "unexpectedly; to one's surprise; actually; go so far as to", "es": "inesperadamente; para sorpresa de uno; sorprendentemente; llegar al colmo de"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Something quietly sitting in the background (居) turns out in this unexpected state (然) to everyone's amazement.", "composite_memory_hook_es": "Algo que permanecía en reposo aparente (居) se revela de este modo asombroso (然) para sorpresa de todos.", "cultural_and_cognitive_roots": "Originally conveyed 'sitting calmly in such a state' in classical prose; evolved by contrastive pragmatics to describe startling events where reality defies subjective expectation.", "tone_sandhi_and_pitch_modulation": "55-35 pitch contour. A high flat 1st tone (55) on jū steps cleanly down then rises smoothly with rán (35)."}, "semantic_boundary_contrasts": {"core_nuance": "居然 emphasizes that an event occurred completely contrary to reasonable expectation, carrying surprise, marvel, or disbelief.", "contrasts": [{"id": "1", "compared_word": "居然 vs. 竟然", "pinyin": "jìngrán", "analysis": "Both indicate surprise, but 竟然 often carries stronger emotional tone (often indignation or severe shock), whereas 居然 can convey delightful pleasant surprise or neutral amazement."}, {"id": "2", "compared_word": "居然 vs. 果然", "pinyin": "guǒrán", "analysis": "居然 is contrary to expectations (unexpected surprise), whereas 果然 indicates that reality exactly matches prior predictions (as expected)."}, {"id": "3", "compared_word": "居然 vs. 突然", "pinyin": "tūrán", "analysis": "突然 describes rapid, unexpected temporal onset ('suddenly'), whereas 居然 highlights cognitive contrast with psychological expectations."}]}, "traps_and_cognates": {"look_alikes": [{"character": "据", "pinyin": "jù", "meaning_en": "according to; basis", "distinction_note": "Has hand radical 扌 on the left instead of 居 alone"}, {"character": "剧", "pinyin": "jù", "meaning_en": "drama; fierce", "distinction_note": "Features knife radical 刂 on the right of 居"}, {"character": "燃", "pinyin": "rán", "meaning_en": "burn; ignite", "distinction_note": "Has additional fire radical 火 on the left side of 然"}, {"character": "烈", "pinyin": "liè", "meaning_en": "intense; fiery", "distinction_note": "Features 列 above 灬 instead of 肰"}], "etymological_cognates": [{"character": "竟", "pinyin": "jìng", "gloss_en": "unexpectedly; in the end"}, {"character": "竟", "pinyin": "jìng", "gloss_en": "synonym root marker"}, {"character": "俄", "pinyin": "é", "gloss_en": "suddenly; unexpectedly"}, {"character": "忽", "pinyin": "hū", "gloss_en": "suddenly; abruptly"}]}, "id": "29", "hanzi": "居然", "pinyin": "jū rán", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "expressing that something happened contrary to expectation, surprising the speaker", "definition_es": "expresa que un hecho ocurre en contra de lo esperado causando asombro", "example_phrase": "他居然考了第一名 (to everyone's surprise, he actually came in first)"}], "example_sentences": [{"id": "#1", "hanzi": "原本天气预报说今天全天都有大暴雨，没想到午后居然放晴了，天边甚至挂起了一道绚丽的彩虹。", "pinyin": "Yuánběn tiānqì yùbào shuō jīntiān quántiān dōu yǒu dà bàoyǔ, méi xiǎngdào wǔhòu jūrán fàngqíng le, tiānbiān shènzhì guàqǐ le yí dào xuànlì de cǎihóng.", "en": "The weather forecast had predicted heavy torrential downpours all day, but to our surprise it actually cleared up in the afternoon, with a gorgeous rainbow appearing.", "es": "El pronóstico del tiempo anunciaba tormentas todo el día, pero para sorpresa de todos, por la tarde escampó e incluso apareció un hermoso arcoíris."}, {"id": "#2", "hanzi": "在完全没有外部战略投资扶持的艰难处境下，这家初创人工智能企业居然在短短两年内实现了关键芯片算法的量产突破。", "pinyin": "Zài wánquán méiyǒu wàibù zhànlüè tóuzī fúchí de jiānnán chǔjìng xià, zhè jiā chūchuàng réngōng zhìnéng qǐyè jūrán zài duǎnduǎn liǎng nián nèi shíxiàn le guānjiàn xīnpiàn suànfǎ de liàngchǎn tūpò.", "en": "In the arduous situation of lacking external venture capital, this AI startup unexpectedly achieved mass-production breakthroughs in key algorithms within two years.", "es": "En medio de una difícil situación sin inversión externa, esta empresa emergente de inteligencia artificial logró sorprendentemente avances clave de producción en dos años."}], "collocations": [{"hanzi": "居然是他", "en": "unexpectedly, it was him"}, {"hanzi": "居然做到了", "en": "actually managed to achieve it"}, {"hanzi": "没想到居然", "en": "never expected that unexpectedly..."}, {"hanzi": "居然会发生", "en": "could actually happen against all odds"}, {"hanzi": "居然敢", "en": "actually have the nerve to"}, {"hanzi": "居然不知道", "en": "actually did not even know"}], "idioms": [{"hanzi": "意料之外", "pinyin": "yì liào zhī wài", "meaning_en": "beyond all expectations; completely surprising"}, {"hanzi": "出人意料", "pinyin": "chū rén yì liào", "meaning_en": "exceeding people's expectations; surprise everyone"}, {"hanzi": "安居乐业", "pinyin": "ān jū lè yè", "meaning_en": "live in peace and work happily"}, {"hanzi": "理所当然", "pinyin": "lǐ suǒ dāng rán", "meaning_en": "take it as natural; matters following natural logic"}], "character_decomposition": [{"character": "居", "pinyin": "jū", "meaning_en": "dwell; reside; occupy; sit still", "meaning_es": "residir; habitar; ocupar; estar sentado", "radical": "尸", "radical_meaning_en": "corpse / body posture", "meaning_component": "尸 (seated body posture)", "sound_component": "古 (gǔ, old/stable phonetics)", "stroke_count": "8", "composition_type": "半包围结构", "etymology_and_mnemonic": "Depicts a person resting in a settled seated position (尸) in an ancient dwelling (古), conveying resting firmly.", "visual_mnemonic_story_en": "A person rests settled inside a sheltered shelter (尸) atop ancient foundations (古).", "visual_mnemonic_story_es": "Una persona reposa instalada bajo techo (尸) sobre cimientos ancestrales (古).", "tone_mnemonic_anchor": "55", "cangjie": "SJLR", "traditional": ""}, {"character": "然", "pinyin": "rán", "meaning_en": "so; like this; suffix forming adverbs", "meaning_es": "así; de este modo; sufijo adverbial", "radical": "灬", "radical_meaning_en": "fire", "meaning_component": "灬 (fire flames burning)", "sound_component": "肰 (rán, dog meat roasted)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "Originally depicted roasting meat over fire (灬), borrowed phonetically as an adverbial suffix meaning 'in such a manner'.", "visual_mnemonic_story_en": "Flames of fire (灬) blaze brightly, demonstrating things happening visibly in this manner (然).", "visual_mnemonic_story_es": "Llamas de fuego (灬) arden vivas, mostrando con claridad que las cosas ocurren de este modo (然).", "tone_mnemonic_anchor": "35", "cangjie": "BKF", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "命运常常在不经意间峰回路转。在经历了无数次被拒之门外的沮丧后，青年在几乎放弃希望的清晨，居然收到了国际顶尖学府全额奖学金的录取通知书。那一刻，曾经流过的所有泪水，都化作了不可思议的奇迹。", "pinyin": "Mìngyùn chángcháng zài bùjīngyì jiān fēnghuílùzhuǎn. Zài jīnglì le wúshù cì bèi jù zhī ménwài de jǔsàng hòu, qīngnián zài jīhū fàngqì xīwàng de qīngchén, jūrán shōudào le guójì dǐngjiān xuéfǔ quán'é jiǎngxuéjīn de lùqǔ tōngzhīshū. Nà yí kè, céngjīng liúguò de suǒyǒu lèishuǐ, dōu huàzuò le bùkěsīyì de qíjì.", "en": "Fate often takes unexpected turns when least anticipated. After experiencing endless rejections, on a morning when he nearly surrendered hope, the youth unexpectedly received a full-scholarship admission letter, turning tears into miracles.", "es": "El destino suele dar giros asombrosos en los momentos menos previstos. Tras innumerables rechazos, cuando casi se daba por vencido, el joven recibió para su sorpresa una carta de admisión con beca completa, trocando lágrimas en un milagro."}, {"id": "#2", "hanzi": "在极度干旱贫瘠的戈壁深处，生态科考队员居然发现了一片生机勃勃的珍稀濒危灌木群落。依托深层地下水脉的微循环补给，这片绿洲在极端气候中顽强存续了数百年，为全球荒漠化治理研究提供了不可多得的生态样本。", "pinyin": "Zài jídù gānhàn pínjí de gēbì shēnchù, shēngtài kěkǎo duìyuán jūrán fāxiàn le yí piàn shēngjībóbó de zhēnxī bīnwēi guānmù qúnluò. Yītuō shēncéng dìxiàshuǐ mài de wēi xúnhuán bǔjǐ, zhè piàn lǜzhōu zài jíduān qìhòu zhōng wánqiáng cúnxù le shù bǎi nián, wèi quánqiú huāngmòhuà zhìlǐ yánjiū tígōng le bùkěduōdé de shēngtài yàngběn.", "en": "Deep in the arid Gobi, ecological researchers surprisingly discovered a thriving community of endangered shrubs. Sustained by deep aquifer micro-cycles, this oasis endured extreme climate for centuries, offering an invaluable sample for desertification studies.", "es": "En las profundidades del desierto árido, los ecólogos descubrieron sorprendentemente una comunidad viva de arbustos en peligro de extinción. Nutridos por corrientes subterráneas, este oasis pervivió siglos aportando un modelo clave contra la desertificación."}]}, {"meanings_summary": {"en": "to urge; to hurry; to press; to hasten; to prompt", "es": "apurar; apremiar; apresurar; urgir; instar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A person (亻) pushing you up a towering, precipitous mountain (崔) embodies being hurried and urged forward (催).", "composite_memory_hook_es": "Una persona (亻) que te empuja a subir una montaña empinada (崔) representa estar siendo apurado y apremiado (催).", "cultural_and_cognitive_roots": "Associated in Chinese poetry with seasonal urgency ('春风催新绿', spring breezes prompt fresh green) as well as the urgency of official tax collectors or military drums driving soldiers into battle.", "tone_sandhi_and_pitch_modulation": "55 pitch contour. A high, steady 1st tone (55); keep the onset crisp and sustained without dipping."}, "semantic_boundary_contrasts": {"core_nuance": "催 focuses on verbally or operationally pressing someone to accelerate their pace and finish promptly.", "contrasts": [{"id": "1", "compared_word": "催 vs. 赶", "pinyin": "gǎn", "analysis": "赶 focuses on accelerating one's own physical movement to catch a vehicle or meet a deadline (e.g., 赶时间, 赶火车), whereas 催 is transitive, pressing another person to act faster."}, {"id": "2", "compared_word": "催 vs. 促", "pinyin": "cù", "analysis": "促 is more formal/written, denoting facilitating or catalyzing broad trends (e.g., 促进, 督促), whereas 催 is direct spoken prompting (e.g., 催促, 别催了)."}, {"id": "3", "compared_word": "催 vs. 逼", "pinyin": "bī", "analysis": "逼 implies coercive intimidation, cornering, or extortion without choice, whereas 催 is urging speed and timeliness."}]}, "traps_and_cognates": {"look_alikes": [{"character": "璀", "pinyin": "cuǐ", "meaning_en": "resplendent; luster of jade", "distinction_note": "Features jade radical 王 on the left instead of person 亻"}, {"character": "摧", "pinyin": "cuī", "meaning_en": "destroy; break", "distinction_note": "Features hand radical 扌 on the left instead of person 亻"}, {"character": "崔", "pinyin": "cuī", "meaning_en": "lofty mountain; surname", "distinction_note": "The phonetic stem without the left person radical 亻"}, {"character": "维", "pinyin": "wéi", "meaning_en": "maintain; dimension", "distinction_note": "Has silk radical 纟 on the left instead of person 亻"}], "etymological_cognates": [{"character": "赶", "pinyin": "gǎn", "gloss_en": "rush; hurry"}, {"character": "督", "pinyin": "dū", "gloss_en": "supervise; urge forward"}, {"character": "迫", "pinyin": "pò", "gloss_en": "compel; press"}, {"character": "促", "pinyin": "cù", "gloss_en": "hasten; promote"}]}, "id": "30", "hanzi": "催", "pinyin": "cuī", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to urge or press someone to act or finish something faster", "definition_es": "apremiar o instar a alguien a actuar o completar una tarea con prisa", "example_phrase": "催他快走 (urge him to hurry up)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to hasten, induce, or stimulate a natural or chemical process", "definition_es": "acelerar o inducir un proceso biológico o químico", "example_phrase": "催熟水果 (ripen fruits artificially)"}], "example_sentences": [{"id": "#1", "hanzi": "眼看校车马上就要到小区门口了，妈妈站在玄关一边帮弟弟整理书包，一边不停催他快点穿鞋。", "pinyin": "Yǎnkàn xiàochē mǎshàng jiù yào dào xiǎoqū ménkǒu le, māma zhàn zài xuánguān yìbiān bāng dìdi zhěnglǐ shūbāo, yìbiān bùtíng cuī tā kuài diǎn chuān xié.", "en": "Seeing that the school bus was arriving at the neighborhood gate, mother stood by the foyer helping brother pack his bag while constantly urging him to put on his shoes.", "es": "Al ver que el autobús escolar casi llegaba a la puerta, mamá ayudaba a mi hermano con la mochila en el recibidor mientras le apuraba sin parar para que se calzara."}, {"id": "#2", "hanzi": "面对供应链核心零部件交货延期风险，项目总监亲自向主要供应商派出督导组，现场催促产能释放并紧盯交付节点。", "pinyin": "Miànduì gōngyìngliàn héxīn língbùjiàn jiāohuò yánqī fēngxiǎn, xiàngmù zǒngjiān qīnzì xiàng zhǔyào gōngyìngshāng pàichū dūdǎozǔ, xiànchǎng cuīcù chǎnnéng shìfàng bìng jǐndīng jiāofù jiédiǎn.", "en": "Facing delivery delay risks for critical supply chain parts, the project director dispatched a supervisor team to suppliers to urge capacity ramp-up and track delivery milestones.", "es": "Ante el riesgo de demora en componentes clave, el director del proyecto envió supervisores a los proveedores para apremiar la producción y asegurar los plazos."}], "collocations": [{"hanzi": "催促进度", "en": "urge progress on a schedule"}, {"hanzi": "催交作业", "en": "press to submit homework"}, {"hanzi": "催款", "en": "press for payment of debts"}, {"hanzi": "催眠", "en": "hypnotize; induce sleep"}, {"hanzi": "催熟", "en": "accelerate ripening"}, {"hanzi": "催人奋进", "en": "urge people onward to strive"}], "idioms": [{"hanzi": "催人泪下", "pinyin": "cuī rén lèi xià", "meaning_en": "moving one to tears; poignant and tear-inducing"}, {"hanzi": "羯鼓催花", "pinyin": "jié gǔ cuī huā", "meaning_en": "beating drums to hasten flower blossoms; eager impatience"}, {"hanzi": "星夜兼程", "pinyin": "xīng yè jiān chéng", "meaning_en": "travel night and day by star light; hurry through journey"}, {"hanzi": "雷厉风行", "pinyin": "léi lì fēng xíng", "meaning_en": "vigorously and swiftly as thunder and wind"}], "character_decomposition": [{"character": "催", "pinyin": "cuī", "meaning_en": "urge; press; hurry; hasten", "meaning_es": "apurar; apremiar; apresurar; instar", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person prodding/urging)", "sound_component": "崔 (cuī, steep high mountain)", "stroke_count": "13", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character pairing person (亻) with steep crag (崔), conveying pressing someone forward as if climbing a steep slope.", "visual_mnemonic_story_en": "A guide (亻) urgently prods climbers up a steep mountain crag (崔) before sunset.", "visual_mnemonic_story_es": "Un guía (亻) apremia a los montañistas para que asciendan el risco escarpado (崔) antes del anochecer.", "tone_mnemonic_anchor": "55", "cangjie": "OUOG", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "生活总是催促着人们匆匆赶路，早晨急促的闹钟，地铁里拥挤的脚步，都在无声地催促着我们向前奔跑。然而，偶尔放慢脚步，听听路边清脆的鸟鸣，看看花开的姿态，才能让疲惫的灵魂重新找回宁静的归宿。", "pinyin": "Shēnghuó zǒngshì cuīcù zhe rénmen cōngcōng gǎnlù, zǎochen jícù de nàozhōng, dìtiě lǐ yōngjǐ de jiǎobù, dōu zài wúshēng de cuīcù zhe wǒmen xiàngqián bēnpǎo. Rán'ér, ǒu'ěr fàngmàn jiǎobù, tīngting lùbiān qīngcuì de niǎomíng, kànkan huākāi de zītài, cáinǐng ràng píbèi de línghún chóngxīn zhǎohuí níngjìng de guīsù.", "en": "Life constantly urges people onward in haste: buzzing alarm clocks and rushed subway steps push us forward silently. Yet slowing down occasionally to hear birds chirping and view flowers allows weary souls to reclaim peaceful havens.", "es": "La vida nos apremia a correr deprisa: el despertador matutino y los pasos apresurados en el metro nos empujan en silencio. Sin embargo, frenar el paso para escuchar el canto de las aves y contemplar las flores devuelve la paz al alma fatigada."}, {"id": "#2", "hanzi": "在现代敏捷项目开发流程中，项目经理通过看板系统实时监控研发瓶颈。当某一核心功能模块出现交付滞后风险时，项目组需及时组织跨部门资源会商，通过梳理阻塞节点替代盲目催促进度，以确保系统按期高质量交付。", "pinyin": "Zài xiàndài mǐnjié xiàngmù kāifā liúchéng zhōng, xiàngmù jīnglǐ tōngguò kànbǎn xìtǒng shíshí jiānkòng yánfā píngjǐng. Dāng mǒu yí héxīn gōngnéng mókuài chūxiàn jiāofù zhìhòu fēngxiǎn shí, xiàngmùzǔ xū jíshí zǔzhī kuà bùmén zīyuán huìshāng, tōngguò shūlǐ zǔsè jiédiǎn tìdài mángmù cuīcù jìndù, yǐ quèbǎo xìtǒng ànqī gāozhìliàng jiāofù.", "en": "In agile development workflows, project managers monitor bottlenecks via Kanban systems. When module delays arise, teams coordinate cross-functional resources to unblock bottlenecks rather than blindly rushing schedules, ensuring quality.", "es": "En el desarrollo ágil de proyectos, los directores supervisan cuellos de botella con tableros Kanban. Al surgir retrasos en módulos clave, se coordinan recursos para despejar trabas en vez de apremiar a ciegas, asegurando entregas de calidad."}]}, {"meanings_summary": {"en": "to wait for; to await; wait; expectation", "es": "esperar; aguardar; espera; expectativa"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Halting with bamboo tallies (等) and pausing your steps (待) to let time unfold creates patient waiting.", "composite_memory_hook_es": "Contar los días como varillas (等) y frenar el paso (待) para dar tiempo al tiempo constituye la serena espera.", "cultural_and_cognitive_roots": "Both characters share the courtly/temple root '寺' (sì); ancient Chinese view of waiting was not passive paralysis but disciplined temporal incubation ('待时而动', biding one's time until heaven's moment arrives).", "tone_sandhi_and_pitch_modulation": "214-51 contour. The 3rd tone of děng is pronounced as a half-3rd tone (21 low) before the crisp falling 4th tone of dài (51)."}, "semantic_boundary_contrasts": {"core_nuance": "等待 denotes spending time in a steady state anticipation of an event, person, or result to materialize.", "contrasts": [{"id": "1", "compared_word": "等待 vs. 等候", "pinyin": "děnghòu", "analysis": "等候 is more specific to physical waiting in a dedicated area (e.g., 在候车室等候), whereas 等待 encompasses deep psychological and temporal anticipation (e.g., 等待时机, 等待奇迹)."}, {"id": "2", "compared_word": "等待 vs. 期盼", "pinyin": "qīpàn", "analysis": "期盼 emphasizes strong yearning and subjective eagerness, whereas 等待 is an objective state of passing time."}, {"id": "3", "compared_word": "等待 vs. 逗留", "pinyin": "dòuliú", "analysis": "逗留 means staying or lingering at a geographic destination during travel, unrelated to expecting future results."}]}, "traps_and_cognates": {"look_alikes": [{"character": "持", "pinyin": "chí", "meaning_en": "hold; grasp", "distinction_note": "Features hand radical 扌 on the left instead of step 彳"}, {"character": "特", "pinyin": "tè", "meaning_en": "special", "distinction_note": "Features ox radical 牛 on the left instead of step 彳"}, {"character": "诗", "pinyin": "shī", "meaning_en": "poetry; verse", "distinction_note": "Features speech radical 讠 on the left with 寺"}, {"character": "符", "pinyin": "fú", "meaning_en": "tally; symbol", "distinction_note": "Features bamboo radical 竹 over 付 instead of 寺"}], "etymological_cognates": [{"character": "候", "pinyin": "hòu", "gloss_en": "wait; expect season"}, {"character": "盼", "pinyin": "pàn", "gloss_en": "long for; look expectantly"}, {"character": "停", "pinyin": "tíng", "gloss_en": "stop; halt steps"}, {"character": "守", "pinyin": "shǒu", "gloss_en": "guard; keep watch"}]}, "id": "31", "hanzi": "等待", "pinyin": "děng dài", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to stay in a place or state expecting a person, event, or condition to occur", "definition_es": "permanecer a la espera de que ocurra una persona, acontecimiento o estado", "example_phrase": "耐心等待 (wait patiently)"}], "example_sentences": [{"id": "#1", "hanzi": "在漫天飘雪的冬夜，母亲站在老屋檐下，搓着冰凉的双手，静静等待着远方归家的游子。", "pinyin": "Zài màntiān piāoxuě de dōngyè, mǔqīn zhàn zài lǎo wūyán xià, cuō zhe bīngliáng de shuāngshǒu, jìngjìng děngdài zhe yuǎnfāng guījiā de yóuzǐ.", "en": "On a winter night with snowflakes swirling through the sky, mother stood under the old eaves, rubbing cold hands, quietly waiting for her traveler returning home from afar.", "es": "En una noche invernal bajo la nieve, la madre aguardaba bajo el alero de la casa, frotándose las manos frías mientras esperaba al hijo que volvía del lejano hogar."}, {"id": "#2", "hanzi": "经过长达八个月的临床试验数据审评，创新抗癌靶向药物研发团队终于拿到了国家药品监督管理局批准上市的决定，结束了漫长焦灼的等待。", "pinyin": "Jīngguò chángdá bā gè yuè de línchuáng shíyàn shùjù shěnpíng, chuàngxīn kàng'ái bǎxiàng yàowù yánfā tuánduì zhōngyú ná dào le Guójiā Yàopǐn Jiāndǔ Guǎnlǐjú pīzhǔn shàngshì de juédìng, jiéshù le màncháng jiāozhuó de děngdài.", "en": "After eight months of clinical trial data evaluation, the innovative targeted cancer drug R&D team finally received the marketing approval decision from the medical administration, ending their long and anxious wait.", "es": "Tras ocho meses de rigurosa evaluación de datos clínicos, el equipo del fármaco oncológico obtuvo por fin la autorización oficial de comercialización, concluyendo una prolongada y tensa espera."}], "collocations": [{"hanzi": "耐心等待", "en": "wait patiently"}, {"hanzi": "漫长等待", "en": "long wait"}, {"hanzi": "焦急等待", "en": "wait anxiously"}, {"hanzi": "等待时机", "en": "await an opportune moment"}, {"hanzi": "等待结果", "en": "wait for the result"}, {"hanzi": "静静等待", "en": "wait in quiet silence"}], "idioms": [{"hanzi": "拭目以待", "pinyin": "shì mù yǐ dài", "meaning_en": "wipe one's eyes and wait; wait and see with high anticipation"}, {"hanzi": "严阵以待", "pinyin": "yán zhèn yǐ dài", "meaning_en": "stand in battle array awaiting the enemy; ready for action"}, {"hanzi": "守株待兔", "pinyin": "shǒu zhū dài tù", "meaning_en": "stand by a tree stump waiting for rabbits; wait idly for windfalls"}, {"hanzi": "翘首以待", "pinyin": "qiáo shǒu yǐ dài", "meaning_en": "crane one's neck in eager anticipation"}], "character_decomposition": [{"character": "等", "pinyin": "děng", "meaning_en": "wait; equal; rank; class", "meaning_es": "esperar; igual; rango; clase", "radical": "竹", "radical_meaning_en": "bamboo", "meaning_component": "竹 (bamboo slats for ranking/weighing)", "sound_component": "寺 (sì, temple/official court)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic character pairing bamboo tallies (竹) with imperial office (寺), anciently denoting classifying equal ranks on tallies, extended to pausing/waiting.", "visual_mnemonic_story_en": "Bamboo measurement slips (竹) are stacked in the hall (寺) until records are verified.", "visual_mnemonic_story_es": "Varillas de bambú (竹) aguardan apiladas en el tribunal (寺) hasta certificar los registros.", "tone_mnemonic_anchor": "214", "cangjie": "HGDI", "traditional": ""}, {"character": "待", "pinyin": "dài", "meaning_en": "wait; treat; stay; about to", "meaning_es": "esperar; aguardar; tratar; quedarse", "radical": "彳", "radical_meaning_en": "step / walk slowly", "meaning_component": "彳 (step pausing on road)", "sound_component": "寺 (sì, court/stopping point)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts halting one's steps (彳) at an official post (寺) awaiting orders.", "visual_mnemonic_story_en": "Halting footsteps (彳) outside the sanctuary gate (寺) to wait patiently for arrival.", "visual_mnemonic_story_es": "Detener el paso (彳) ante el umbral (寺) para esperar pacientemente la llegada.", "tone_mnemonic_anchor": "51", "cangjie": "HOGDI", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "生命中许多美好的事物，都值得我们耐心地等待。春天的花开，秋天的硕果，都需要经过风霜雨雪的漫长孕育。学会学会在浮躁的尘世中平静等待，不是消极怠工，而是在时光深处积蓄破土而出的蓬勃生机。", "pinyin": "Shēngmìng zhōng xǔduō měihǎo de shìwù, dōu zhídé wǒmen nàixīn de děngdài. Chūntiān de huākāi, qiūtiān de shuòguǒ, dōu xūyào jīngguò fēngshuāngyǔxuě de màncháng yùnyù. Xuéhuì zài fúzào de chénshì zhōng píngjìng děngdài, bú shì xiāojí dàigōng, érshì zài shíguāng shēnchù jīxù pòtǔ'érchū de péngbó shēngjī.", "en": "Many wonders of life are worth waiting for patiently. Spring flowers and autumn fruit demand long maturation through wind and frost. Learning to wait with serenity amidst turmoil is not passive surrender, but gathering vitality to burst forth.", "es": "Muchas maravillas de la vida merecen una paciente espera. Las flores primaverales y los frutos de otoño maduran tras largos fríos. Aprender a aguardar con serenidad no es pasividad, sino acumular la fuerza vital necesaria para brotar."}, {"id": "#2", "hanzi": "在现代宏观经济资本运作与长周期产业投资领域，秉持耐心资本理念是穿越行业周期的关键。面对底层硬核技术的漫长研发周期，投资机构唯有经得起时间等待，摒弃短期投机套利冲动，才能分享战略产业自主创新的丰厚红利。", "pinyin": "Zài xiàndài hóngguān jīngjì zīběn yùnzuò yǔ chángzhōuqī chǎnyè tóuzī lǐngyù, bǐngchí nàixīn zīběn lǐniàn shì chuānyuè hángyè zhōuqī de guānjiàn. Miànduì dǐcéng yìnghé jìshù de màncháng yánfā zhōuqī, tóuzī jīgòu wéiyǒu jīngdéqǐ shíjiān děngdài, bìngqì duǎnqī tóujī tàolì chōngdòng, cáinǐng fēnxiǎng zhànlüè chǎnyè zìzhǔ chuàngxīn de fēnghòu hónglì.", "en": "In long-cycle industrial investment, patient capital philosophy is vital to traversing economic cycles. Facing lengthy R&D timelines for foundational technology, investors who endure the wait and reject speculation reap innovation dividends.", "es": "En la inversión industrial a largo plazo, el capital paciente permite atravesar los ciclos económicos. Frente a la prolongada gestación de las tecnologías de base, los inversores capaces de esperar sin especular cosechan los frutos de la innovación."}]}, {"meanings_summary": {"en": "mosquito; biting gnat", "es": "mosquito; zancudo"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The humming insect (蚊) with the standard noun suffix (子) forms the pesky mosquito.", "composite_memory_hook_es": "El insecto zumbador (蚊) con el sufijo de sustantivo (子) forma la palabra mosquito.", "cultural_and_cognitive_roots": "Symbol of annoying, disruptive trifles in classical poetry; the idiom '聚蚊成雷' warns that tiny pests humming together can generate the roar of thunder, metaphor for the dangerous accumulation of minor slander.", "tone_sandhi_and_pitch_modulation": "35-214 contour. In everyday spoken Chinese, 子 is universally reduced to a light neutral tone: wénzi (35-neutral)."}, "semantic_boundary_contrasts": {"core_nuance": "蚊子 refers specifically and biologically to mosquitoes (Culicidae family) that suck blood and hum loudly.", "contrasts": [{"id": "1", "compared_word": "蚊子 vs. 苍蝇", "pinyin": "cāngying", "analysis": "蚊子 sucks blood with piercing mouthparts and makes a high-pitched hum at night, whereas 苍蝇 is a filth-feeding fly that spreads digestive pathogens during daytime."}, {"id": "2", "compared_word": "蚊子 vs. 飞蛾", "pinyin": "fēi'é", "analysis": "飞蛾 is a nocturnal powdery moth attracted to flames, harmless to human skin, unlike blood-biting 蚊子."}, {"id": "3", "compared_word": "蚊子 vs. 蜜蜂", "pinyin": "mìfēng", "analysis": "蜜蜂 is a beneficial honeybee that stings defensively when provoked, unlike parasitic mosquitoes that feed on human blood."}]}, "traps_and_cognates": {"look_alikes": [{"character": "纹", "pinyin": "wén", "meaning_en": "pattern; grain", "distinction_note": "Features silk radical 纟 on the left instead of insect 虫"}, {"character": "蚊", "pinyin": "wén", "meaning_en": "mosquito", "distinction_note": "Headword character with insect radical 虫"}, {"character": "蛇", "pinyin": "shé", "meaning_en": "snake", "distinction_note": "Right side is 它 rather than 文"}, {"character": "蜂", "pinyin": "fēng", "meaning_en": "bee; wasp", "distinction_note": "Right side is 夆 rather than 文"}], "etymological_cognates": [{"character": "蝇", "pinyin": "yíng", "gloss_en": "housefly in the 虫 radical system"}, {"character": "蛾", "pinyin": "é", "gloss_en": "moth"}, {"character": "蝉", "pinyin": "chán", "gloss_en": "cicada"}, {"character": "蝶", "pinyin": "dié", "gloss_en": "butterfly"}]}, "id": "32", "hanzi": "蚊子", "pinyin": "wén zi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a small slender dipteran insect with piercing mouthparts, the female of which bites and sucks blood", "definition_es": "insecto díptero pequeño de piezas bucales punzantes cuya hembra pica para succionar sangre", "example_phrase": "消灭蚊子 (eradicate mosquitoes)"}], "example_sentences": [{"id": "#1", "hanzi": "夏天夜里在院子里乘凉时，如果不点燃盘装蚊香或喷洒防蚊花露水，手臂上很容易被可恶的蚊子叮出好几个红肿的大包。", "pinyin": "Xiàtiān yèlǐ zài yuànzi lǐ chéngliáng shí, rúguǒ bù diǎnrán pánzhuāng wénxiāng huò pēnsǎ fángwén huālùshuǐ, shǒubì shàng hěn róngyì bèi kě'wù de wénzi dīng chū hǎojǐ gè hóngzhǒng de dàbāo.", "en": "When enjoying the cool evening in the courtyard during summer, unless one lights a mosquito coil or sprays repellent, arms easily get bitten by pesky mosquitoes into red swollen welts.", "es": "Al tomar el fresco nocturno en el patio durante el verano, si no se enciende repelente o espirales, los molestos mosquitos acaban acribillando los brazos de ronchas rojas."}, {"id": "#2", "hanzi": "热带公共卫生疾病控制专家多次警告，伊蚊等特定种类的蚊子是登革热、疟疾和寨卡病毒等急性传染病跨区域扩散的关键媒介。", "pinyin": "Rèdài gōnggòng wèishēng jíbìng kòngzhì zhuānjiā duō cì jǐnggào, yīwén děng tèdìng zhǒnglèi de wénzi shì dēnggérè, nüèjí hé zhàikǎ bìngdú děng jíxìng chuánrǎnbìng kuà qūyù kuòsàn de guānjiàn méijiè.", "en": "Tropical public health disease control experts have repeatedly warned that specific mosquito species like Aedes are crucial vectors spreading acute infectious diseases such as dengue, malaria, and Zika.", "es": "Expertos en salud pública advierten de que ciertas especies de mosquitos como el Aedes son vectores biológicos clave en la propagación de enfermedades como el dengue, la malaria y el zika."}], "collocations": [{"hanzi": "蚊子叮咬", "en": "mosquito bites"}, {"hanzi": "驱赶蚊子", "en": "repel / drive away mosquitoes"}, {"hanzi": "消灭蚊子", "en": "exterminate mosquitoes"}, {"hanzi": "蚊子幼虫", "en": "mosquito larvae / wrigglers"}, {"hanzi": "蚊子叫声", "en": "whining / buzzing of mosquitoes"}, {"hanzi": "招蚊子", "en": "attract mosquitoes"}], "idioms": [{"hanzi": "聚蚊成雷", "pinyin": "jù wén chéng léi", "meaning_en": "a swarm of mosquitoes buzzing like thunder; small slanders growing into formidable harm"}, {"hanzi": "秋蚊见血", "pinyin": "qiū wén jiàn xiè", "meaning_en": "autumn mosquitoes thirsty for blood; fierce desperation before death"}, {"hanzi": "蝇营狗苟", "pinyin": "yíng yíng gǒu gǒu", "meaning_en": "scurrying like flies and creeping like dogs; shamelessly chasing personal gain"}, {"hanzi": "蛛丝马迹", "pinyin": "zhū sī mǎ jì", "meaning_en": "spider web and horse tracks; faint clues"}], "character_decomposition": [{"character": "蚊", "pinyin": "wén", "meaning_en": "mosquito; gnat", "meaning_es": "mosquito; zancudo", "radical": "虫", "radical_meaning_en": "insect / bug", "meaning_component": "虫 (insect radical)", "sound_component": "文 (wén, pattern/humming vibration)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character combining insect (虫) with 文 (wén), imitating the fine high-pitched humming drone of mosquito wings.", "visual_mnemonic_story_en": "An annoying insect (虫) flies around writing invisible patterns in the air with a humming drone (文).", "visual_mnemonic_story_es": "Un insecto molesto (虫) traza dibujos invisibles en el aire con un zumbido agudo (文).", "tone_mnemonic_anchor": "35", "cangjie": "LIYK", "traditional": ""}, {"character": "子", "pinyin": "zi", "meaning_en": "noun suffix; child; son", "meaning_es": "sufijo nominal; niño; hijo", "radical": "子", "radical_meaning_en": "child", "meaning_component": "子 (infant/nominal affix)", "sound_component": "子 (inherent phoneme)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Pictogram of an infant with outstretched arms, widely utilized in vernacular Chinese as a common nominalizing noun suffix.", "visual_mnemonic_story_en": "A small child (子) swaddled up, functioning as the ubiquitous Chinese noun particle.", "visual_mnemonic_story_es": "Un infante (子) envuelto en mantas, usado como el sufijo de sustantivo más común del idioma.", "tone_mnemonic_anchor": "214", "cangjie": "ND", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "童年的盛夏夜里，庭院中摇曳的蒲扇是抵挡蚊子最好的盾牌。微风吹散了白昼的暑气，耳边偶尔响起蚊子微弱的嗡嗡声，却很快在漫天繁星与阵阵蛙鸣中远去。那一缕艾草蚊香的清香，是故乡最悠长的夏夜记忆。", "pinyin": "Tóngnián de shèngxià yèlǐ, tíngyuàn zhōng yáoyè de púshàn shì dǐdǎng wénzi zuì hǎo de dùnpái. Wēifēng chuīsàn le báizhòu de shǔqì, ěrbiān ǒu'ěr xiǎngqǐ wénzi wēiruò de wēngwēng shēng, què hěn kuài zài màntiān fánxīng yǔ zhènzhèn wāmíng zhōng yuǎnqù. Nà yì lǚ àicǎo wénxiāng de qīngxiāng, shì gùxiāng zuì yōucháng de xiàyè jìyì.", "en": "On summer nights of childhood, swaying cattail fans were our best shield against mosquitoes. Breezes cooled the day's heat; faint buzzing in our ears soon receded into starlight and croaking frogs. The scent of mugwort incense is my deepest memory.", "es": "En las noches infantiles de verano, el abanico de paja era el mejor escudo contra los zancudos. La brisa disipaba el bochorno y el zumbido de los mosquitos se perdía entre estrellas y ranas. El aroma a incienso de artemisa es el recuerdo más dulce de mi tierra."}, {"id": "#2", "hanzi": "在现代生物技术防蚊治理前沿，科研团队正在利用基因驱动技术对野生蚊子种群实施精准干预。通过向自然界释放不育雄蚊阻断虫媒交配链条，能够在不破坏食物链生态平衡的前提下，大幅压低登革热与黄热病在城市的暴发风险。", "pinyin": "Zài xiàndài shēngwù jìshù fángwén zhìlǐ qiányán, kēyán tuánduì zhèngzài lìyòng jīyīn qūdòng jìshù duì yěshēng wénzi zhǒngqún shíshī jīngzhǔn gānyù. Tōngguò xiàng zìránjiè shìfàng bùyù xióngwén zǔduàn chóngméi jiāopèi liàntiáo, nénggòu zài bù pòhuài shíwùliàn shēngtài pínghéng de qiántí xià, dàfú yādī dēnggérè yǔ huángrèbìng zài chéngshì de bàofā fēngxiǎn.", "en": "At the forefront of biotechnology mosquito control, scientists utilize gene drives to intervene in wild mosquito populations. Releasing sterile males disrupts reproduction, suppressing dengue and yellow fever risks without disrupting food chains.", "es": "En la biotecnología contra insectos transmisores, los científicos aplican impulsos genéticos a poblaciones silvestres de mosquitos. Liberar machos estériles corta la reproducción y reduce el riesgo de dengue y fiebre amarilla sin alterar el ecosistema."}]}, {"meanings_summary": {"en": "midnight; middle of the night; late at night", "es": "medianoche; altas horas de la noche; en plena noche"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Reaching the exact midpoint (半) of the dark night (夜) marks midnight (半夜).", "composite_memory_hook_es": "Llegar a la mitad exacta (半) de la noche oscura (夜) define la medianoche (半夜).", "cultural_and_cognitive_roots": "Linked to the ancient Chinese system of five night watches ('五更'); the third watch ('三更', 23:00 to 01:00) sits at the balance of Yin and Yang, designated colloquially as 'bànyè' (half of the night).", "tone_sandhi_and_pitch_modulation": "51-51 pitch contour. Two consecutive crisp falling 4th tones; articulate both syllables distinctly."}, "semantic_boundary_contrasts": {"core_nuance": "半夜 refers specifically to the middle of the night, around or after midnight, usually between 23:00 and 03:00.", "contrasts": [{"id": "1", "compared_word": "半夜 vs. 午夜", "pinyin": "wǔyè", "analysis": "午夜 is a formal, precise, or literary chronological point marking 24:00/00:00, whereas 半夜 is a broader colloquial time window describing the deep of the night."}, {"id": "2", "compared_word": "半夜 vs. 晚上", "pinyin": "wǎnshang", "analysis": "晚上 covers the entire evening from sunset to bedtime (typically 18:00 to 22:00), while 半夜 begins after most people have fallen asleep."}, {"id": "3", "compared_word": "半夜 vs. 黎明", "pinyin": "límíng", "analysis": "黎明 marks the crack of dawn right before sunrise, the direct temporal successor to the dead of night."}]}, "traps_and_cognates": {"look_alikes": [{"character": "伴", "pinyin": "bàn", "meaning_en": "companion; partner", "distinction_note": "Features person radical 亻 on the left instead of 半 alone"}, {"character": "拌", "pinyin": "bàn", "meaning_en": "mix; stir", "distinction_note": "Features hand radical 扌 on the left instead of 半 alone"}, {"character": "变", "pinyin": "biàn", "meaning_en": "change", "distinction_note": "Top component is 亦 with dots; bottom is 又"}, {"character": "夕", "pinyin": "xī", "meaning_en": "evening; dusk", "distinction_note": "Radical component itself inside 夜"}], "etymological_cognates": [{"character": "晚", "pinyin": "wǎn", "gloss_en": "evening; late"}, {"character": "昏", "pinyin": "hūn", "gloss_en": "dusk; twilight"}, {"character": "宵", "pinyin": "xiāo", "gloss_en": "night; night watch"}, {"character": "暮", "pinyin": "mù", "gloss_en": "sunset; dusk"}]}, "id": "33", "hanzi": "半夜", "pinyin": "bàn yè", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the middle period of the night, around or after midnight", "definition_es": "el periodo central de la noche, alrededor o pasada la medianoche", "example_phrase": "半夜醒来 (wake up in the middle of the night)"}], "example_sentences": [{"id": "#1", "hanzi": "昨天半夜突然狂风大作，窗外电闪雷鸣，暴雨敲打着窗玻璃，把熟睡中的全家人都惊醒了。", "pinyin": "Zuótiān bànyè tūrán kuángfēng dàzuò, chuāngwài diànshǎnléimíng, bàoyǔ qiāodǎ zhe chuāngbōlí, bǎ shúshuì zhōng de quánjiā rén dōu jīngxǐng le.", "en": "Wild winds suddenly blew in the middle of the night yesterday with lightning and thunder, torrential rain hammering the windowpanes and startling the whole sleeping family awake.", "es": "Ayer a medianoche se desató un vendaval con truenos y relámpagos, y la lluvia torrencial azotó los cristales despertando a toda la familia de su sueño."}, {"id": "#2", "hanzi": "由于系统服务器集群在半夜遭遇异常网络流量冲击，技术值班团队紧急响应，历经三小时通宵排查修复了核心链路。", "pinyin": "Yóuyú xìtǒng fúwùqì jíqún zài bànyè zāoyù yìcháng wǎngluò liúliàng chōngjī, jìshù zhíbān tuánduì jǐnjí xiǎngyìng, lìjīng sān xiǎoshí tōngxiāo páichá xiūfù le héxīn liànlù.", "en": "Because server clusters were hit by abnormal network traffic surges in the middle of the night, on-duty tech staff responded swiftly, troubleshooting overnight to restore links.", "es": "Debido a una sobrecarga de tráfico anómala en los servidores a medianoche, el equipo técnico de guardia actuó de urgencia reparando los enlaces críticos tras horas de desvelo."}], "collocations": [{"hanzi": "半夜三更", "en": "in the dead of night / middle of the night"}, {"hanzi": "深更半夜", "en": "deep in the dead of night"}, {"hanzi": "半夜醒来", "en": "wake up in the middle of the night"}, {"hanzi": "大半夜", "en": "late at night; wee hours"}, {"hanzi": "半夜敲门", "en": "knock on the door at midnight"}, {"hanzi": "半夜起床", "en": "get up in the middle of the night"}], "idioms": [{"hanzi": "夜以继日", "pinyin": "yè yǐ jì rì", "meaning_en": "day and night without cease; working round the clock"}, {"hanzi": "深更半夜", "pinyin": "shēn gēng bàn yè", "meaning_en": "the small hours of the morning; the dead of night"}, {"hanzi": "半夜三更", "pinyin": "bàn yè sān gēng", "meaning_en": "the third watch of the night; in the deep of the night"}, {"hanzi": "风雨交加", "pinyin": "fēng yǔ jiāo jiā", "meaning_en": "wind and rain accompanied by thunder; severe nighttime storm"}], "character_decomposition": [{"character": "半", "pinyin": "bàn", "meaning_en": "half; semi-; partly", "meaning_es": "mitad; medio; a medias", "radical": "十", "radical_meaning_en": "ten", "meaning_component": "八 (divide in two) + 牛 (ox halved)", "sound_component": "半 (inherent phoneme)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "Anciently depicted cleaving an ox (牛) down the middle into two symmetrical halves (八).", "visual_mnemonic_story_en": "A central stroke cuts directly down through an animal carcass (十/八) into two equal halves.", "visual_mnemonic_story_es": "Un trazo vertical divide en dos mitades exactas (十/八) el cuerpo para compartirlo a medias.", "tone_mnemonic_anchor": "51", "cangjie": "FQ", "traditional": ""}, {"character": "夜", "pinyin": "yè", "meaning_en": "night; darkness; evening", "meaning_es": "noche; oscuridad; anochecer", "radical": "夕", "radical_meaning_en": "evening / sunset", "meaning_component": "夕 (crescent moon rising at evening)", "sound_component": "亦 (yì, phonetic match / arms sheltering)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Depicts a human standing under the evening moon (夕) sheltered by the canopy of darkness.", "visual_mnemonic_story_en": "Under the canopy of the roof (亠), the crescent moon (夕) shines through darkness of night.", "visual_mnemonic_story_es": "Bajo el manto del cielo (亠), la luna creciente (夕) alumbra la oscuridad de la noche.", "tone_mnemonic_anchor": "51", "cangjie": "YOKD", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "整座城市在半夜陷入了深沉的沉睡，白日的喧嚣与车水马龙都悄然退去。窗外只有几颗清冷的寒星，静静俯瞰着静谧的街巷。在这样万籁俱寂的半夜，人的心境往往格外澄明，能听见心底最真实的声音。", "pinyin": "Zhěng zuò chéngshì zài bànyè xiànrù le shēnchén de chénshuì, báirì de xuānxiāo yǔ chēshuǐmǎlóng dōu qiǎorán tuìqù. Chuāngwài zhǐyǒu jǐ kē qīnglěng de hánxīng, jìngjìng fǔkàn zhe jìngmì de jiēxiàng. Zài zhèyàng wànlàijùjì de bànyè, rén de xīnjìng wǎngwǎng géwài chéngmíng, néng tīngjiàn xīndǐ zuì zhēnshí de shēngyīn.", "en": "The entire city sank into deep slumber at midnight; daylight clamor and traffic receded. Outside the window, cool stars silently overlooked quiet lanes. In such stillness, the mind becomes clear, hearing the truest voice within.", "es": "La ciudad entera se sumió en un sueño profundo a medianoche; el bullicio diurno y el tráfico desaparecieron. Por la ventana, frías estrellas contemplaban callejuelas en silencio. En esa quietud nocturna, el alma escucha sus anhelos más sinceros."}, {"id": "#2", "hanzi": "在现代越洋跨国金融外汇交易中，许多投资机构的技术团队必须在半夜保持高强度值守。面对国际外汇市场与大宗商品由于突发地缘事件引发的剧烈波动，半夜的实时风险对冲操作往往直接关乎数十亿美元头寸的资产安全。", "pinyin": "Zài xiàndài yuèyáng kuàguó jīnróng wàihuì jiāoyì zhōng, xǔduō tóuzī jīgòu de jìshù tuánduì bìxū zài bànyè bǎochí gāoxiàngdù zhíshǒu. Miànduì guójì wàihuì shìchǎng yǔ dàzōng shāngpǐn yóuyú tūfā dìyuán shìjiàn yǐnfā de jùliè bōdòng, bànyè de shíshí fēngxiǎn duìchōng cāozuò wǎngwǎng zhíjiē guānhū shù shí yì měiyuán tóucùn de zīchǎn ānquán.", "en": "In transoceanic foreign exchange trading, investment teams must maintain vigilance in the middle of the night. Confronting extreme currency volatility sparked by geopolitical events, midnight hedging operations safeguard billions in institutional capital.", "es": "En las finanzas internacionales y el mercado de divisas, los analistas deben hacer guardia a medianoche. Ante la volatilidad extrema provocada por sucesos geopolíticos, las operaciones de cobertura en plena noche protegen carteras multimillonarias de activos."}]}, {"meanings_summary": {"en": "to bite; to sting (of insects); to prompt/exhort; tinkling sound", "es": "picar (un insecto); encargar con insistencia; tintinear"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A mouth (口) driving in like a sharp nail (丁) stings into your skin or drives home a repeated warning (叮).", "composite_memory_hook_es": "Una boca (口) punzante como un clavo (丁) pica la piel o clava una advertencia insistente (叮).", "cultural_and_cognitive_roots": "Polysemous in Chinese culture: physically it mimics the sharp piercing of a nail (丁); rhetorically it duplicates in '叮咛' / '叮嘱', metaphorically nailing wise parental advice firmly into the listener's memory.", "tone_sandhi_and_pitch_modulation": "55 pitch contour. A high, clear, ringing 1st tone (55); sounds brisk and crisp like a metallic chime."}, "semantic_boundary_contrasts": {"core_nuance": "叮 specifically denotes insect stinging/biting with mouthparts, or verbal earnest exhortation (叮嘱).", "contrasts": [{"id": "1", "compared_word": "叮 vs. 咬", "pinyin": "yǎo", "analysis": "咬 implies using upper and lower teeth to clamp down and chew, whereas 叮 specifically applies to insect mouthparts or stingers piercing the skin."}, {"id": "2", "compared_word": "叮 vs. 蛰", "pinyin": "zhē", "analysis": "蛰 refers to venomous stinging by bees, wasps, or scorpions causing burning pain, whereas 叮 applies to mosquito and gnat blood-sucking bites."}, {"id": "3", "compared_word": "叮 vs. 嘱咐", "pinyin": "zhǔfù", "analysis": "嘱咐 is a general verb for bidding or instructing, whereas 叮 specifically emphasizes repeated, earnest verbal urging (as in 叮嘱)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "订", "pinyin": "dìng", "meaning_en": "book; order", "distinction_note": "Features speech radical 讠 on the left instead of mouth 口"}, {"character": "钉", "pinyin": "dīng / dìng", "meaning_en": "nail; tack", "distinction_note": "Features metal radical 钅 on the left instead of mouth 口"}, {"character": "盯", "pinyin": "dīng", "meaning_en": "stare; gaze fixedly", "distinction_note": "Features eye radical 目 on the left instead of mouth 口"}, {"character": "叮", "pinyin": "dīng", "meaning_en": "sting; exhort", "distinction_note": "Headword character itself"}], "etymological_cognates": [{"character": "咬", "pinyin": "yǎo", "gloss_en": "bite; snap at in the mouth radical family"}, {"character": "啄", "pinyin": "zhuó", "gloss_en": "peck; pick with beak"}, {"character": "嚼", "pinyin": "jiáo", "gloss_en": "chew; masticate"}, {"character": "嘱", "pinyin": "zhǔ", "gloss_en": "enjoin; bid words"}]}, "id": "34", "hanzi": "叮", "pinyin": "dīng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to sting or bite with a proboscis or stinger (of mosquitoes, bees, insects)", "definition_es": "picar o morder con aguijón o probóscide (insectos, mosquitos)", "example_phrase": "被蚊子叮了一口 (bitten by a mosquito)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to exhort repeatedly, prompt, or urge with careful instructions", "definition_es": "encargar o advertir con insistencia y cuidado", "example_phrase": "叮嘱再三 (exhort repeatedly)"}], "example_sentences": [{"id": "#1", "hanzi": "昨晚在湖边草丛里散步时，我的脖子不小心被蚊子叮了好几个包，又红又痒，十分难受。", "pinyin": "Zuówǎn zài húbiān cǎocóng lǐ sànbù shí, wǒ de bózi bù xiǎoxīn bèi wénzi dīng le hǎojǐ gè bāo, yòu hóng yòu yǎng, shífēn nánshòu.", "en": "When strolling in the grassy brush by the lake last night, my neck was accidentally bitten by mosquitoes into several welts, red, itchy, and uncomfortable.", "es": "Anoche, al pasear por el pasto junto al lago, los mosquitos me picaron varias veces en el cuello, dejándome ronchas rojas que picaban mucho."}, {"id": "#2", "hanzi": "临行前往高原高寒边防哨所慰问前，后勤医疗总监特意反复叮嘱队员们务必随身携带抗高原反应与防叮咬药品。", "pinyin": "Línxíng qiánwǎng gāoyuán gāohán biānfáng shàosuǒ wèiwèn qián, hòuqín yīliáo zǒngjiān tèyì fǎnfù dīngzhǔ duìyuán men wùbì suíshēn xiàidài kàng gāoyuán fǎnyìng yǔ fáng dīngyǎo yàopǐn.", "en": "Prior to departing for plateau border sentries, the chief medical officer repeatedly exhorted team members to carry altitude sickness and insect bite remedies.", "es": "Antes de viajar a los puestos fronterizos de la meseta, el jefe médico encargó a los brigadistas llevar consigo medicamentos contra el mal de altura y picaduras."}], "collocations": [{"hanzi": "被蚊子叮", "en": "bitten by a mosquito"}, {"hanzi": "叮了一口", "en": "stung once / bitten once"}, {"hanzi": "叮嘱", "en": "exhort / urge with care"}, {"hanzi": "千叮万嘱", "en": "exhort and admonish countless times"}, {"hanzi": "防蚊虫叮咬", "en": "prevent mosquito and insect bites"}, {"hanzi": "叮咚作响", "en": "tinkle and clink melodiously"}], "idioms": [{"hanzi": "千叮万嘱", "pinyin": "qiān dīng wàn zhǔ", "meaning_en": "give repeated earnest instructions and exhortations"}, {"hanzi": "再三叮咛", "pinyin": "zài sān dīng níng", "meaning_en": "exhort over and over again with tender solicitude"}, {"hanzi": "言犹在耳", "pinyin": "yán yóu zài ěr", "meaning_en": "words still ringing in one's ears; advice remembered freshly"}, {"hanzi": "耳提面命", "pinyin": "ěr tí miàn mìng", "meaning_en": "instruct face to face and pull by the ear; give earnest guidance"}], "character_decomposition": [{"character": "叮", "pinyin": "dīng", "meaning_en": "bite/sting; exhort; clear tinkle", "meaning_es": "picar; encargar; tintinear", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (mouth/stinger piercing or words prompting)", "sound_component": "丁 (dīng, nail/pointed tool)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character pairing mouth (口) with pointed nail (丁), describing a sharp sting like a nail, or sharp verbal reminders.", "visual_mnemonic_story_en": "An insect uses its mouthpart like a sharp nail (丁) to sting through skin with a needle-like prick.", "visual_mnemonic_story_es": "Un insecto usa su boca como un clavo diminuto y punzante (丁) para picar la piel.", "tone_mnemonic_anchor": "55", "cangjie": "RMN", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "每次远行离家，母亲总会拉着我的手，千叮万嘱要按时吃饭、注意保暖。那些朴实无华的言语，宛如冬日里的一缕暖阳，穿透遥远的距离，在岁月的长河中化作心头最深沉的牵挂与前行的力量。", "pinyin": "Měi cì yuǎnxíng líjiā, mǔqīn zǒng huì lā zhe wǒ de shǒu, qiān dīng wàn zhǔ yào ànshí chīfàn, zhùyì bǎonuǎn. Nàxiē pǔshíwúhuá de yányǔ, wǎnrú dōngrì lǐ de yì lǚ nuǎnyáng, chuāntòu yuǎnyuán de jùlí, zài suìyuè de chánghé zhōng huàzuò xīntóu zuì shēnchén de qiānguà yǔ qiánxíng de lìliàng.", "en": "Whenever I left home for long journeys, mother held my hand, repeatedly exhorting me to eat on time and stay warm. Those unadorned words were like winter sunlight, spanning distance to become enduring solace and strength.", "es": "Cada vez que partía de viaje, mi madre me tomaba de las manos encargándome una y otra vez que comiera a tiempo y me abrigara. Esas sencillas palabras fueron como un sol invernal que acortó distancias, dándome fuerzas para el camino."}, {"id": "#2", "hanzi": "在现代野外边境科考与丛林探险安全规范中，防范毒虫叮咬是保障队员生存能力的关键科目。通过配发高长效驱避防护服与抗组胺外用药膏，能够有效遏制野外有害蚊蠓叮咬引发的过敏性皮炎及虫媒疾病感染。", "pinyin": "Zài xiàndài yěwài biānjìng kěkǎo yǔ cónglín tànxiǎn ānquán guīfàn zhōng, fángfàn dúchóng dīngyǎo shì bǎozhàng duìyuán shēngcún nénglì de guānjiàn kēmù. Tōngguò pèifā gāo chángxiào qūbì fánghùfú yǔ kàngzǔ'àn wàiyòng yàogāo, nénggòu yǒuxiào èzhì yěwài yǒuhài wénměng dīngyǎo yǐnfā de guòmǐnxìng píyán jí chóngméi jíbìng gǎnrǎn.", "en": "In field expeditions and jungle safety protocols, preventing toxic insect bites is critical for team survival. Equipping long-lasting repellent gear and antihistamines curbs allergic dermatitis and vector-borne infections caused by insect bites.", "es": "En las expediciones por la selva, prevenir las picaduras de insectos venenosos es vital para la supervivencia. Dotar al equipo de ropa repelente y pomadas antihistamínicas frena la dermatitis alérgica y los contagios parasitarios."}]}, {"meanings_summary": {"en": "wife (colloquial; affectionate)", "es": "esposa; mujer (coloquial y cariñoso)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The lifelong companion (老) with whom you vow to grow into venerable old age (婆) is your cherished wife (老婆).", "composite_memory_hook_es": "La compañera de por vida (老) con quien envejecerás hasta peinar canas (婆) es tu querida esposa (老婆).", "cultural_and_cognitive_roots": "Song Dynasty folklore records poet Mai Aixin desiring a concubine; his wife composed a rhyming couplet: '老公十分公道，老婆一片婆心'. Moved by her devotion, he abandoned the thought. Ever since, 'lǎogōng' and 'lǎopo' became China's most affectionate spousal terms.", "tone_sandhi_and_pitch_modulation": "214-35 contour. In everyday spoken Chinese, 婆 is universally reduced to a light neutral tone: lǎopo (21-neutral)."}, "semantic_boundary_contrasts": {"core_nuance": "老婆 is an affectionate, colloquial, and warm spoken term used to refer to one's own wife.", "contrasts": [{"id": "1", "compared_word": "老婆 vs. 妻子", "pinyin": "qīzi", "analysis": "妻子 is the formal, standard, written, and legal term for wife, whereas 老婆 is predominantly colloquial and intimate."}, {"id": "2", "compared_word": "老婆 vs. 太太", "pinyin": "tàitai", "analysis": "太太 is a polite, respectful, and slightly formal term for someone else's wife or socially elevated spouse, whereas 老婆 is everyday casual."}, {"id": "3", "compared_word": "老婆 vs. 爱人", "pinyin": "àirén", "analysis": "爱人 is gender-neutral meaning 'spouse' in mainland administrative/social contexts, whereas 老婆 specifically designates a female spouse."}]}, "traps_and_cognates": {"look_alikes": [{"character": "考", "pinyin": "kǎo", "meaning_en": "test; examine", "distinction_note": "Features 丂 at the bottom instead of 匕"}, {"character": "孝", "pinyin": "xiào", "meaning_en": "filial piety", "distinction_note": "Features 子 (child) at the bottom beneath 土"}, {"character": "波", "pinyin": "bō", "meaning_en": "wave; ripple", "distinction_note": "Features water radical 氵 on the left without 女"}, {"character": "婆", "pinyin": "pó", "meaning_en": "matron; wife", "distinction_note": "Headword character itself"}], "etymological_cognates": [{"character": "妻", "pinyin": "qī", "gloss_en": "formal wife"}, {"character": "妇", "pinyin": "fù", "gloss_en": "married woman; matron"}, {"character": "媳", "pinyin": "xí", "gloss_en": "daughter-in-law; wife in 媳妇"}, {"character": "娘", "pinyin": "niáng", "gloss_en": "mother; young woman"}]}, "id": "35", "hanzi": "老婆", "pinyin": "lǎo po", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Colloquial", "definition_en": "informal, affectionate spoken term for one's wife or someone's spouse", "definition_es": "término coloquial y afectuoso para referirse a la propia esposa o cónyuge", "example_phrase": "疼老婆 (cherish one's wife)"}], "example_sentences": [{"id": "#1", "hanzi": "下班回家的路上，王强特意去花店买了一束新鲜的红玫瑰，打算给正在厨房忙着做晚餐的老婆一个惊喜。", "pinyin": "Xiàbān huíjiā de lùshang, Wáng Qiáng tèyì qù huādiàn mǎi le yí shù xīnxiān de hóng méiguī, dǎsuàn gěi zhèngzài chúfáng máng zhe zuò wǎncān de lǎopo yí gè jīngxǐ.", "en": "On his way home from work, Wang Qiang stopped by the florist to buy fresh red roses, intending to give his wife cooking dinner in the kitchen a surprise.", "es": "Al volver del trabajo, Wang Qiang pasó por la floristería a comprar rosas rojas para sorprender a su esposa, que preparaba la cena en la cocina."}, {"id": "#2", "hanzi": "社会学学者在关于当代城市家庭劳务分工的调研中指出，“怕老婆”等民间幽默俗语的演变，从侧面折射出女性家庭话语权与家庭平等地位的实质性提升。", "pinyin": "Shèhuìxué xuézhě zài guānyú dāngdài chéngshì jiātíng láowù fēngōng de diàoyán zhōng zhǐchū, “pà lǎopo” děng mínjiān yōumò súyǔ de yǎnbiàn, cóng cèmiàn zhéshè chū nǚxìng jiātíng huàyǔquán yǔ jiātíng píngděng dìwèi de shízhìxìng tíshēng.", "en": "Sociologists researching urban household labor division note that humorous folk sayings like 'henpecked / fearing one's wife' mirror the substantive rise of women's domestic status and equality.", "es": "Los sociólogos señalan que dichos humorísticos populares como 'temer a la esposa' reflejan el aumento real de la equidad y del poder de decisión de las mujeres en el hogar moderno."}], "collocations": [{"hanzi": "疼老婆", "en": "cherish and dote on one's wife"}, {"hanzi": "怕老婆", "en": "henpecked / respect one's wife immensely"}, {"hanzi": "娶老婆", "en": "take a wife / marry"}, {"hanzi": "老婆孩子", "en": "wife and kids; family"}, {"hanzi": "讨老婆", "en": "seek a wife to marry"}, {"hanzi": "爱老婆", "en": "love one's wife"}], "idioms": [{"hanzi": "白头偕老", "pinyin": "bái tóu xié lǎo", "meaning_en": "live together until white hair; grow old together in marital devotion"}, {"hanzi": "相濡以沫", "pinyin": "xiāng rú yǐ mò", "meaning_en": "share meager resources in adversity; mutual support in marital hardship"}, {"hanzi": "老骥伏枥", "pinyin": "lǎo jì fú lì", "meaning_en": "an old steed in the stable still aspires to gallop a thousand miles"}, {"hanzi": "返老还童", "pinyin": "fǎn lǎo huán tóng", "meaning_en": "rejuvenate; recover youthful vigor in old age"}], "character_decomposition": [{"character": "老", "pinyin": "lǎo", "meaning_en": "old; experienced; affectionate prefix", "meaning_es": "viejo; anciano; experimentado; prefijo afectivo", "radical": "老", "radical_meaning_en": "old", "meaning_component": "老 (elderly man with long hair leaning on cane)", "sound_component": "老 (inherent root)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Pictogram of an elderly revered person with long hair leaning upon a walking staff (匕/𠤎).", "visual_mnemonic_story_en": "An elderly person with silver hair leans on a walking cane (老), embodying lifelong companionship.", "visual_mnemonic_story_es": "Un anciano con cabellos canos se apoya en un bastón (老), simbolizando la compañía de toda la vida.", "tone_mnemonic_anchor": "214", "cangjie": "JKP", "traditional": ""}, {"character": "婆", "pinyin": "po", "meaning_en": "elderly woman; grandmother; matron; wife", "meaning_es": "anciana; abuela; matrona; esposa", "radical": "女", "radical_meaning_en": "woman", "meaning_component": "女 (woman)", "sound_component": "波 (bō, rippling waves)", "stroke_count": "11", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic character pairing woman (女) with rippling waves (波), historically denoting a venerable matron with silver hair.", "visual_mnemonic_story_en": "A respected woman (女) whose hair has rippled like soft waves (波) through years of devotion.", "visual_mnemonic_story_es": "Una mujer respetable (女) cuyos cabellos ondean como suaves olas (波) tras años de vida compartida.", "tone_mnemonic_anchor": "35", "cangjie": "EDV", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "清晨厨房里冒着热气的清粥小菜，深夜归家时门厅留着的一盏暖灯，都是老婆给予这个家最温柔的守候。岁月悄然带走了青春的容颜，但彼此相视一笑的默契，却在柴米油盐的琐碎烟火中化作了不可磨灭的依恋。", "pinyin": "Qīngchén chúfáng lǐ màozhe rèqì de qīngzhōu xiǎocài, shēnyè guījiā shí méntīng liúzhe de yì zhǎn nuǎndēng, dōu shì lǎopo jǐyǔ zhè gè jiā zuì wēnróu de shǒuhòu. Suìyuè qiǎorán dàizǒu le qīngchūn de róngyán, dàn bǐcǐ xiāngshìyíxiào de mòqì, què zài cháimǐyóuyán de suǒsuì yānhuǒ zhōng huàzuò le bùkěmómiè de yīliàn.", "en": "Steaming porridge in the morning kitchen and a warm light in the foyer late at night are the gentlest guardianship a wife gives a home. Time takes youthful looks, but a knowing smile across daily meals becomes an indelible bond.", "es": "El tazón humeante en la cocina matinal y la luz tibia en el zaguán de noche son la devoción más dulce de una esposa. El tiempo atenúa la juventud, pero la sonrisa cómplice entre los quehaceres cotidianos forja un apego imborrable."}, {"id": "#2", "hanzi": "在当代家庭社会学研究中，核心家庭内部的情感表达方式展现出深刻的平等化特征。男性在日常社交中大方表达对老婆的关爱与敬重，不仅体现了家庭决策权向平等协商的转变，更重塑了现代文明家庭伦理的包容范式。", "pinyin": "Zài dāngdài jiātíng shèhuìxué yánjiū zhōng, héxīn jiātíng nèibù de qínggǎn biǎodá fāngshì zhǎnxiàn chū shēnkè de píngděnghuà tèzhēng. Nánxìng zài rìcháng shèjiāo zhōng dàfāng biǎodá duì lǎopo de guān'ài yǔ jìngzhòng, bùjǐn tǐxiàn le jiātíng juécèquán xiàng píngděng xiéshāng de zhuǎnbìan, gèng zhòngshù le xiàndài wénmíng jiātíng lúnlǐ de bāoróng fànshì.", "en": "In contemporary family sociology, emotional expression within nuclear families shows profound egalitarian characteristics. Husbands openly expressing care and respect for their wives mirrors democratic household decisions, reshaping civilized ethics.", "es": "En la sociología familiar contemporánea, la expresión de afecto en el hogar evidencia una profunda igualdad. Que los hombres manifiesten cariño y respeto hacia sus esposas refleja decisiones domésticas democráticas, renovando la ética familiar."}]}, {"meanings_summary": {"en": "to make a noise; to quarrel; to disturb; noisy; clamorous", "es": "hacer ruido; reñir; molestar; ruidoso; bullicioso"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Opening a loud mouth (口) with too little (少) courtesy creates a noisy clamor (吵).", "composite_memory_hook_es": "Abrir una boca (口) ruidosa con poca (少) prudencia provoca un gran alboroto (吵).", "cultural_and_cognitive_roots": "In traditional Chinese spatial aesthetics, tranquility ('静') represents philosophical refinement; 'chǎo' (auditory disturbance) disrupts domestic peace (安宁) and emotional equilibrium.", "tone_sandhi_and_pitch_modulation": "214 pitch contour. A dipping 3rd tone; when placed before 1st, 2nd, or 4th tones, it is pronounced as a half-3rd tone (21 low)."}, "semantic_boundary_contrasts": {"core_nuance": "吵 functions flexibly as a verb (to make noise / quarrel) and as an adjective (noisy and irritating).", "contrasts": [{"id": "1", "compared_word": "吵 vs. 闹", "pinyin": "nào", "analysis": "吵 focuses strictly on unpleasant auditory loudness and verbal friction, whereas 闹 can indicate lively festive bustling (e.g., 热闹) or mischievous antics."}, {"id": "2", "compared_word": "吵 vs. 喧哗", "pinyin": "xuānhuá", "analysis": "喧哗 is formal and written, denoting unseemly loud clamor in public places (e.g., 请勿喧哗), while 吵 is common vernacular spoken Chinese."}, {"id": "3", "compared_word": "吵 vs. 嘈杂", "pinyin": "cáozá", "analysis": "嘈杂 is an adjective describing a confused, disordered bedlam of overlapping sounds (e.g., 嘈杂的市场), whereas 吵 can function as a transitive verb (e.g., 别吵我)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "抄", "pinyin": "chāo", "meaning_en": "copy; transcribe", "distinction_note": "Has hand radical 扌 on the left instead of mouth 口"}, {"character": "秒", "pinyin": "miǎo", "meaning_en": "second (time)", "distinction_note": "Has grain radical 禾 on the left instead of mouth 口"}, {"character": "炒", "pinyin": "chǎo", "meaning_en": "stir-fry; sauté", "distinction_note": "Has fire radical 火 on the left instead of mouth 口"}, {"character": "砂", "pinyin": "shā", "meaning_en": "sand; grit", "distinction_note": "Has stone radical 石 on the left instead of mouth 口"}], "etymological_cognates": [{"character": "喧", "pinyin": "xuān", "gloss_en": "clamor; noisy mouth radical"}, {"character": "哗", "pinyin": "huá", "gloss_en": "hubbub; uproar"}, {"character": "噪", "pinyin": "zào", "gloss_en": "cacophony; noise"}, {"character": "闹", "pinyin": "nào", "gloss_en": "boisterous; make trouble"}]}, "id": "36", "hanzi": "吵", "pinyin": "chǎo", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to make loud clamor, disturb someone with noise, or quarrel vocally", "definition_es": "hacer ruido perturbador, alborotar o reñir en voz alta", "example_phrase": "别吵了 (stop making noise / stop arguing)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "noisy, turbulent, or deafeningly loud", "definition_es": "ruidoso, bullicioso o estrepitoso", "example_phrase": "外边太吵 (it is too noisy outside)"}], "example_sentences": [{"id": "#1", "hanzi": "隔壁邻居家装修房屋的声音实在太吵了，正在准备高考复习的姐姐根本无法在书房集中注意力。", "pinyin": "Gébì línjī jiā zhuāngxiū fángwū de shēngyīn shízài tài chǎo le, zhèngzài zhǔnbèi gāokǎo fùxí de jiějie gēnběn wúfǎ zài shūfáng jízhōng zhùyìlì.", "en": "The noise from home renovation in the neighboring apartment was far too noisy; my older sister preparing for college entrance exams simply could not concentrate.", "es": "El ruido de las obras en la casa del vecino era insoportable; mi hermana, que repasaba para el examen de ingreso universitario, no lograba concentrarse en absoluto."}, {"id": "#2", "hanzi": "市生态环境综合执法支队针对市民反复投诉的工业噪声污染企业展开突击夜查，对违法夜间超标排放吵民噪声的施工现场下达限期停工整改通知书。", "pinyin": "Shì shēngtài huánjìng zōnghé zhífǎ zhīduì zhēnduì shìmín fǎnfù tóusù de gōngyè zhàoshēng wūrǎn qǐyè zhǎnkāi tūjī yèchá, duì wéifǎ yèjiān chāobiāo páifàng chǎo mín zhàoshēng de shīgōng xiànchǎng xiàdá xiànqī tínggōng zhěnggǎi tōngzhīshū.", "en": "Environmental law enforcement launched surprise night inspections against industrial noise pollution, issuing suspension orders to construction sites unlawfully disturbing residents.", "es": "La brigada ambiental realizó inspecciones nocturnas contra la contaminación acústica, ordenando la paralización inmediata de las obras que perturbaban el descanso vecinal."}], "collocations": [{"hanzi": "吵闹不休", "en": "clamorous and ceaseless"}, {"hanzi": "吵醒熟睡的人", "en": "awaken someone from sleep with noise"}, {"hanzi": "环境太吵", "en": "environment is too noisy"}, {"hanzi": "别吵了", "en": "stop shouting / stop bickering"}, {"hanzi": "吵吵闹闹", "en": "noisy and turbulent"}, {"hanzi": "吵得头疼", "en": "so loud it gives one a headache"}], "idioms": [{"hanzi": "吵吵闹闹", "pinyin": "chāo chao nào nào", "meaning_en": "noisy and clamorous; full of squabbling"}, {"hanzi": "人声鼎沸", "pinyin": "rén shēng dǐng fèi", "meaning_en": "a boiling hubbub of human voices; noisy clamor"}, {"hanzi": "沸反盈天", "pinyin": "fèi fǎn yíng tiān", "meaning_en": "uproarious din reaching the skies; chaotic noise"}, {"hanzi": "鸦雀无声", "pinyin": "yā què wú shēng", "meaning_en": "not even a crow or sparrow heard; dead silence; direct antonym"}], "character_decomposition": [{"character": "吵", "pinyin": "chǎo", "meaning_en": "make noise; noisy; quarrel", "meaning_es": "hacer ruido; ruidoso; reñir", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (mouth emitting sound)", "sound_component": "少 (shǎo, phonetic harmony)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic character pairing mouth (口) with 少 (shǎo), describing intrusive racket uttered by unrestrained mouths.", "visual_mnemonic_story_en": "Unrestrained mouths (口) yelling with small (少) consideration create intolerable noise.", "visual_mnemonic_story_es": "Bocas (口) vociferando con poca (少) consideración provocan un ruido insoportable.", "tone_mnemonic_anchor": "214", "cangjie": "RFH", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "厌倦了都市车水马龙的喧吵，周末独自漫步在清幽的山林深处。耳畔没有了刺耳的鸣笛与刺目的喧嚣，只有松涛阵阵与溪流潺潺。在远离吵闹的大自然怀抱中，心灵终于找回了久违的安宁与从容。", "pinyin": "Yànjuàn le dūshì chēshuǐmǎlóng de xuānchǎo, zhōumò dúzì mànbù zài qīngyōu de shānlín shēnchù. Ěrpàn méiyǒu le cì'ěr de míngdí yǔ cìmù de xuānxiāo, zhǐyǒu sōngtāo zhènzhèn yǔ xīliú chánchán. Zài yuǎnlí chǎonào de dàzìrán huáibào zhōng, xīnlíng zhōngyú zhǎohuí le jiǔwéi de ānníng yǔ cóngróng.", "en": "Weary of urban traffic and clamor, I strolled alone through tranquil mountain forests over the weekend. Gone were shrill horns and bustle, replaced by pine breezes and bubbling brooks. Far from noise, the soul reclaimed peace.", "es": "Fatigado del bullicio urbano y los atascos, caminé a solas por la espesura del bosque el fin de semana. Lejos de bocinazos estridentes, solo susurraban los pinos y el arroyo, permitiendo al alma reencontrar la calma perdida."}, {"id": "#2", "hanzi": "在现代高科技声学工程与室内建筑设计中，低频结构传声隔震已成为治理施工吵民的核心技术。通过在精密仪器实验室与住宅楼层间铺设阻尼隔音垫层，能有效将刺耳噪声衰减在法定阈值以内，保障高品质声环境。", "pinyin": "Zài xiàndài gāokējì shēngxué gōngchéng yǔ shìnèi jiànzhù shèjì zhōng, dīpín jiégòu chuánshēng gézhèn yǐ chéngwéi zhìlǐ shīgōng chǎomín de héxīn jìshù. Tōngguò zài jīngmì yíqì shíyànshì yǔ zhùzhái lóucéng jiān pūsè zǔní géyīn diàncéng, néng yǒuxiào jiāng cì'ěr zhàoshēng shuāijiǎn zài fǎdìng yùzhí yǐnèi, bǎozhàng gāozhìliàng shēnghuánjìng.", "en": "In acoustic engineering and building design, low-frequency structural vibration dampening is core to mitigating residential noise disturbances. Laying acoustic damping underlays between residential floors attenuates intrusive noise within statutory thresholds.", "es": "En la ingeniería acústica y el diseño arquitectónico, el aislamiento de vibraciones estructurales es clave contra la contaminación acústica. Instalar capas aislantes entre plantas residenciales atenúa ruidos molestos dentro de los umbrales legales."}]}, {"meanings_summary": {"en": "measure word for itemized things, tasks, proposals, and projects; nape of neck; item", "es": "clasificador para asuntos, tareas, partidas, proyectos y normas; nuca; rubro"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Holding your head (页) high while undertaking work (工) allows you to check off each itemized task (项).", "composite_memory_hook_es": "Mantener la nuca erguida (页) para trabajar con empeño (工) permite cumplir cada tarea y partida (项).", "cultural_and_cognitive_roots": "Anatomically meant the nape of the neck ('项背'); in Chinese bureaucratic accounting, documents were divided into 'heads' (项) like items in a ledger, transforming into the quintessential measure word for formal endeavors.", "tone_sandhi_and_pitch_modulation": "51 pitch contour. A resolute falling 4th tone (51); enunciate with firm falling projection."}, "semantic_boundary_contrasts": {"core_nuance": "项 is a formal measure word specifically tailored for itemized projects, research tasks, policies, awards, or sports events.", "contrasts": [{"id": "1", "compared_word": "项 vs. 个", "pinyin": "gè", "analysis": "个 is a universal colloquial measure word, whereas 项 is reserved for formalized, itemized projects, proposals, or tasks (e.g., 一项研究, 一项任务)."}, {"id": "2", "compared_word": "项 vs. 条", "pinyin": "tiáo", "analysis": "条 is used for slender objects, roads, or legal statutory clauses (如一条法规), while 项 is used for programmatic projects or overarching endeavors."}, {"id": "3", "compared_word": "项 vs. 宗", "pinyin": "zōng", "analysis": "宗 is an administrative/commercial measure word for large bulk transactions or court cases (e.g., 一宗大买卖), whereas 项 classifies discrete tasks or criteria."}]}, "traps_and_cognates": {"look_alikes": [{"character": "顶", "pinyin": "dǐng", "meaning_en": "top; crown", "distinction_note": "Features 丁 on the left instead of 工 with 页"}, {"character": "预", "pinyin": "yù", "meaning_en": "in advance; prepare", "distinction_note": "Features 予 on the left instead of 工 with 页"}, {"character": "烦", "pinyin": "fán", "meaning_en": "troubled; vexed", "distinction_note": "Features 火 (fire) on the left instead of 工 with 页"}, {"character": "领", "pinyin": "lǐng", "meaning_en": "collar; lead", "distinction_note": "Features 令 on the left of 页"}], "etymological_cognates": [{"character": "条", "pinyin": "tiáo", "gloss_en": "item; clause; strip"}, {"character": "款", "pinyin": "kuǎn", "gloss_en": "clause; paragraph; fund"}, {"character": "目", "pinyin": "mù", "gloss_en": "item; eye; rubric in 项目"}, {"character": "件", "pinyin": "jiàn", "gloss_en": "piece; document"}]}, "id": "37", "hanzi": "项", "pinyin": "xiàng", "level": "HSK 5", "part_of_speech": "Measure Word", "senses": [{"sense_number": "1", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "measure word used for itemized tasks, proposals, scientific research projects, principles, or regulations", "definition_es": "clasificador empleado para proyectos, tareas, propuestas, medidas o principios numerados", "example_phrase": "一项重要任务 (an important task)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Formal", "definition_en": "nape of the neck; itemized entry; term in algebra", "definition_es": "nuca; partida contable; rubro; término matemático", "example_phrase": "望其项背 (see the back of someone's neck)"}], "example_sentences": [{"id": "#1", "hanzi": "在今天上午举行的毕业典礼上，校长亲自为每一位在各学科学术竞赛中斩获殊荣的优秀毕业生颁发了一项特别荣誉奖。", "pinyin": "Zài jīntiān shàngwǔ jǔxíng de bìyè diǎnlǐ shàng, xiàozhǎng qīnzì wèi měi yí wèi zài gè xuékē xuéshù jìngsài zhōng zhǎnhuò shūróng de yōuxiù bìyèshēng bānfā le yí xiàng tèbié róngyù jiǎng.", "en": "At the graduation ceremony this morning, the principal personally presented a special honorary award to each outstanding graduate who triumphed in academic contests.", "es": "En la ceremonia de graduación de esta mañana, el rector entregó personalmente una distinción de honor especial a cada graduado destacado en certámenes académicos."}, {"id": "#2", "hanzi": "为深化全国统一大市场建设，国家发展改革委联合商务部正式发布了新版市场准入负面清单，取消了多项不合理的行政审批许可事项。", "pinyin": "Wèi shēnhuà quánguó tǒngyī dà shìchǎng jiànshè, Guójiā Fāzhǎn Gǎigé Wěi liánhé Shāngwùbù zhèngshì fābù le xīnbǎn shìchǎng zhǔnrù fùmiàn qīngdān, qǔxiāo le duō xiàng bù hélǐ de xíngzhèng shěnpī xǔkě shìxiàng.", "en": "To deepen unified national market construction, authorities issued a negative list for market access, abolishing multiple unreasonable administrative licensing items.", "es": "Para profundizar el mercado unificado, las autoridades publicaron la nueva lista negativa de acceso al mercado, eliminando múltiples trámites y licencias administrativas desmedidas."}], "collocations": [{"hanzi": "一项任务", "en": "an itemized task"}, {"hanzi": "多项原则", "en": "multiple principles"}, {"hanzi": "一项研究", "en": "a research study"}, {"hanzi": "注意事项", "en": "matters needing attention / caveats"}, {"hanzi": "一项新技术", "en": "a new technology"}, {"hanzi": "专项资金", "en": "special earmarked fund"}], "idioms": [{"hanzi": "望其项背", "pinyin": "wàng qí xiàng bèi", "meaning_en": "see the back of someone's neck; catch up with someone of superior ability"}, {"hanzi": "名列前茅", "pinyin": "míng liè qián máo", "meaning_en": "rank among the very best on the roster"}, {"hanzi": "有条不紊", "pinyin": "yǒu tiáo bù wěn", "meaning_en": "methodical and systematic without disorder"}, {"hanzi": "分门别类", "pinyin": "fēn mén bié lèi", "meaning_en": "classify into distinct categories and rubrics"}], "character_decomposition": [{"character": "项", "pinyin": "xiàng", "meaning_en": "item; neck; nape; classifier for tasks", "meaning_es": "rubro; nuca; clasificador para tareas y asuntos", "radical": "页", "radical_meaning_en": "leaf / head", "meaning_component": "页 (head/neck area)", "sound_component": "工 (gōng, phonetic association)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts the back of the neck (页) supporting the head with work (工); extended metaphorically to individual itemized heads in an official inventory.", "visual_mnemonic_story_en": "A muscular work (工) posture holds the nape of the head (页) high, checking off cataloged items.", "visual_mnemonic_story_es": "Una postura firme de trabajo (工) sostiene erguida la nuca (页) al verificar los rubros catalogados.", "tone_mnemonic_anchor": "51", "cangjie": "MCB", "traditional": "項"}], "extended_reading_passages": [{"id": "#1", "hanzi": "科研探索从来不是一蹴而就的坦途，每一项重大科学理论的诞生，都凝结着无数科学家数十载甘坐冷板凳的心血。在平凡的岗位上把每一项细微的数据测算做到极致，才能在人类探索真理的征程中留下坚实的足迹。", "pinyin": "Kēyán tànsuǒ cónglái bú shì yícù'érjiù de tǎntú, měi yí xiàng zhòngdà kēxué lǐlùn de dànshēng, dōu níngjié zhe wúshù kēxuéjiā shù shí zǎi gān zuò lěngbǎndèng de xīnxuè. Zài píngfán de gǎngwèi shàng bǎ měi yí xiàng xìwēi de shùjù cèsuàn zuò dào jízhì, cáinǐng zài rénlèi tànsuǒ zhēnlǐ de zhēngchéng zhōng liúxià jiānshí de zújì.", "en": "Scientific discovery is never a smooth journey achieved overnight; the birth of every major theory embodies decades of tireless dedication by scientists. Perfecting every measurement in ordinary posts leaves indelible footprints toward truth.", "es": "La investigación científica nunca es un camino llano ni inmediato; el nacimiento de cada teoría trascendental condensa décadas de paciente entrega. Llevar cada medición al máximo rigor en el trabajo diario forja huellas firmes hacia la verdad."}, {"id": "#2", "hanzi": "在推动高水平对外开放的战略框架下，我国自贸试验区持续对标国际高标准经贸规则。通过率先推进外商投资管理体制改革，累计向全国复制推广了数百项制度创新成果，为优化营商环境注入了强劲动力。", "pinyin": "Zài tuīdòng gāoshuǐpíng duìwài kāifàng de zhànlüè kuàngjià xià, wǒ guó zìmào shìyànqū chíxù duìbiāo guójì gāobiāozhǔn jīngmào guīzé. Tōngguò shuàixiān tuījìn wàishāng tóuzī guǎnlǐ tǐzhì gǎigé, lěijì xiàng quánguó fùzhì tuīguǎng le shù bǎi xiàng zhìdù chuàngxīn chéngguǒ, wèi yōuhuà yíngshāng huánjìng zhùrù le qiángjìn dònglì.", "en": "Under high-level opening-up strategies, pilot free trade zones align with international economic rules. By leading foreign investment reforms, they replicated hundreds of institutional innovations nationwide, infusing vitality into business environments.", "es": "En la apertura comercial de alto nivel, las zonas piloto de libre comercio se adaptan a las normas económicas internacionales. Al liderar reformas a la inversión extranjera, han difundido cientos de innovaciones institucionales vigorizando los negocios."}]}, {"meanings_summary": {"en": "to share hardships and tribulations together; go through thick and thin together", "es": "compartir juntos las adversidades; apoyarse en las duras y en las maduras; compartir infortunios"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Confronting perils (患) and catastrophes (难), standing hand-in-hand together with (与) shared destiny (共) defines enduring solidarity.", "composite_memory_hook_es": "Afrontar peligros (患) y desdichas (难), unidos de la mano (与) en hermandad común (共) encarna la solidaridad inquebrantable.", "cultural_and_cognitive_roots": "From the Sima Qian's Records of the Grand Historian (史记·越王勾践世家): '越王为人长颈鸟喙，可与共患难，不可与共乐' (The King of Yue is a man with whom one can share adversity, but not prosperity). In modern Chinese ethics, the idiom represents the ultimate benchmark of steadfast friendship and marital loyalty.", "tone_sandhi_and_pitch_modulation": "51-51-214-51 pitch contour. Notice that 难 is pronounced in the 4th tone nàn (51, meaning calamity), NOT 2nd tone nán (difficult); yǔ is pronounced as a half-3rd tone (21 low) before gòng (51)."}, "semantic_boundary_contrasts": {"core_nuance": "患难与共 specifically denotes staunchly staying together to endure severe hardship, danger, and adversity without deserting one another.", "contrasts": [{"id": "1", "compared_word": "患难与共 vs. 同甘共苦", "pinyin": "tónggāngòngkǔ", "analysis": "同甘共苦 covers sharing both joy and sorrow (sweetness and bitterness), whereas 患难与共 specifically emphasizes standing firm through severe peril and tribulation."}, {"id": "2", "compared_word": "患难与共 vs. 风雨同舟", "pinyin": "fēngyǔtóngzhōu", "analysis": "风雨同舟 evokes the visual metaphor of sailing together in a turbulent storm facing common peril, while 患难与共 focuses on deep personal and institutional loyalty during life crises."}, {"id": "3", "compared_word": "患难与共 vs. 同舟共济", "pinyin": "tóngzhōugòngjì", "analysis": "同舟共济 stresses practical mutual assistance and cooperative effort to overcome an emergency obstacle, whereas 患难与共 highlights enduring emotional and ethical solidarity."}]}, "traps_and_cognates": {"look_alikes": [{"character": "忠", "pinyin": "zhōng", "meaning_en": "loyal", "distinction_note": "Features 中 over 心 instead of 串"}, {"character": "淮", "pinyin": "huái", "meaning_en": "Huai River", "distinction_note": "Features water radical 氵 on the left with 隹"}, {"character": "写", "pinyin": "xiě", "meaning_en": "write", "distinction_note": "Features crown radical 冖 on top of 与"}, {"character": "其", "pinyin": "qí", "meaning_en": "his; its", "distinction_note": "Features additional horizontal strokes inside"}], "etymological_cognates": [{"character": "同", "pinyin": "tóng", "gloss_en": "same; shared with"}, {"character": "盟", "pinyin": "méng", "gloss_en": "alliance sworn in blood"}, {"character": "劫", "pinyin": "jié", "gloss_en": "calamity; catastrophe"}, {"character": "难", "pinyin": "nàn", "gloss_en": "adversity; headword root"}]}, "id": "38", "hanzi": "患难与共", "pinyin": "huàn nàn yǔ gòng", "level": "HSK 5", "part_of_speech": "Idiom", "senses": [{"sense_number": "1", "part_of_speech": "Idiom", "register": "Literary", "definition_en": "to stand together and share adversity, hardship, and peril side by side as steadfast partners or companions", "definition_es": "permanecer unidos afrontando juntos las penurias, peligros y adversidades como aliados incondicionales", "example_phrase": "患难与共的夫妻 (husband and wife who shared hardships together)"}], "example_sentences": [{"id": "#1", "hanzi": "在创业最艰难的创业初期，合伙人不仅没有分道扬镳，反而同住一间地下室患难与共，最终攻克难关创立了行业知名品牌。", "pinyin": "Zài chuàngyè zuì jiānnán de chuàngyè chūqī, héhuǒrén bùjǐn méiyǒu fēndàoyángbiāo, fǎn'ér tóng zhù yì jiān dìxiàshì huànnànyǔgòng, zuìzhōng gōngkè nánguān chuànglì le hángyè zhīmíng pǐnpái.", "en": "During the most grueling early startup days, the partners did not part ways; instead, they lived in a basement sharing hardships together, conquering hurdles to establish a renowned brand.", "es": "En los inicios más duros del emprendimiento, los socios no se dispersaron; compartieron juntos las penurias en un sótano, superando obstáculos hasta forjar una marca líder."}, {"id": "#2", "hanzi": "建交半个多世纪以来，两国人民在争取民族独立与推动国家现代化建设的历史进程中始终患难与共，结下了坚不可摧的深厚友谊。", "pinyin": "Jiànjiāo bàn gè shìjì yǐlái, liǎng guó rénmín zài zhēngqǔ mínzú dúlì yǔ tuīdòng guójiā xiàndàihuà jiànshè de lìshǐ jìnchéng zhōng shǐzhōng huànnànyǔgòng, jiéxià le jiānbùkěcuī de shēnhòu yǒuyì.", "en": "Since establishing diplomatic relations over half a century ago, the peoples of both nations have shared hardships together in modernization, forging unbreakable friendship.", "es": "En más de medio siglo de lazos diplomáticos, ambos pueblos han compartido vicisitudes en la búsqueda de su soberanía y desarrollo, forjando una amistad indestructible."}], "collocations": [{"hanzi": "患难与共的朋友", "en": "friends who shared trials and tribulations"}, {"hanzi": "患难与共的真情", "en": "true devotion tested by hardship"}, {"hanzi": "始终患难与共", "en": "always share hardships together throughout"}, {"hanzi": "患难与共的经历", "en": "experience of weathering storms together"}, {"hanzi": "誓死患难与共", "en": "vow to share trials together unto death"}, {"hanzi": "同舟共济患难与共", "en": "in the same boat sharing tribulations"}], "idioms": [{"hanzi": "同甘共苦", "pinyin": "tóng gān gòng kǔ", "meaning_en": "share both sweetness and bitterness; go through thick and thin"}, {"hanzi": "风雨同舟", "pinyin": "fēng yǔ tóng zhōu", "meaning_en": "stand together in the same boat through wind and rain"}, {"hanzi": "肝胆相照", "pinyin": "gān dǎn xiāng zhào", "meaning_en": "show utmost sincerity and devotion; hearts reflecting each other"}, {"hanzi": "生死与共", "pinyin": "shēng sǐ yǔ gòng", "meaning_en": "share life and death together; inseparable unto the grave"}], "character_decomposition": [{"character": "患", "pinyin": "huàn", "meaning_en": "calamity; disaster; suffer; illness", "meaning_es": "calamidad; padecer; infortunio; mal", "radical": "心", "radical_meaning_en": "heart", "meaning_component": "心 (heart weighed down by trouble)", "sound_component": "串 (chuàn, strung through)", "stroke_count": "11", "composition_type": "上下结构", "etymology_and_mnemonic": "Depicts two arrows or obstacles pierced through (串) over the heart (心), signifying deep anxieties and perils.", "visual_mnemonic_story_en": "Troubles pierce like arrows through the heart (心), bringing grief and peril (患).", "visual_mnemonic_story_es": "Las penas atraviesan el corazón (心) como flechas, trayendo aflicción e infortunio (患).", "tone_mnemonic_anchor": "51", "cangjie": "LKP", "traditional": ""}, {"character": "难", "pinyin": "nàn", "meaning_en": "disaster; catastrophe; hardship; adversity", "meaning_es": "desgracia; catástrofe; adversidad; tribulación", "radical": "隹", "radical_meaning_en": "short-tailed bird", "meaning_component": "隹 (bird trapped in distress)", "sound_component": "又 (hand grasping phonetics)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts a distressed bird (隹) caught in adversity; pronounced in 4th tone (nàn) meaning calamity or disaster.", "visual_mnemonic_story_en": "A bird (隹) caught under hardship struggles through catastrophic calamity (难).", "visual_mnemonic_story_es": "Un ave (隹) atrapada en la tormenta lucha por sobrevivir a la catástrofe (难).", "tone_mnemonic_anchor": "51", "cangjie": "EOG", "traditional": "難"}, {"character": "与", "pinyin": "yǔ", "meaning_en": "and; with; together with; give", "meaning_es": "y; con; junto a; dar", "radical": "一", "radical_meaning_en": "one", "meaning_component": "一 (unifying link / hands joining)", "sound_component": "与 (archaic phoneme)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Simplification of traditional 與 depicting multiple hands joining together in mutual cooperation.", "visual_mnemonic_story_en": "A stroke bends round to link two entities into unified companionship (与).", "visual_mnemonic_story_es": "Un trazo fluido enlaza a dos partes en mutua compañía (与).", "tone_mnemonic_anchor": "214", "cangjie": "YSM", "traditional": "與"}, {"character": "共", "pinyin": "gòng", "meaning_en": "common; shared; together; join", "meaning_es": "común; compartido; juntos; unirse", "radical": "八", "radical_meaning_en": "eight / divide", "meaning_component": "廾 (two hands lifting together)", "sound_component": "廿 (twenty/plurality)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Depicts two hands (廾/八) jointly holding and lifting an object together in shared solidarity.", "visual_mnemonic_story_en": "Two hands raised together from below (八) unite to bear a shared destiny.", "visual_mnemonic_story_es": "Dos manos alzadas a la vez (八) se unen para sostener un destino común.", "tone_mnemonic_anchor": "51", "cangjie": "TC", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "岁月如流水般冲刷着人间的喧嚣，唯有患难与共的情谊能抵挡时光的侵蚀。锦上添花者虽众，但当暴风雨降临，能在泥泞中紧握你的双手、共担寒霜的知己，才是生命中最珍贵的奇迹。这种深情，早已超越了言语的界限。", "pinyin": "Suìyuè rú liúshuǐ bān chōngshuā zhe rénjiān de xuānxiāo, wéiyǒu huànnànyǔgòng de qíngyì néng dǐdǎng shíguāng de qīnshí. Jǐnshàngtiānhuā zhě suī zhòng, dàn dāng bàofēngyǔ jiànglín, néng zài nǐnìng zhōng jǐnwò nǐ de shuāngshǒu, gòngdān hánshuāng de zhījǐ, cái shì shēngmìng zhōng zuì zhēnguì de qíjì. Zhè zhǒng shēnqíng, zǎoyǐ chāoyuè le yányǔ de jièxiàn.", "en": "Years wash away mortal clamor like flowing water; only bonds forged in shared hardship withstand time. Flatterers abound, but friends who grip your hand in the mud and share the frost when storms hit are life's rarest miracles, surpassing all words.", "es": "Los años disipan el bullicio humano como agua corriente; solo la amistad que comparte adversidades desafía al tiempo. Sobran quienes halagan en la dicha, pero el amigo que te sostiene en el fango compartiendo el frío es el mayor milagro de la vida."}, {"id": "#2", "hanzi": "在错综复杂的国际局势下，真正的战略伙伴关系建立在患难与共的互信基础之上。面对全球供应链动荡与气候危机，各国唯有摒弃零和思维，携手应对挑战，方能筑牢命运共同体的安全屏障。", "pinyin": "Zài cuòzōngfùzá de guójì júshì xià, zhēnzhèng de zhànlüè huǒbàn guānxì jiànlì zài huànnànyǔgòng de hùxìn jīchǔ zhī shàng. Miànduì quánqiú gōngyìngliàn dòngdàng yǔ qìhòu wēijī, gè guó wéiyǒu bìngqì línghé sīwéi, xiéshǒu yìngduì tiǎozhàn, fāng néng zhùláo mìngyùn gòngtóngtǐ de ānquán píngzhàng.", "en": "In complex geopolitics, genuine strategic partnerships are founded on mutual trust forged through shared hardship. Confronting supply chain turmoil and climate crises, nations must discard zero-sum mindsets and unite to fortify global security.", "es": "En la compleja geopolítica, la auténtica alianza estratégica se cimienta en la confianza mutua que comparte vicisitudes. Frente a la inestabilidad global y la crisis climática, los países deben superar la mentalidad de suma cero y cooperar por la seguridad común."}]}];
